function convert(amount, from, to) {
  const n = parseFloat(amount);
  if (isNaN(n)) return 0;
  if (!RATES[from] || !RATES[to]) return 0;
  const eur = n / RATES[from];
  const result = eur * RATES[to];
  return Math.round(result * 100) / 100;
}
