  cat: "#F5A95C",
  chick: "#FFD24A",
  bear: "#C08B55",
  bunny: "#FFC2D6",
  robot: "#A9C2E0",
  ghost: "#D9CFF7",
  cactus: "#6FC46A",
  octo: "#C47BE8",
  star: "#FFD166",
  // The second ten. Each is the character's own dominant colour, so the
  // speed marks beside it read as belonging to it rather than as a fixed
  // yellow flash stuck on whoever happens to be waving.
  puppy: "#D8A062",
  turtle: "#6FBF80",
  elephant: "#99A0BC",
  lion: "#E0A93C",
  bee: "#F2C53D",
  dino: "#6CC47E",
  moon: "#EDD277",
