function BankAvatar({ bank, size = 48 }) {
  const [failed, setFailed] = useState8(false);
  if (!bank.logo || failed) {
    return <div
      className="rounded-2xl flex items-center justify-center flex-shrink-0 text-white font-bold"
      style={{ width: size, height: size, background: bank.color, fontSize: size * 0.26 }}
    >{bank.initials}</div>;
  }
  return <div
    className="rounded-2xl bg-white flex items-center justify-center flex-shrink-0 overflow-hidden border border-slate-100"
    style={{ width: size, height: size }}
  ><img
    src={bank.logo}
    alt={bank.name}
    onError={() => setFailed(true)}
    className="w-full h-full object-contain p-2"
  /></div>;
}
function GlobeHero({ size = 460 }) {
  const glints = [
    { x: 46, y: 30, d: 0 },
    { x: 62, y: 22, d: 0.4 },
    { x: 71, y: 46, d: 0.9 },
    { x: 55, y: 58, d: 1.4 },
    { x: 38, y: 48, d: 0.7 },
    { x: 80, y: 30, d: 1.8 },
    { x: 66, y: 68, d: 2.2 },
    { x: 30, y: 34, d: 1.1 }
  ];
  const arcs = [
    "M 155,140 Q 260,60 340,105",
    "M 210,190 Q 300,240 380,160",
    "M 140,220 Q 220,290 320,250"
  ];
  return <div className="relative flex-shrink-0" style={{ width: size, height: size }}>{
    /* Sphere with rotating texture */
  }<div
    className="relative w-full h-full rounded-full overflow-hidden"
    style={{
      boxShadow: "0 0 0 1px rgba(255,255,255,0.4), -6px -4px 30px rgba(255,255,255,0.5), inset -30px -20px 70px rgba(10,20,50,0.55), inset 16px 14px 50px rgba(255,255,255,0.25)"
    }}
  ><div // ── THE EARTH TURNS AT THE SPEED AN EARTH TURNS ─────────────────
       // Three seconds for a full rotation, which is roughly 28,000 times
       // real time and reads as a spinning logo rather than a planet.
       // Ninety makes it a slow drift you notice only if you watch, which
       // is what was asked for and is the right register for something
       // sitting behind a headline somebody is trying to read.
       className="absolute inset-0 flex animate-[spinearth_90s_linear_infinite]" style={{ width: "200%" }}><img
    src="https://raw.githubusercontent.com/mrdoob/three.js/dev/examples/textures/planets/earth_atmos_2048.jpg"
    alt=""
    className="w-1/2 h-full object-cover"
    draggable={false}
  /><img
    src="https://raw.githubusercontent.com/mrdoob/three.js/dev/examples/textures/planets/earth_atmos_2048.jpg"
    alt=""
    className="w-1/2 h-full object-cover"
    draggable={false}
  /></div>{
    /* spherical shading for depth + soft light source top-left, like the reference photo */
  }<div
    className="absolute inset-0 pointer-events-none"
    style={{
      background: "radial-gradient(circle at 30% 26%, rgba(255,255,255,0.4) 0%, rgba(255,255,255,0) 32%), radial-gradient(circle at 68% 78%, rgba(3,10,30,0.6) 0%, rgba(3,10,30,0) 55%)"
    }}
  />{
    /* faint blue atmosphere rim */
  }<div
    className="absolute inset-0 rounded-full pointer-events-none"
    style={{ boxShadow: "inset 0 0 40px 6px rgba(120,180,255,0.35)" }}
  />{
    /* connection arcs, drawn over the globe */
  }<svg className="absolute inset-0 w-full h-full pointer-events-none" viewBox="0 0 460 460">{arcs.map((d, i) => <path
    key={i}
    d={d}
    fill="none"
    stroke="rgba(255,255,255,0.55)"
    strokeWidth="1.2"
    strokeDasharray="3 7"
    className="animate-[dashflow_2.4s_linear_infinite]"
    style={{ animationDelay: `${i * 0.3}s` }}
  />)}</svg>{
    /* glinting connection lights */
  }{glints.map((g, i) => <span
    key={i}
    className="absolute rounded-full bg-white animate-[twinkle_2.6s_ease-in-out_infinite]"
    style={{
      left: `${g.x}%`,
      top: `${g.y}%`,
      width: 4,
      height: 4,
      boxShadow: "0 0 6px 2px rgba(255,255,255,0.9)",
      animationDelay: `${g.d}s`
    }}
  />)}</div><style>{`
        @keyframes spinearth { from { transform: translateX(0); } to { transform: translateX(-50%); } }
        @keyframes twinkle { 0%, 100% { opacity: 0.15; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1.3); } }
        @keyframes dashflow { from { stroke-dashoffset: 40; } to { stroke-dashoffset: 0; } }
      `}</style></div>;
}



// src/components/common/iconTile.jsx
//
// THE ICON IN THE BOX, THE NAME UNDER IT.
//
// "I want icon inside, name outside, and this thing everywhere." One
// component for every tile in the app that is an icon with a name —
// Accounts' PayLater / My Assets / My Essentials / About Us, the bills
// row, Pay & Services' quick pay and travel, the bazaar categories, the
// setup screen's pickers. The box holds the picture and nothing else; the
// name sits underneath, outside it, the way a phone's home screen does.
//
// One shape everywhere is the point. The tiles had drifted into five
// layouts — name inside a white card, inside a coloured card, beside the
// icon, under it inside the border — and a person learns one.
function IconTile({
  label,
  onClick,
  ariaLabel,
  children,
  // The box: its side in px, or "100%" to fill the column as a square.
  box = 64,
  radius = 20,
  background,
  selected = false,
  badge = null,
  dimmed = false,
  labelColor,
  disabled = false,
  role,
  ariaChecked,
  ariaPressed,
  labelLines = 2,
  labelSize = 12,
  // With box="100%": a fixed height instead of a square, for a wide box.
  boxHeight = null
}) {
  return <button
    type="button"
    onClick={onClick}
    disabled={disabled}
    aria-label={ariaLabel || label}
    aria-pressed={ariaPressed}
    aria-checked={ariaChecked}
    role={role}
    className="v2-tap"
    style={{
      display: "flex", flexDirection: "column", alignItems: "center", gap: 7, minWidth: 0, width: "100%",
      border: "none", background: "none", padding: 0, cursor: onClick && !disabled ? "pointer" : "default",
      fontFamily: "inherit", opacity: dimmed ? 0.5 : 1
    }}
  ><span style={{
    position: "relative", flexShrink: 0,
    width: box, height: box === "100%" ? (boxHeight || "auto") : box, aspectRatio: box === "100%" && !boxHeight ? "1" : undefined,
    maxWidth: "100%", borderRadius: radius,
    background: background || T.surface,
    // A tinted box is its own surface and needs no lift; a plain white
    // one keeps the card shadow so it still reads as a box on the page.
    boxShadow: selected ? `0 0 0 2px ${T.surface}, 0 0 0 4px ${T.accent}` : (background ? "none" : T.shadowCard),
    display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden",
    transition: "box-shadow 0.15s ease, transform 0.15s ease"
  }}>{children}{badge ? <span style={{ position: "absolute", top: 6, right: 6, zIndex: 2, display: "flex" }}>{badge}</span> : null}</span>{label ? <span style={{
    maxWidth: "100%", fontSize: labelSize, fontWeight: 700, lineHeight: 1.25, textAlign: "center",
    color: labelColor || (selected ? T.accent : T.ink),
    display: "-webkit-box", WebkitLineClamp: labelLines, WebkitBoxOrient: "vertical", overflow: "hidden", overflowWrap: "anywhere"
  }}>{label}</span> : null}</button>;
}


// src/components/common/appLogo.jsx
//
// THE APP LOGO, AND ITS FIVE COLOURS.
//
// The mark is the white "g" the app icon has always carried. The square
// behind it is one of five deep colours the founder picked:
//
//   Indigo #1E1B4B · Slate Gray #2E2E33 · Royal Purple #3B0F63 ·
//   Espresso Brown #3A2E1F · Deep Blue Gray #0F2D3D
//
// THE HOME-SCREEN ICON CANNOT ROTATE, so it is Royal Purple, fixed. A
// phone draws an installed app's icon from the manifest and keeps it:
// iPhone never re-reads it, Android at most about once a day and may ask
// the person first. Everything the app draws itself — the opening splash,
// the browser tab icon, the dashboard's top bar and payment notifications
// — changes colour every two hours instead.
//
// "Random every two hours", and it must be the SAME colour for the app and
// for the service worker, which shows a notification while the app is
// closed and cannot read the app's storage. So the colour is worked out
// from the clock alone: a walk of two-hour steps from 1 January 2026, each
// step a pseudo-random jump of 1 to 4 places round the five. A jump is
// never 0, so the colour never stays the same two slots running, and
// anything that knows the time arrives at the same answer.
