  square: { aspect: 1, outW: 900, outH: 900, round: false, title: "Crop to a square" },
  wide: { aspect: 2, outW: 1400, outH: 700, round: false, title: "Crop the cover" },
  circle: { aspect: 1, outW: 720, outH: 720, round: true, title: "Crop your photo" }
