// ── The GH2H mark ────────────────────────────────────────────────────────
//
// The letters and their colours were local to GH2HFlipCircle, which was fine
// while the tiles were the only thing that drew them. They are module-level
// now because the receive QR paints the same mark in its fourth corner (see
// gloobalQrCornerFace in common/gloobalReceiveQrCard.jsx), and a second copy
// of the four letters is a second thing to remember to change.
//
// flipIcons.jsx is emitted before gloobalReceiveQrCard.jsx in build_app.mjs's
// FRONTEND_MODULES, which matters: these are `var` initialisers, and unlike
// function declarations they do not hoist across the concatenated bundle.
var GH2H_LETTERS = ["G", "H", "2", "H"];
var GH2H_LETTER_COLORS = ["#3B82F6", "#9333EA", "#059669", "#EC4899"];

function GH2HFlipCircle({ size = 40 }) {
  const LETTERS = GH2H_LETTERS;
  const LETTER_COLORS = GH2H_LETTER_COLORS;
  const [step, setStep] = useState9(0);
  const [symbolChar, setSymbolChar] = useState9(() => DIAL_SYMBOLS[Math.floor(Math.random() * DIAL_SYMBOLS.length)]);
  useEffect9(() => {
    const isSymbolStep = step % 2 === 1;
    const duration = (isSymbolStep ? 700 : 1400) * FLIP_SLOW;
    const timer = setTimeout(() => {
      const nextIsSymbolStep = (step + 1) % 2 === 1;
      if (nextIsSymbolStep) {
        setSymbolChar(DIAL_SYMBOLS[Math.floor(Math.random() * DIAL_SYMBOLS.length)]);
      }
      setStep((s) => s + 1);
    }, duration);
    return () => clearTimeout(timer);
  }, [step]);
  const flipped = step % 2 === 1;
  const letterIndex = Math.floor(step / 2) % LETTERS.length;
  const letter = LETTERS[letterIndex];
  const frontColor = LETTER_COLORS[letterIndex];
  const backColor = LETTER_COLORS[(letterIndex + 1) % LETTER_COLORS.length];
  return <div style={{ width: size, height: size, flexShrink: 0, perspective: 400 }}><div
    style={{
      position: "relative",
      width: "100%",
      height: "100%",
      transformStyle: "preserve-3d",
      transition: `transform ${0.5 * FLIP_SLOW}s cubic-bezier(.4,.15,.2,1)`,
      transform: flipped ? "rotateY(180deg)" : "rotateY(0deg)"
    }}
  ><span
    style={{
      position: "absolute",
      inset: 0,
      borderRadius: "50%",
      backfaceVisibility: "hidden",
      background: T.surface,
      border: `2px solid ${frontColor}`,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      transition: "border-color 0.3s ease"
    }}
  ><span style={{ fontSize: size * 0.5, fontWeight: 800, color: frontColor, fontFamily: T.fontDisplay }}>{letter}</span></span><span
    style={{
      position: "absolute",
      inset: 0,
      borderRadius: "50%",
      backfaceVisibility: "hidden",
      transform: "rotateY(180deg)",
      background: backColor,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      transition: "background 0.3s ease"
    }}
  ><span style={{ fontSize: size * 0.42, fontWeight: 800, color: "#fff", fontFamily: T.fontDisplay }}>{symbolChar}</span></span></div></div>;
}
// A small integer derived from a string, stable across renders, reloads and
// devices. Deliberately the plain djb2-style hash rather than anything
// cryptographic: this only has to spread short IDs evenly across a handful
// of buckets.
function flipSeedHash(value) {
  let hash = 5381;
  const text = String(value || "");
  for (let i = 0; i < text.length; i += 1) {
    hash = (hash * 33 + text.charCodeAt(i)) >>> 0;
  }
  return hash;
}
// `seed` freezes the mark: colour and symbol derived from the seed, and —
// note the early return in the effect below — NO animation at all.
//
// NOTHING PASSES IT TODAY, deliberately. It was used on the referral list
// and the transaction rows to give each person one fixed mark, on the
// argument that a list of people needs identity rather than churn. That
// argument was not wrong, but the price was: seeding is the only way to
// stop the flip, so every seeded list went completely still, and the flip
// through the dial-pad symbols is the point of this mark. Reverted on
// request; identity is carried by the name on the row instead.
//
// Kept rather than deleted because the capability is sound and cheap. If it
// is ever wanted again, separate the two concerns first — a seeded mark
// COULD keep flipping and land back on its own face each time, which is the
// version that would not have had to be reverted.
function FlipSymbolCircle({ size = 34, seed }) {
  const DOT_COLORS = ["#2563EB", "#DC2626", "#EA580C", "#059669", "#9333EA", "#DB2777"];
  const seeded = seed !== void 0 && seed !== null && seed !== "";
  const randomColor = (exclude) => {
    let c = DOT_COLORS[Math.floor(Math.random() * DOT_COLORS.length)];
    while (c === exclude) c = DOT_COLORS[Math.floor(Math.random() * DOT_COLORS.length)];
    return c;
  };
  const seedHash = seeded ? flipSeedHash(seed) : 0;
  const [color, setColor] = useState9(() => seeded ? DOT_COLORS[seedHash % DOT_COLORS.length] : randomColor());
  const [symbol, setSymbol] = useState9(
    () => seeded
      // A second, independent slice of the hash, so colour and symbol do not
      // move together — two members who happen to share a colour still
      // differ by symbol.
      ? DIAL_SYMBOLS[(seedHash >>> 8) % DIAL_SYMBOLS.length]
      : DIAL_SYMBOLS[Math.floor(Math.random() * DIAL_SYMBOLS.length)]
  );
  const [flipped, setFlipped] = useState9(false);
  useEffect9(() => {
    if (seeded) return;
    const interval = setInterval(() => {
      setFlipped((f) => !f);
      setSymbol(DIAL_SYMBOLS[Math.floor(Math.random() * DIAL_SYMBOLS.length)]);
      setColor((prev) => randomColor(prev));
      // 3200ms, up from 1600.
      //
      // This mark is not alone on the screen the way the logo box is —
      // a history page draws ten of them at once, each on its own
      // independent timer. At 1.6s with a 0.5s turn, something in the
      // list was mid-flip essentially all of the time, and ten unrelated
      // things twitching behind a column of amounts is noise rather than
      // life. At 3.2s each mark is still for most of its cycle and the
      // list settles between flips.
    }, 3200 * FLIP_SLOW);
    return () => clearInterval(interval);
  }, [seeded]);
  return <span style={{ display: "inline-block", perspective: 200, flexShrink: 0 }}><span
    aria-hidden="true"
    style={{
      position: "relative",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      width: size,
      height: size,
      borderRadius: "50%",
      background: color,
      transformStyle: "preserve-3d",
      // 0.9s, matching the logo box and the 0.00% dots — one turn speed
      // for every flipping mark in the app.
      transition: `transform ${0.9 * FLIP_SLOW}s cubic-bezier(.4,.15,.2,1), background 0.7s ease`,
      transform: flipped ? "rotateY(180deg)" : "rotateY(0deg)"
    }}
  ><span style={{ fontSize: size * 0.42, fontWeight: 800, color: "#fff", transform: flipped ? "rotateY(180deg)" : "none" }}>{symbol}</span></span></span>;
}



// src/components/common/profileAvatar.jsx
//
// The round profile photo every surface that shows a person draws — the scan
// card, the receipt, the notifications list — and the signed-in cache of
// OTHER people's photos read from the server.
//
// ── What counts as a photo ─────────────────────────────────────────────────
//
// Only a `data:image/...` URL. Photos are stored and served as data URLs on
// purpose: the Netlify CSP allows `data:` images but not the API origin, and
// a data URL keeps any canvas it is drawn onto (the shareable receipt image)
// untainted. Anything else — an http URL, a blob, an object — is not drawn.
//
// G_LOGO_DATA_URI is ALSO a data:image URL, and it is what the dashboard has
// long stored as "no photo chosen, use the logo". Drawing it as a photo would
// crop the logo with object-fit: cover onto a plain surface, so it is treated
// as "no photo" and gets the proper fallback instead.
//
// ── The fallback ───────────────────────────────────────────────────────────
//
// The same treatment the dashboard's logo circle uses: the brand gradient
// disc with the Gloobal mark in white (brightness(0) invert(1)), contained,
// with ~12% padding so the mark never touches the edge. Also used when a
// photo fails to decode (onError), so a broken image never shows.

function profileAvatarIsPhoto(photo) {
  return typeof photo === "string" && photo.startsWith("data:image/") && photo !== G_LOGO_DATA_URI;
}

function ProfileAvatar({ photo, name, size = 56, ring }) {
  // Keyed by the src that failed, not a boolean: a new photo arriving after a
  // broken one must get its own chance to load.
  const [failedSrc, setFailedSrc] = useState38(null);
  const showPhoto = profileAvatarIsPhoto(photo) && failedSrc !== photo;
  const displayName = typeof name === "string" && name.trim() ? name.trim() : "GLOOBAL user";
  const ringColor = ring ? (typeof ring === "string" ? ring : "#fff") : null;
  return <span
    data-testid="profile-avatar"
    data-avatar-state={showPhoto ? "photo" : "fallback"}
    style={{
      position: "relative",
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      width: size,
      height: size,
      minWidth: size,
      borderRadius: "50%",
      // The photo is cropped to the circle here, not by the img.
      overflow: "hidden",
      flexShrink: 0,
      boxSizing: "border-box",
      background: showPhoto ? T.surface : T.gradWallet || T.accent,
      boxShadow: ringColor
        ? `0 0 0 2px ${ringColor}, 0 4px 10px rgba(76,29,149,0.16)`
        : "0 4px 10px rgba(76,29,149,0.16)"
    }}
  >{showPhoto
    ? <img
        src={photo}
        alt={`${displayName} profile photo`}
        width={size}
        height={size}
        onError={() => setFailedSrc(photo)}
        style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
      />
    : <img
        src={G_LOGO_DATA_URI}
        alt="Gloobal"
        width={size}
        height={size}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "contain",
          padding: Math.max(2, Math.round(size * 0.12)),
          boxSizing: "border-box",
          display: "block",
          filter: "brightness(0) invert(1)"
        }}
      />}</span>;
}

// ── Counterparty photos ────────────────────────────────────────────────────
//
// symbolId → photo (string) | null (known: no photo) | Promise (in flight).
// One request per Gloobal ID per session, however many rows, receipts and
// cards ask at once: a second caller while the first is in flight gets the
// same promise.
//
// A FAILED read (cold start, offline, 5xx) is not cached — the entry is
// dropped so the next caller asks again — and resolves null for this caller.
// Caching it as null would hide somebody's photo for the rest of the session
// because the server was waking up the first time it was asked.
var COUNTERPARTY_PHOTO_CACHE = new Map();

function counterpartyPhotoKey(symbolId) {
  return typeof symbolId === "string" ? symbolId.trim() : "";
}

// undefined = not known yet (absent or in flight); otherwise photo | null.
function counterpartyPhotoPeek(key) {
  if (!key || !COUNTERPARTY_PHOTO_CACHE.has(key)) return undefined;
  const value = COUNTERPARTY_PHOTO_CACHE.get(key);
  return value && typeof value.then === "function" ? undefined : value;
}

// Usable outside React (the receipt image draws with it).
function loadCounterpartyPhoto(symbolId) {
  const key = counterpartyPhotoKey(symbolId);
  if (!key) return Promise.resolve(null);
  if (COUNTERPARTY_PHOTO_CACHE.has(key)) {
    const cached = COUNTERPARTY_PHOTO_CACHE.get(key);
    return cached && typeof cached.then === "function" ? cached : Promise.resolve(cached);
  }
  const pending = Promise.resolve()
    .then(() => GloobalApi.getUserPhoto(key))
    .then(
      (photo) => {
        const value = profileAvatarIsPhoto(photo) ? photo : null;
        // Only if this request is still the one on record — a sign-out
        // (clearCounterpartyPhotoCache) mid-flight must not be undone by it.
        if (COUNTERPARTY_PHOTO_CACHE.get(key) === pending) COUNTERPARTY_PHOTO_CACHE.set(key, value);
        return value;
      },
      () => {
        if (COUNTERPARTY_PHOTO_CACHE.get(key) === pending) COUNTERPARTY_PHOTO_CACHE.delete(key);
        return null;
      }
    );
  COUNTERPARTY_PHOTO_CACHE.set(key, pending);
  return pending;
}

// Sign-out: the next account must not see photos fetched under the last one.
function clearCounterpartyPhotoCache() {
  COUNTERPARTY_PHOTO_CACHE.clear();
}

function useCounterpartyPhoto(symbolId) {
  const key = counterpartyPhotoKey(symbolId);
  // The outcome of this hook's own load, for the case the cache cannot answer
  // afterwards (a failed read is deliberately not cached).
  const [settled, setSettled] = useState37({ key: null, photo: null });
  useEffect27(() => {
    if (!key || counterpartyPhotoPeek(key) !== undefined) return undefined;
    let alive = true;
    loadCounterpartyPhoto(key).then((photo) => {
      if (alive) setSettled({ key, photo });
    });
    return () => {
      alive = false;
    };
  }, [key]);
  if (!key) return { photo: null, loading: false };
  const cached = counterpartyPhotoPeek(key);
  if (cached !== undefined) return { photo: cached, loading: false };
  if (settled.key === key) return { photo: settled.photo, loading: false };
  return { photo: null, loading: true };
}


// src/components/common/shareLink.js
//
// SHARING A GLOOBAL LINK SO IT ARRIVES AS A LINK.
//
// "Share is a text, not a link." Two separate faults produced that:
//
//   1. The creator profile's Share sent "Pay me on Gloobal at rasoi.ghar"
//      and nothing else — no address at all, so there was nothing to tap.
//   2. The QR card passed the address in `url` AND inside `text`. What a
//      receiving app does with those two fields is up to the app: some
//      keep only `text`, some only `url`, some join them, and a picture
//      shared with `files` has its `url` dropped by most Android targets.
//
// So the link always travels INSIDE the message, on its own line at the
// end — the one place every messenger (WhatsApp, Telegram, SMS, Gmail)
// turns into a tappable link — and `url` is never set separately, which
// is what made it appear twice or not at all.
//
// The order of attempts, each falling through only when the one before is
// refused (a person closing the sheet is a choice, not a failure):
//   1. the picture, when there is one and this phone can share files;
//   2. the message with the link;
//   3. copy the message, and say so.
function gloobalShareMessage(message, url) {
  const m = String(message || "").trim();
  return url ? (m ? `${m}\n${url}` : url) : m;
}

async function gloobalShareLink({ title = "", message = "", url = "", file = null, onToast } = {}) {
  const text = gloobalShareMessage(message, url);
  const nav = typeof navigator !== "undefined" ? navigator : null;
  if (file && nav && typeof nav.canShare === "function" && typeof nav.share === "function") {
    try {
      if (nav.canShare({ files: [file] })) {
        await nav.share({ files: [file], title, text });
        return "shared";
      }
    } catch (error) {
      if (error && error.name === "AbortError") return "cancelled";
      // A refused picture still has a link to send — fall through.
    }
  }
  if (nav && typeof nav.share === "function") {
    try {
      await nav.share(title ? { title, text } : { text });
      return "shared";
    } catch (error) {
      if (error && error.name === "AbortError") return "cancelled";
    }
  }
  try {
    await nav.clipboard.writeText(text);
    if (onToast) onToast("Link copied");
    return "copied";
  } catch (error) {
    if (onToast) onToast(url || "Couldn't share right now");
    return "failed";
  }
}


// src/components/common/gloobalAnimalQr.js
//
// ── Animal QR: a picture inside the code, every module still readable ─────
//
// A scanner does not look at a whole module. It samples each module near its
// CENTRE and decides dark or light. So the rest of each module is free to
// paint a picture, as long as every centre still says what the data says.
// That is the whole trick, and these are its rules:
//
//   - Finder, timing and alignment patterns stay solid black squares. They
//     are how a phone finds the code at all; nothing is drawn over them.
//   - Outside the animal, a dark module is a black dot (90% of the module).
//   - Inside the animal, every module is filled with the animal's colour, and
//     a LIGHT module gets a white dot (70%) in its centre. The colour is dark
//     enough to read as "dark" to a scanner (luminance <= 80, the same floor
//     gloobalQrDiscInk uses), so a dark module stays dark and a light one
//     stays light at the one point that counts.
//
// Measured before this was built, with three different users' pay links at
// six sizes and four blur levels: every animal reads on jsQR within a scan or
// two of a plain QR with no picture, and 36/36 on WeChat's decoder and zbar.
// tests/gloobal-animal-qr.test.mjs decodes every animal again on every run.
//
// The code is always version 6 with error correction H, so every pay link
// lands in the same 41-module grid the pictures were fitted to. A payload that
// does not fit returns null, and the card falls back to the plain QR.
