function gloobalAnimalQrFind(key) {
  return GLOOBAL_QR_ANIMALS.find((a) => a.key === key) || null;
}

// The animal's colour, darkened until a scanner reads it as dark. Scaled
// rather than mixed with black, so the hue survives.
function gloobalAnimalQrInk(hex) {
  const raw = String(hex || "").replace("#", "");
  if (raw.length !== 6) return "#3B0764";
  let r = parseInt(raw.slice(0, 2), 16);
  let g = parseInt(raw.slice(2, 4), 16);
  let b = parseInt(raw.slice(4, 6), 16);
  const lum = () => 0.2126 * r + 0.7152 * g + 0.0722 * b;
  let guard = 0;
  while (lum() > GLOOBAL_ANIMAL_QR_MAX_LUM && guard < 40) {
    r = Math.round(r * 0.92);
    g = Math.round(g * 0.92);
    b = Math.round(b * 0.92);
    guard += 1;
  }
  return "#" + [r, g, b].map((n) => Math.max(0, Math.min(255, n)).toString(16).padStart(2, "0")).join("");
}

// Everything needed to draw one animal code, in module units (quiet zone
// included), so the SVG and the PNG are drawn from the same list and cannot
// disagree about what the code is.
//
//   squares:   solid black function-pattern modules
//   dots:      black data dots outside the animal
//   fill:      modules painted in the animal's colour
//   holes:     white dots on light modules inside the animal
//
// Returns null when the payload does not fit version 6 at H, or the animal is
// unknown — the caller then draws the plain QR instead.
function gloobalAnimalQrLayout(text, animalKey) {
  const animal = gloobalAnimalQrFind(animalKey);
  if (!animal || typeof uqrEncode !== "function") return null;
  let qr;
  try {
    qr = uqrEncode(text, {
      ecc: "H",
      border: 0,
      minVersion: GLOOBAL_ANIMAL_QR_VERSION,
      maxVersion: GLOOBAL_ANIMAL_QR_VERSION
    });
  } catch {
    return null;
  }
  if (!qr || qr.size !== GLOOBAL_ANIMAL_QR_SIZE || !qr.types) return null;
  const q = GLOOBAL_ANIMAL_QR_QUIET;
  const inAnimal = (x, y) => {
    const row = animal.rows[y - animal.y];
    return !!row && row[x - animal.x] === "#";
  };
  const squares = [];
  const dots = [];
  const fill = [];
  const holes = [];
  for (let y = 0; y < qr.size; y++) {
    for (let x = 0; x < qr.size; x++) {
      const dark = !!qr.data[y][x];
      // types: 0 is a data/ecc module; anything else is a function pattern.
      if (qr.types[y][x] !== 0) {
        if (dark) squares.push([x + q, y + q]);
        continue;
      }
      if (inAnimal(x, y)) {
        fill.push([x + q, y + q]);
        if (!dark) holes.push([x + q, y + q]);
      } else if (dark) {
        dots.push([x + q, y + q]);
      }
    }
  }
  return {
    total: qr.size + q * 2,
    color: gloobalAnimalQrInk(animal.color),
    squares,
    dots,
    fill,
    holes
  };
}

// The person's saved choice: an animal key or "classic". Storage can be
// missing or throw (private windows); the default is simply used then.
function gloobalAnimalQrLoadChoice() {
  try {
    const saved = typeof localStorage !== "undefined" ? localStorage.getItem(GLOOBAL_ANIMAL_QR_STORAGE_KEY) : null;
    if (saved === "classic" || gloobalAnimalQrFind(saved)) return saved;
  } catch {
  }
  return GLOOBAL_ANIMAL_QR_DEFAULT;
}

// One of the cast, at random. For the shop code opened from the Creator
// Profile: "when I tap it out of creator side qrs i get one random with
// big size". A random pick is not saved — it is a picture of the moment,
// and the next tap gives another.
function gloobalAnimalQrRandom() {
  const cast = GLOOBAL_QR_ANIMALS;
  if (!cast.length) return "classic";
  return cast[Math.floor(Math.random() * cast.length)].key;
}

function gloobalAnimalQrSaveChoice(choice) {
  try {
    if (typeof localStorage !== "undefined") localStorage.setItem(GLOOBAL_ANIMAL_QR_STORAGE_KEY, choice);
  } catch {
  }
}

// Paints a layout onto a 2D canvas context at `scale` pixels per module.
// Integer scales keep module edges on pixel edges, so nothing blurs.
function gloobalAnimalQrPaint(ctx, layout, scale) {
  const s = scale;
  ctx.fillStyle = "#FFFFFF";
  ctx.fillRect(0, 0, layout.total * s, layout.total * s);
  ctx.fillStyle = "#000000";
  for (const [x, y] of layout.squares) ctx.fillRect(x * s, y * s, s, s);
  ctx.fillStyle = layout.color;
  for (const [x, y] of layout.fill) ctx.fillRect(x * s, y * s, s, s);
  const dot = (list, d, color) => {
    ctx.fillStyle = color;
    for (const [x, y] of list) {
      ctx.beginPath();
      ctx.arc((x + 0.5) * s, (y + 0.5) * s, (d * s) / 2, 0, Math.PI * 2);
      ctx.fill();
    }
  };
  dot(layout.dots, GLOOBAL_ANIMAL_QR_OUT_DOT, "#000000");
  dot(layout.holes, GLOOBAL_ANIMAL_QR_IN_DOT, "#FFFFFF");
}


// src/components/common/gloobalReceiveQrCard.jsx
// "Your Gloobal QR": a plain, static, UPI-style receive code. The payload is
// the pay link from backend/utils/gloobalPayLink.js — an account, no amount,
// no session — so the same code works printed, screenshotted or shared.
//
// The symbol is deliberately ordinary: square modules, standard finders,
// error-correction H, a 4-module quiet zone, and a small logo badge sized by
// GLOOBAL_QR_LOGO_FRACTION (≈7% of the area, well inside what H recovers).
// Every styling liberty a QR takes costs some phone somewhere a failed scan;
// this one takes one.
//
// ── The badge: white ring, coloured disc, white mark ─────────────────────
//
// The centre was a white rounded SQUARE with the logo in its own colours. It
// is now a circle, the mark is knocked out white, and the disc cycles through
// the brand palette every two seconds.
//
// The white ring is not decoration and is the reason this is safe. Whatever
// the disc's colour, the modules underneath it are gone and error correction
// has to rebuild them either way — but a DARK disc sitting straight against
// dark modules merges with them, and a decoder that cannot find the grid's
// edge fails to locate the code rather than misreading it. Keeping the white
// ring leaves the light gap the old square provided, and the circle inscribed
// in the same box covers 78.5% of what the square did, so this change
// strictly reduces the number of modules lost.

var GLOOBAL_QR_QUIET_ZONE = 4;

function buildGloobalQrMatrix(text) {
  try {
    // `types` is uqr's per-module role map: 0 is a data or error-correction
    // module, anything else is a function pattern (finder, timing,
    // alignment, format). The classic style draws the two differently — see
    // gloobalQrClassicLayout — so it is read here rather than re-derived
    // from coordinates later.
    const { size, data, types } = uqrEncode(text, { ecc: "H", border: 0 });
    return { size, data, types };
  } catch {
    return null;
  }
}

// The dot, as a fraction of a module.
//
// Deliberately the SAME constant the animal codes use, not a second one with
// the same value: the two styles are now one drawing language, and a dot
// that drifted in only one of them would be a difference nobody chose.
var GLOOBAL_QR_DOT = GLOOBAL_ANIMAL_QR_OUT_DOT;

// Split a plain code into the two things that get drawn differently.
//
// Function patterns — the three finders, the timing lines, the alignment
// block, the format strips — stay SOLID SQUARES. They are what a decoder
// locates the code by: it looks for the 1:1:3:1:1 run of dark and light
// across a finder, and rounding those modules narrows every dark run at its
// edges. Breaking them is how a pretty QR becomes an unscannable one.
//
// Data and error-correction modules become dots. A decoder samples those at
// the module's CENTRE, which a centred dot covers completely, so the shape
// of their corners costs nothing the sampler reads.
//
// Exactly the division gloobalAnimalQrLayout already makes (it also carves
// out the animal); this is that same rule with no picture in the middle.
function gloobalQrClassicLayout(matrix) {
  const q = GLOOBAL_QR_QUIET_ZONE;
  const squares = [];
  const dots = [];
  const types = matrix.types;
  for (let y = 0; y < matrix.size; y++) {
    for (let x = 0; x < matrix.size; x++) {
      if (!matrix.data[y][x]) continue;
      // No types map (an older uqr, or a shape this build does not expect):
      // every dark module stays a square. The code is then exactly what it
      // was before, which is the right way to lose a decoration.
      const functional = !types || !types[y] || types[y][x] !== 0;
      (functional ? squares : dots).push([x + q, y + q]);
    }
  }
  return { squares, dots };
}

// One module as a square, and one as a circle. Both styles draw through
// these, so a change to the drawing language reaches the whole app.
function gloobalQrRectPath(list) {
  return list.map(([x, y]) => `M${x} ${y}h1v1h-1z`).join("");
}
function gloobalQrDotPath(list, diameter) {
  const r = diameter / 2;
  return list.map(([x, y]) => `M${x + 0.5 - r} ${y + 0.5}a${r} ${r} 0 1 0 ${2 * r} 0a${r} ${r} 0 1 0 ${-2 * r} 0z`).join("");
}

// The logo square, in modules, measured in the full (quiet-zone included)
// coordinate space. One helper so the SVG and the PNG draw the same square.
function gloobalQrLogoBox(size) {
  const total = size + GLOOBAL_QR_QUIET_ZONE * 2;
  const side = size * GLOOBAL_QR_LOGO_FRACTION;
  const offset = (total - side) / 2;
  const cx = offset + side / 2;
  // ring: the white halo, inscribed in the old square's box.
  // disc: the coloured badge inside it.
  // mark: the logo inside that.
  return {
    total, side, x: offset, y: offset, cx, cy: cx,
    ring: side / 2,
    disc: side / 2 * 0.84,
    mark: side / 2 * 0.84 * 1.06
  };
}

// ── The fourth corner ────────────────────────────────────────────────────
//
// Three corners of a QR carry finder patterns; the fourth carries nothing,
// and the GH2H mark from the Send and Receive tiles goes there.
//
// WHERE it goes was measured, not chosen. Centred on the symbol's own
// bottom-right 7×7 block — the position that mirrors a finder exactly — it
// lands on the version 5 alignment pattern, the 5×5 block centred two modules
// in from that corner. A decoder uses that pattern to correct perspective, so
// covering it does not cost error-correction capacity, it costs localisation:
// across 192 rasters (8 badge colours × 6 module scales × 4 blur levels) the
// bare code decoded 176 times, the mark on the block 138, and a SOLID dark
// mark on the block only 73.
//
// Moved two modules out, so its inner edge clears the alignment pattern and
// its outer edge overhangs into the quiet zone, the same 7-module circle
// decoded 184/192 — no worse than the code with no mark on it at all. That is
// the geometry below.
//
// It is also why the mark is mostly WHITE. A light badge reads to a decoder
// as a light region; a dark one merges with the modules around it, which is
// the difference between 184 and 73.
// Anchored by its OUTER edge, not its centre: the overhang past the symbol
// is what sets the mark in the corner, so resizing it should not slide it
// diagonally away. EDGE is how far past the symbol's own edge it reaches, in
// modules, out of a 4-module quiet zone.
//
// R was 3.5 — a 7-module circle, the size of a finder pattern — and read as
// a fourth finder rather than as a mark. At 2.8 it covers 64% of that area
// and still clears the alignment pattern by more than it did before, since
// shrinking it from a fixed outer edge only moves its inner edge outward.
// Measured at 176/192, which is the bare code's own rate: 3.1, 2.8, 2.5 and
// 2.2 all scored exactly that, so this is a free choice among sizes that
// cost the scan nothing.
var GLOOBAL_QR_CORNER_EDGE = 1.5;
// Then cut to 1.6 on request: the mark should read like a © beside the code,
// a little larger than one, not like a badge on it. Same fixed outer edge, so
// it sits tucked into the corner and covers fewer modules than before.
var GLOOBAL_QR_CORNER_R = 1.6;

// `size` is the code's own module count, without its quiet zone. `quiet`
// defaults to this file's, and is a parameter because the animal codes carry
// their own constant (GLOOBAL_ANIMAL_QR_QUIET) — the two happen to be 4
// today, and a shared mark that silently depended on that would be a bug
// waiting for somebody to widen one of them.
function gloobalQrCornerBadge(size, quiet) {
  const q = Number.isFinite(quiet) ? quiet : GLOOBAL_QR_QUIET_ZONE;
  const total = size + q * 2;
  const edge = q + size;
  const r = GLOOBAL_QR_CORNER_R;
  const c = edge + GLOOBAL_QR_CORNER_EDGE - r;
  return {
    total,
    cx: c,
    cy: c,
    r,
    // The ring, at the same fraction of the diameter as the 2px border on the
    // 22px GH2HFlipCircle the tiles draw.
    stroke: r * 2 * 0.09,
    // The letter inside it. Was r * 1.2 — 60% of the disc's diameter, which
    // is how a badge is lettered, not how a © is. At that size the glyph
    // ran up against the ring and the two read as one blob at the size this
    // mark is actually seen: a few millimetres on a printed code, and
    // smaller than a fingernail on a phone. Smaller letter, same disc, so
    // the mark covers exactly the modules it covered before and the scan
    // numbers below it are unaffected.
    font: r * 0.95
  };
}

// The mark's cycle comes from GH2H_LETTERS / GH2H_LETTER_COLORS in
// components/common/flipIcons.jsx — the same two arrays GH2HFlipCircle draws
// on the Send and Receive tiles. They are read here rather than restated:
// this IS that mark, and a second copy of the four letters is a second thing
// to remember to change.
//
// One difference, and it is deliberate. The tile's mark alternates each
// letter with a random dial symbol. This one does not: on something people
// photograph, a mark that spends half its life showing a stray "×" reads as
// noise ON the code rather than as a wordmark beside it.
function gloobalQrCornerFace(step) {
  const letters = typeof GH2H_LETTERS !== "undefined" ? GH2H_LETTERS : ["G", "H", "2", "H"];
  const colors = typeof GH2H_LETTER_COLORS !== "undefined"
    ? GH2H_LETTER_COLORS
    : ["#3B82F6", "#9333EA", "#059669", "#EC4899"];
  const i = ((Math.floor(step) % letters.length) + letters.length) % letters.length;
  return {
    letter: letters[i],
    // Through the same darkener the centre disc uses. These four were drawn
    // to sit ON white, not to be read against it — #3B82F6 measures 2.03:1 —
    // and the ring and the letter here are both a graphic on white.
    color: gloobalQrDiscInk(colors[i % colors.length])
  };
}

// A brand colour, darkened until a WHITE mark on it clears 3:1.
//
// Measured on the palette this cycles through: seven of the eight fail that
// floor as authored — #0891B2 is 2.11:1, #059669 2.15:1, #EA580C 2.19:1 —
// because they were chosen to sit on white, not to carry white. Only #DC2626
// passes untouched. Rather than hand-pick a second palette that drifts from
// the first, each colour is scaled down until it measures, so adding a colour
// to LOGO_FLIP_COLORS cannot quietly reintroduce an unreadable badge.
//
// 3:1 is the floor for a graphic that has to be read, and this mark is the
// one thing on the code a person looks at deliberately.
var GLOOBAL_QR_DISC_MAX_LUM = 80;

function gloobalQrDiscInk(hex) {
  const raw = String(hex || "").replace("#", "");
  if (raw.length !== 6) return "#4C1D95";
  let r = parseInt(raw.slice(0, 2), 16);
  let g = parseInt(raw.slice(2, 4), 16);
  let b = parseInt(raw.slice(4, 6), 16);
  const lum = () => 0.2126 * r + 0.7152 * g + 0.0722 * b;
  // Scaled rather than blended toward black: scaling keeps the hue and the
  // saturation, so the badge stays recognisably that brand colour instead of
  // walking toward grey.
  let guard = 0;
  while (lum() > GLOOBAL_QR_DISC_MAX_LUM && guard < 40) {
    r = Math.round(r * 0.92);
    g = Math.round(g * 0.92);
    b = Math.round(b * 0.92);
    guard += 1;
  }
  return "#" + [r, g, b].map((n) => Math.max(0, Math.min(255, n)).toString(16).padStart(2, "0")).join("");
}

// ── The corner mark, drawn once for everything that carries it ───────────
//
// Four things draw a Gloobal code: this file's two SVGs (the standard one
// and an animal) and the two canvas paths behind Share. The mark used to
// exist in two of them, written out twice; the animal code had neither, on
// the reasoning that the picture is the decoration and anything painted
// over it costs modules it was placed to keep.
//
// That reasoning was about the CENTRE badge, which sits on the code, and it
// still holds — an animal has no centre disc. It does not reach the corner
// mark, which sits almost entirely in the quiet zone: of its 3.2 modules
// across, 1.5 are outside the code's last column and about 1.7 overlap it,
// at the one corner a QR has no finder pattern in. That overlap is what was
// measured at 176/192 on the standard code, and tests/gloobal-animal-qr
// decodes every animal with it painted on before this ships.
//
// So the mark belongs on all four, and it is written once. Two renderers,
// same geometry, same face:
//
// ── OFF, BY REQUEST ──────────────────────────────────────────────────
// The founder asked for the mark in the bottom-right corner to go: the
// card already says GLOOBAL in its title, and the hallmark sits top left.
// Switched off here for all four renderers at once; flip it back to true
// and every code carries it again.
var GLOOBAL_QR_CORNER_MARK_ON = false;

function GloobalQrCornerMark({ corner, face }) {
  if (!GLOOBAL_QR_CORNER_MARK_ON) return null;
  return (
    <g aria-hidden="true">
      {/* The white disc is painted first and full size, so the modules
          under the mark are gone rather than showing through the ring. */}
      <circle cx={corner.cx} cy={corner.cy} r={corner.r} fill="#FFFFFF" />
      <circle
        cx={corner.cx}
        cy={corner.cy}
        r={corner.r - corner.stroke / 2}
        fill="none"
        stroke={face.color}
        strokeWidth={corner.stroke}
        style={{ transition: "stroke 0.55s ease" }}
      />
      <text
        x={corner.cx}
        y={corner.cy}
        textAnchor="middle"
        dominantBaseline="central"
        fontFamily={typeof T !== "undefined" ? T.fontDisplay : "system-ui, sans-serif"}
        fontSize={corner.font}
        fontWeight="800"
        fill={face.color}
        style={{ transition: "fill 0.55s ease" }}
      >
        {face.letter}
      </text>
    </g>
  );
}

// The same mark onto a 2D context, at `scale` pixels per module.
function gloobalQrPaintCornerMark(ctx, corner, face, scale) {
  if (!GLOOBAL_QR_CORNER_MARK_ON) return;
  ctx.beginPath();
  ctx.arc(corner.cx * scale, corner.cy * scale, corner.r * scale, 0, Math.PI * 2);
  ctx.fillStyle = "#FFFFFF";
  ctx.fill();
  ctx.beginPath();
  ctx.arc(corner.cx * scale, corner.cy * scale, (corner.r - corner.stroke / 2) * scale, 0, Math.PI * 2);
  ctx.strokeStyle = face.color;
  ctx.lineWidth = corner.stroke * scale;
  ctx.stroke();
  ctx.fillStyle = face.color;
  ctx.font = `800 ${corner.font * scale}px ${typeof T !== "undefined" ? T.fontDisplay : "system-ui, sans-serif"}`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(face.letter, corner.cx * scale, corner.cy * scale);
}

// ── THE HALLMARK, BESIDE THE CODE RATHER THAN ONLY INSIDE IT ───────────
//
// The founder asked for this mark to sit on the left of the card, facing
// My Share across the title. Inside the code it cannot: a QR leaves
// exactly one corner free — the bottom-right — because the other three
// carry the finder squares a scanner locks onto, and a mark moved onto one
// of those is a code that may not read. So it is drawn at card level, in
// the header row's left cell, which was an empty spacer.
//
// It is GH2HFlipCircle — the app's own mark, the one already turning on
// the Send and Receive tiles — rather than a still copy of it. The founder
// asked for "symbols and colour in hallmark flip", and that is precisely
// what that component is: a coloured letter on white, flipping to a dial
// symbol on a coloured face, G → H → 2 → H with a different symbol between
// each.
//
// Which settles a question the first version of this got wrong by
// omission. The mark INSIDE the code deliberately shows letters only —
// see gloobalQrCornerFace — because on something people photograph, a
// mark spending half its life showing a stray "×" reads as noise ON the
// code. That reasoning is about being on the code. This one is beside it,
// on the card, in exactly the context the tiles are in, so the rule that
// applies to it is the tiles' rule and not the code's.
//
// Reusing the component rather than restating its letters and colours is
// the other half: a second copy of G/H/2/H is a second thing to remember
// to change.
var GLOOBAL_QR_HALLMARK_SIZE = 28;

function GloobalQrSvg({ value, logo = true, discColor, markStep = 0 }) {
  const matrix = buildGloobalQrMatrix(value);
  if (!matrix) return null;
  const layout = gloobalQrClassicLayout(matrix);
  const box = gloobalQrLogoBox(matrix.size);
  const corner = gloobalQrCornerBadge(matrix.size);
  const face = gloobalQrCornerFace(markStep);
  return (
    <svg
      viewBox={`0 0 ${box.total} ${box.total}`}
      width="100%"
      height="100%"
      role="img"
      aria-label="Gloobal QR code"
      style={{ display: "block" }}
    >
      <rect x="0" y="0" width={box.total} height={box.total} fill="#FFFFFF" />
      {/* Function patterns square and crisp; data modules as dots. The dots
          get no crispEdges — rounding them to the pixel grid is what would
          make them look like squares again at small sizes. */}
      <path d={gloobalQrRectPath(layout.squares)} fill="#000" shapeRendering="crispEdges" />
      <path d={gloobalQrDotPath(layout.dots, GLOOBAL_QR_DOT)} fill="#000" />
      {logo ? (
        <g>
          <circle cx={box.cx} cy={box.cy} r={box.ring} fill="#FFFFFF" />
          <circle
            cx={box.cx}
            cy={box.cy}
            r={box.disc}
            fill={gloobalQrDiscInk(discColor || (typeof T !== "undefined" ? T.accent : "#7C3AED"))}
            style={{ transition: "fill 0.55s ease" }}
          />
          <image
            href={G_LOGO_DATA_URI}
            x={box.cx - box.mark / 2}
            y={box.cy - box.mark / 2}
            width={box.mark}
            height={box.mark}
            preserveAspectRatio="xMidYMid meet"
            // Knocked out white. The mark's own blues would disappear into a
            // blue disc and fight a green one; white is the only fill that
            // works against all eight.
            style={{ filter: "brightness(0) invert(1)" }}
          />
        </g>
      ) : null}
      {/* The fourth corner — see gloobalQrCornerBadge for why it sits tucked
          into the quiet zone rather than on the code. */}
      {logo ? <GloobalQrCornerMark corner={corner} face={face} /> : null}
    </svg>
  );
}

// An animal code, drawn from gloobalAnimalQrLayout. No centre badge — the
// picture is the decoration, and a disc through the middle of it would cost
// the modules the animal was placed to keep, as well as the animal.
//
// It does carry the corner mark now. That is a different argument from the
// centre one: the mark sits in the quiet zone at the corner with no finder
// pattern, overlapping about 1.7 modules, and every animal is decoded with
// it painted on in tests/gloobal-animal-qr.test.mjs. A code is a code — the
// hallmark is how you know whose it is, and an animal is no less ours.
function GloobalAnimalQrSvg({ layout, label, markStep = 0 }) {
  // The same two path builders the classic style draws through — see
  // gloobalQrRectPath / gloobalQrDotPath. They used to be defined here, and
  // a second copy of a module's shape is exactly how two styles of the same
  // code start to differ by accident.
  const rects = gloobalQrRectPath;
  const dots = gloobalQrDotPath;
  // The animal layout publishes `total` (code plus both quiet zones); the
  // badge wants the code's own size and the quiet zone it sits in.
  const corner = gloobalQrCornerBadge(
    layout.total - GLOOBAL_ANIMAL_QR_QUIET * 2,
    GLOOBAL_ANIMAL_QR_QUIET
  );
  const face = gloobalQrCornerFace(markStep);
  return (
    <svg
      viewBox={`0 0 ${layout.total} ${layout.total}`}
      width="100%"
      height="100%"
      role="img"
      aria-label="Gloobal QR code"
      data-qr-style="animal"
      data-qr-animal={label || undefined}
      style={{ display: "block" }}
    >
      <rect x="0" y="0" width={layout.total} height={layout.total} fill="#FFFFFF" />
      <path d={rects(layout.squares)} fill="#000" shapeRendering="crispEdges" />
      <path d={rects(layout.fill)} fill={layout.color} shapeRendering="crispEdges" />
      <path d={dots(layout.dots, GLOOBAL_ANIMAL_QR_OUT_DOT)} fill="#000" />
      <path d={dots(layout.holes, GLOOBAL_ANIMAL_QR_IN_DOT)} fill="#FFFFFF" />
      <GloobalQrCornerMark corner={corner} face={face} />
    </svg>
  );
}

// The same symbol as a PNG, for sharing. Integer pixels per module so no
// module edge lands between pixels and blurs.
function gloobalQrToPngBlob(value, { moduleScale = 12, discColor, markStep = 0, animal = null } = {}) {
  return new Promise((resolve) => {
    try {
      // The animal code, when one is chosen and the link fits it: the same
      // layout the screen shows, painted at an integer scale.
      const animalLayout = animal ? gloobalAnimalQrLayout(value, animal) : null;
      if (animalLayout && typeof document !== "undefined") {
        const scale = Math.max(1, Math.round(moduleScale));
        const canvas = document.createElement("canvas");
        canvas.width = canvas.height = animalLayout.total * scale;
        const ctx = canvas.getContext("2d");
        if (!ctx) return resolve(null);
        gloobalAnimalQrPaint(ctx, animalLayout, scale);
        // The hallmark goes on the shared picture too. gloobalAnimalQrPaint
        // itself stays untouched: it lives in gloobalAnimalQr.js, which the
        // decode suite loads on its own with nothing else in scope, and the
        // mark's geometry lives here. So it is painted over the top, which
        // is also the order the SVG draws it in.
        gloobalQrPaintCornerMark(
          ctx,
          gloobalQrCornerBadge(animalLayout.total - GLOOBAL_ANIMAL_QR_QUIET * 2, GLOOBAL_ANIMAL_QR_QUIET),
          gloobalQrCornerFace(markStep),
          scale
        );
        return canvas.toBlob((blob) => resolve(blob || null), "image/png");
      }
      const matrix = buildGloobalQrMatrix(value);
      if (!matrix || typeof document === "undefined") return resolve(null);
      const scale = Math.max(1, Math.round(moduleScale));
      const box = gloobalQrLogoBox(matrix.size);
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = box.total * scale;
      const ctx = canvas.getContext("2d");
      if (!ctx) return resolve(null);

      ctx.fillStyle = "#FFFFFF";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      // The same split the SVG draws, from the same helper: squares for the
      // function patterns, dots for the data. A PNG that still came out in
      // solid squares would mean the code somebody SHARES does not look like
      // the one they were shown.
      const classic = gloobalQrClassicLayout(matrix);
      ctx.fillStyle = "#000000";
      for (const [x, y] of classic.squares) ctx.fillRect(x * scale, y * scale, scale, scale);
      const dotR = GLOOBAL_QR_DOT / 2 * scale;
      for (const [x, y] of classic.dots) {
        ctx.beginPath();
        ctx.arc((x + 0.5) * scale, (y + 0.5) * scale, dotR, 0, Math.PI * 2);
        ctx.fill();
      }

      // The same badge the SVG draws: white ring, coloured disc, white mark.
      const cx = box.cx * scale;
      ctx.beginPath();
      ctx.arc(cx, cx, box.ring * scale, 0, Math.PI * 2);
      ctx.fillStyle = "#FFFFFF";
      ctx.fill();
      ctx.beginPath();
      ctx.arc(cx, cx, box.disc * scale, 0, Math.PI * 2);
      ctx.fillStyle = gloobalQrDiscInk(discColor || (typeof T !== "undefined" ? T.accent : "#7C3AED"));
      ctx.fill();

      // The fourth corner, showing the letter it was on at the moment Share
      // was pressed.
      gloobalQrPaintCornerMark(
        ctx,
        gloobalQrCornerBadge(matrix.size),
        gloobalQrCornerFace(markStep),
        scale
      );

      const finish = () => canvas.toBlob((blob) => resolve(blob || null), "image/png");
      const img = new Image();
      img.onload = () => {
        try {
          const mark = box.mark * scale;
          const ratio = Math.min(mark / img.width, mark / img.height);
          const w = img.width * ratio;
          const h = img.height * ratio;
          // Knocked out white, the same way the SVG's CSS filter does it:
          // draw the mark, then flood its own pixels with white through
          // source-in. Done on a scratch canvas so the flood cannot reach the
          // code underneath.
          const cut = document.createElement("canvas");
          cut.width = Math.max(1, Math.round(w));
          cut.height = Math.max(1, Math.round(h));
          const cctx = cut.getContext("2d");
          if (cctx) {
            cctx.drawImage(img, 0, 0, cut.width, cut.height);
            cctx.globalCompositeOperation = "source-in";
            cctx.fillStyle = "#FFFFFF";
            cctx.fillRect(0, 0, cut.width, cut.height);
            ctx.drawImage(cut, cx - w / 2, cx - h / 2, w, h);
          } else {
            ctx.drawImage(img, cx - w / 2, cx - h / 2, w, h);
          }
        } catch {
        }
        finish();
      };
      // A QR without its logo still scans; never fail the share over it.
      img.onerror = finish;
      img.src = G_LOGO_DATA_URI;
    } catch {
      resolve(null);
    }
  });
}

var GLOOBAL_QR_CARD_BUTTON = {
  flex: 1,
  minWidth: 0,
  minHeight: 44,
  borderRadius: 999,
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  gap: 8,
  fontSize: 14,
  fontWeight: 700,
  cursor: "pointer",
  padding: "0 12px"
};

// How long each colour holds before the badge turns over.
var GLOOBAL_QR_DISC_CYCLE_MS = 2000;

// `side` is which half of the account this code is FOR — "person" on the
// personal Receive screen, "shop" on the creator one. The two used to draw
// the same bytes, so a scanner could only guess, and guessed the shop for
// both. Now the code says. Left unset, the unmarked form is drawn, which
// behaves exactly as every code did before there were sides.
// `style` forces which picture is drawn and hides the picker. The shop
// code opened from the Creator Profile passes a random animal; without it
// the person's saved choice is used, as it always was.
function GloobalReceiveQrCard({ gloobalId, name, side, style: forcedStyle = null, onToast, headerAction = null }) {
  const [sharing, setSharing] = useState36(false);
  // The badge's colour, turning over every two seconds.
  //
  // randomLogoFlipColor(prev) is the same picker the dial pad's centre key
  // uses, and it takes the current colour so it never hands back the one
  // already showing — a turn that lands on the same colour reads as the
  // animation having stopped.
  //
  // Only this one value animates. The modules, the finders and the quiet zone
  // are the code, and nothing that is the code moves.
  const [discColor, setDiscColor] = useState36(() => randomLogoFlipColor());
  // The corner mark's step, advanced on the same tick as the disc so the two
  // turn over together — staggering them reads as one of them lagging.
  const [markStep, setMarkStep] = useState36(0);
  useEffect31(() => {
    const id = setInterval(() => {
      setDiscColor((prev) => randomLogoFlipColor(prev));
      setMarkStep((s) => s + 1);
    }, GLOOBAL_QR_DISC_CYCLE_MS);
    return () => clearInterval(id);
  }, []);
  // Which picture: an animal key, or "classic" for the plain code with the
  // logo badge. Remembered on this device; every choice carries the same link.
  const [qrStyle, setQrStyle] = useState36(() => forcedStyle || gloobalAnimalQrLoadChoice());
  const chooseQrStyle = (next) => {
    setQrStyle(next);
    gloobalAnimalQrSaveChoice(next);
  };
  const payload = buildGloobalPayUrl(gloobalId, side);
  const animalLayout = payload && qrStyle !== "classic" ? gloobalAnimalQrLayout(payload, qrStyle) : null;
  const animalChoice = animalLayout ? gloobalAnimalQrFind(qrStyle) : null;

  if (!payload) {
    return (
      <p style={{ margin: 0, textAlign: "center", fontSize: 13, color: T.inkSoft }}>
        Your <GloobalWordmark /> ID isn't ready yet.
      </p>
    );
  }

  const handleCopy = () => {
    // copyToClipboard is fire-and-forget (it falls back internally and
    // returns nothing), so the toast is shown straight away.
    copyToClipboard(gloobalId);
    onToast?.("GLOOBAL ID copied");
  };

  // Share first, download second — see shareAuditReport in
  // features/receipts/auditReport.js for why canShare is asked up front
  // rather than a rejected share falling through to a download.
  const handleShare = async () => {
    if (sharing) return;
    setSharing(true);
    try {
      // The colour showing at the moment Share was pressed. A PNG cannot
      // cycle, and picking a fixed brand colour instead would hand somebody a
      // file that does not match the code they were looking at.
      const blob = await gloobalQrToPngBlob(payload, { discColor, markStep, animal: animalLayout ? qrStyle : null });
      if (!blob) {
        onToast?.("Couldn't create the QR image");
        return;
      }
      // The picture and the link together, the link INSIDE the message so
      // it arrives tappable — see components/common/shareLink.js for why
      // `url` is never passed on its own any more.
      const file = typeof File !== "undefined" ? new File([blob], "gloobal-qr.png", { type: "image/png" }) : null;
      const message = side === "shop" && name ? `Pay ${name} on GLOOBAL:` : "Pay me on GLOOBAL:";
      const outcome = await gloobalShareLink({ title: "My GLOOBAL QR", message, url: payload, file });
      if (outcome === "shared" || outcome === "cancelled") return;
      // Neither a share sheet nor a clipboard: keep the picture instead.
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "gloobal-qr.png";
      document.body.appendChild(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 10000);
      onToast?.("QR saved");
    } finally {
      setSharing(false);
    }
  };

  return (
    <section
      aria-labelledby="gloobal-receive-qr-title"
      style={{
        background: "#FFFFFF",
        borderRadius: T.radiusXl,
        border: `1px solid ${T.line}`,
        boxShadow: T.shadowCard,
        width: "100%",
        maxWidth: 360,
        margin: "0 auto",
        padding: "20px 12px",
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 14
      }}
    >
      {/* Title centred, with an optional action (My Share) on its right.
          Three columns so the title stays centred whether or not the
          action is there. */}
      <div style={{ width: "100%", display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", gap: 8 }}>
        <GH2HFlipCircle size={GLOOBAL_QR_HALLMARK_SIZE} />
        <h2
          id="gloobal-receive-qr-title"
          style={{ margin: 0, fontFamily: T.fontDisplay, fontSize: 17, fontWeight: 800, color: T.ink, whiteSpace: "nowrap" }}
        >
          Your <GloobalWordmark /> QR
        </h2>
        <div data-testid="qr-header-action" style={{ justifySelf: "end", display: "flex" }}>{headerAction}</div>
      </div>

      <div style={{ width: "min(300px, 100%)", aspectRatio: "1 / 1", background: "#FFFFFF" }}>
        {animalLayout ? (
          <GloobalAnimalQrSvg layout={animalLayout} label={animalChoice && animalChoice.label} markStep={markStep} />
        ) : (
          <GloobalQrSvg value={payload} discColor={discColor} markStep={markStep} />
        )}
      </div>

      {/* The picker: colour dots only, no words. Each dot's name is its
          accessible label (and tooltip). Scrolls sideways if it ever
          outgrows a narrow phone. Absent when the style was forced — a
          random shop code is a picture of the moment, not a choice. */}
      {forcedStyle ? null : <div
        role="radiogroup"
        aria-label="QR picture"
        data-testid="qr-style-picker"
        style={{ display: "flex", justifyContent: "safe center", gap: 5, width: "100%", overflowX: "auto", padding: "4px 2px 6px", boxSizing: "border-box", scrollbarWidth: "none" }}
      >
        {[{ key: "classic", label: "Classic", color: null }, ...GLOOBAL_QR_ANIMALS].map((opt) => {
          const selected = (animalLayout ? qrStyle : "classic") === opt.key;
          return (
            <button
              key={opt.key}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-label={opt.label}
              title={opt.label}
              onClick={() => chooseQrStyle(opt.key)}
              style={{
                flexShrink: 0,
                width: 26,
                height: 26,
                borderRadius: "50%",
                padding: 0,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                border: selected ? `2px solid ${opt.color ? gloobalAnimalQrInk(opt.color) : T.ink}` : "2px solid transparent",
                background: "#FFFFFF",
                cursor: "pointer"
              }}
            >
              <span
                aria-hidden="true"
                style={{
                  width: 16,
                  height: 16,
                  borderRadius: opt.color ? "50%" : 4,
                  background: opt.color ? gloobalAnimalQrInk(opt.color) : "#000"
                }}
              />
            </button>
          );
        })}
      </div>}

      <div style={{ width: "100%", minWidth: 0, textAlign: "center", display: "flex", flexDirection: "column", gap: 4 }}>
        {name ? (
          <div
            style={{
              fontSize: 15,
              fontWeight: 800,
              color: T.ink,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap"
            }}
          >
            {name}
          </div>
        ) : null}
        <div style={{ fontSize: 13.5, fontWeight: 700, color: T.inkSoft, letterSpacing: 0.3, wordBreak: "break-all" }}>
          {gloobalId}
        </div>
      </div>

      <div style={{ display: "flex", gap: 10, width: "100%" }}>
        <button
          type="button"
          onClick={handleCopy}
          aria-label="Copy Gloobal ID"
          style={{ ...GLOOBAL_QR_CARD_BUTTON, background: "#FFFFFF", color: T.ink, border: `1px solid ${T.line}` }}
        >
          <Copy4 size={16} aria-hidden="true" />
          Copy ID
        </button>
        <button
          type="button"
          onClick={handleShare}
          disabled={sharing}
          aria-label="Share Gloobal QR"
          style={{
            ...GLOOBAL_QR_CARD_BUTTON,
            background: T.gradButton,
            color: "#FFFFFF",
            border: "none",
            opacity: sharing ? 0.7 : 1
          }}
        >
          <Share23 size={16} aria-hidden="true" />
          Share
        </button>
      </div>

      <p style={{ margin: 0, fontSize: 12.5, color: T.inkSoft, textAlign: "center" }}>
        Scan this QR to pay into your <GloobalWordmark /> wallet.
      </p>
    </section>
  );
}


// src/components/common/actionTileMotion.jsx
//
// The four action tiles move the way the thing they do moves.
//
// Send flies off the tile. Receive drops in from above. Scan sweeps a line
// down its frame. Bank settles on its footing.
//
// ── Why motion, and why this motion ──────────────────────────────────────
//
// The tiles were never actually still: Dashboard.jsx picks one of TEN
// flip-capable buttons every 15 seconds and flips it for 1.3s, so each tile
// turns about once every two and a half minutes. The machinery was there and
// the odds of catching it were not. That flip stays — it is part of the app's
// character, and it is what ties these buttons to the dial symbols — and this
// sits on a wrapper outside it, so the two compose rather than fight for the
// same transform.
//
// What it buys beyond decoration: two of these four tiles, Scan and Receive,
// carry NO text label. Their meaning rests entirely on a glyph. A movement
// that restates the meaning is a second way to read them, which a slow scale
// or a drifting sheen would not be — those are alive and say nothing, and the
// send tile would breathe exactly like the bank tile.
//
// ── The rest, which is most of the time ──────────────────────────────────
//
// Each animation occupies the first ~28% of a 9-second cycle and then holds
// still. Four tiles moving continuously on a mid-range Android is a battery
// cost paid all day for an effect nobody is looking at after the first
// minute, and a dashboard where everything is always moving is one where
// nothing draws the eye. Staggered by 0.6s so at almost any glance exactly
// one tile is doing something.
var ACTION_TILE_CYCLE_MS = 9000;

// The stagger, in seconds, by tile. Indexed the same way the dashboard lays
// them out, so the order on screen is the order they take their turn.
var ACTION_TILE_DELAYS = { send: 0, bank: 0.6, scan: 1.2, receive: 1.8 };

// One <style> for the whole group, rendered once by the dashboard.
//
// Inline rather than in App.jsx's global sheet, and that is a lesson this
// codebase already paid for: @keyframes finDrift lived in App.jsx while the
// particles that needed it lived in a component, so the day that component
// was rendered on a new screen it drew eighteen particles parked off-viewport
// and a blank background. Keyframes travel with what they animate.
function ActionTileMotionStyle() {
  return <style>{`
    /* Send — away, and back. The gap where it is invisible is deliberate:
       the plane does not fly BACK onto the tile, which would read as a
       return trip. It leaves, and another one is there. */
    @keyframes gat-send {
      0%, 4%   { transform: translate(0,0); opacity: 1; }
      20%      { transform: translate(14px,-14px); opacity: 0; }
      21%      { transform: translate(-10px,10px); opacity: 0; }
      30%, 100%{ transform: translate(0,0); opacity: 1; }
    }
    /* Receive — in from above, and it stays. The mirror of send: one ends
       empty-handed, the other ends holding something.
       Note it starts AT REST and fades before it moves, rather than starting
       already hoisted above the tile. Both matter: an animation-delay with
       the default fill mode shows the element's own resting state during the
       delay, so a keyframe set that opens mid-flight would draw the icon in
       one place for 1.8s and then jump; and a set that ends somewhere other
       than where it began pops on every loop. */
    @keyframes gat-receive {
      0%, 4%   { transform: translateY(0); opacity: 1; }
      9%       { transform: translateY(0); opacity: 0; }
      10%      { transform: translateY(-13px); opacity: 0; }
      24%      { transform: translateY(0); opacity: 1; }
      100%     { transform: translateY(0); opacity: 1; }
    }
    /* Bank — a settle, not a bounce. It is the one tile of the four that
       should look like it is not going anywhere. */
    @keyframes gat-bank {
      0%, 4%   { transform: translateY(0); }
      14%      { transform: translateY(-3px); }
      26%, 100%{ transform: translateY(0); }
    }
    /* Scan — the line a scanner actually shows. Runs inside the tile's own
       corner brackets rather than across the whole tile, so it reads as the
       frame doing its job. */
    @keyframes gat-sweep {
      0%, 3%   { top: 34%; opacity: 0; }
      7%       { opacity: 1; }
      22%      { top: 66%; opacity: 1; }
      27%, 100%{ top: 66%; opacity: 0; }
    }
    .gat { animation-duration: ${ACTION_TILE_CYCLE_MS}ms; animation-iteration-count: infinite;
           animation-timing-function: cubic-bezier(.4,0,.2,1); will-change: transform; }
    .gat-send    { animation-name: gat-send; }
    .gat-receive { animation-name: gat-receive; }
    .gat-bank    { animation-name: gat-bank; }
    .gat-sweep   { animation-name: gat-sweep; animation-duration: ${ACTION_TILE_CYCLE_MS}ms;
                   animation-iteration-count: infinite;
                   animation-timing-function: cubic-bezier(.45,0,.55,1); }
    @media (prefers-reduced-motion: reduce) {
      /* Nothing animates, and nothing is left mid-flight. Every keyframe
         above both starts and ends at the tile's resting state, so removing
         the animation removes the motion and not the icon — the failure the
         symbol background had, where particles started off-screen and were
         carried in BY the animation. */
      .gat, .gat-sweep { animation: none !important; }
      .gat-sweep { opacity: 0 !important; }
    }
  `}</style>;
}

// What the tile's GLYPH gets. Not the tile, and not the icon component's
// root — see the note in flipIcons.jsx on why those are the same element and
// why animating it would carry the tint away with the plane.
//
// Returns null for any key that is not one of the four, so a tile added later
// is obviously still rather than silently inheriting somebody else's meaning.
function actionTileIconMotion(tileKey) {
  const delay = ACTION_TILE_DELAYS[tileKey];
  if (delay === void 0) return null;
  return {
    className: `gat gat-${tileKey}`,
    style: { display: "block", animationDelay: `${delay}s` }
  };
}

// The scan line, which is the one piece of this that is not a transform on an
// existing element. Positioned against the tile, so the caller renders it as
// a sibling of the icon inside the tile's own positioned box.
function ActionTileSweep({ tileKey, color }) {
  if (tileKey !== "scan") return null;
  return <span
    aria-hidden="true"
    className="gat-sweep"
    style={{
      position: "absolute",
      left: "32%",
      right: "32%",
      height: 2,
      borderRadius: 2,
      background: color,
      // The line's RESTING state is invisible, and that has to live here
      // rather than in the keyframes. An animation-delay with the default
      // fill mode leaves the element showing its own style until the delay
      // elapses — so without this, the scan tile draws a solid bar across
      // its glyph for the first 1.2 seconds of every page load.
      opacity: 0,
      boxShadow: `0 0 8px ${color}AA`,
      animationDelay: `${ACTION_TILE_DELAYS.scan}s`,
      pointerEvents: "none"
    }}
  />;
}


// src/components/common/misc.jsx
// ── WHETHER THIS SERVICE IS LIVE YET ────────────────────────────────────
//
// A star, like the one that marks a pinned shop: HOLLOW AND RED while a
// service is not connected to a real API, SOLID AND GREEN once it is.
//
// ── IT WAS A PADLOCK, AND THE REASON IT CHANGED MATTERS LESS THAN THE
//    REASON IT KEPT TWO SIGNALS ─────────────────────────────────────────
//
// The padlock before this drew a CLOSED shape in both states and changed
// only its colour — red for locked, green for unlocked. A closed padlock
// means "locked" to anyone who has ever seen one, so the shape said locked
// while the colour said open, and the colour was the part carrying the
// meaning. On the Accounts tab that produced green padlocks on the three
// services that were available, which reads as the exact opposite of the
// truth. It was fixed by making the shape carry it too: closed and red,
// open and green.
//
// The founder asked for a star instead, and a star has no open and closed.
// Drawing it red or green and nothing else would put the whole meaning
// back into colour alone — and red and green are the pair a large minority
// of people cannot separate, which is the fault that was just removed.
//
// So the star is FILLED or not. Hollow reads as an outline waiting to be
// completed; solid reads as done, which is what it is. Colour agrees with
// the fill rather than carrying the message on its own, and the same
// difference is already doing this job on a pinned shop's mark.
function ServiceLock({ locked = true, size = 15 }) {
  return <Star3
    size={size}
    color={locked ? T.negative : T.positive}
    fill={locked ? "none" : T.positive}
    strokeWidth={locked ? 2.2 : 1.6}
    style={{ flexShrink: 0 }}
    aria-hidden="true"
  />;
}



// src/features/receipts/receiptCurrency.js
//
// ── What a receipt says about currency, in one place ────────────────────
//
// Three documents describe the same transaction — the receipt screen
// (ReceiptModal), the shared picture (receiptImage.js) and the audit PDF
// (auditReport.js) — and each used to decide for itself whether a
// conversion had happened and which fields held it. They disagreed:
//
//   - the PDF read sourceCurrency / destinationCurrency / sourceSideAmount /
//     destinationSideAmount / fxRateLabel, names no receipt builder has ever
//     set, so its conversion section could never appear;
//   - the screen drew the two amounts without a rate, the picture refused to
//     draw either without one;
//   - on a Creator Share receipt the Payment tab read the SHARE row's
//     conversion fields, which are null on a share leg by design, so the
//     payment it came from always looked domestic; and the Creator Share tab
//     showed one side of the share and never the other, although the server
//     records both (the payee's withheld figure in their currency, the
//     payer's credit in theirs).
//
// Every figure here is a RECORDED one. Nothing is converted, multiplied,
// divided or inverted: a missing side stays missing, and a missing rate
// means no rate line, never one worked out from the two amounts.

function receiptRecordedFigure(value) {
  if (value == null || value === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

// Two recorded sides in two different currencies, or null.
//
// `rateLabel` is the caller's, because the rate's stored direction differs
// between the payment and the share (see below) and the label must state it
// in that direction rather than an inverted one.
function receiptConversionFacts(paidAmount, paidCurrency, gotAmount, gotCurrency, rateLabel) {
  const paid = receiptRecordedFigure(paidAmount);
  const got = receiptRecordedFigure(gotAmount);
  const paidCcy = paidCurrency ? String(paidCurrency) : "";
  const gotCcy = gotCurrency ? String(gotCurrency) : "";
  // Same currency on both sides is not a conversion. A block reading
  // "1 INR = 1.000000 INR" states that an exchange took place, and none did.
  if (paid == null || got == null || !paidCcy || !gotCcy || paidCcy === gotCcy) return null;
  return {
    paidAmount: paid,
    paidCurrency: paidCcy,
    gotAmount: got,
    gotCurrency: gotCcy,
    rateLabel: rateLabel || null
  };
}

// ── The payment's conversion ────────────────────────────────────────────
//
// The server's rate converts 1 unit of the RECEIVER's currency into the
// SENDER's, and is shown that way round: "1 INR = 0.009165 EUR".
//
// On a Creator Share receipt the payment is not this row — the row is the
// share — so the figures come off the source payment the history lookup
// found (buildHistoryReceipt's source* fields). Null when it was not found.
function receiptPaymentConversion(receipt) {
  const r = receipt || {};
  if (r.kind === "coin") return null;
  const isShare = r.kind === "share";
  const senderAmount = isShare ? r.sourceSenderAmount : r.senderAmount;
  const senderCurrency = isShare ? r.sourceSenderSideCurrency : r.senderSideCurrency;
  const receiverAmount = isShare ? r.sourceReceiverAmount : r.receiverAmount;
  const receiverCurrency = isShare ? r.sourceReceiverSideCurrency : r.receiverSideCurrency;
  const rate = receiptRecordedFigure(isShare ? r.sourceFxRate : r.fxRate);
  return receiptConversionFacts(
    senderAmount, senderCurrency, receiverAmount, receiverCurrency,
    rate != null && receiverCurrency && senderCurrency
      ? `1 ${receiverCurrency} = ${rate.toFixed(6)} ${senderCurrency}`
      : null
  );
}

// ── The Creator Share's conversion ──────────────────────────────────────
//
// The share runs the other way from its payment: the PAYEE gives it (in the
// payee's currency, withheld from their credit) and the PAYER gets it (in
// the payer's currency). Both figures are stored — `cashback` and
// `cashbackCredit` on the payment, amount and debitAmount on the share leg —
// and carried onto the receipt as shareSender* / shareReceiver*.
//
// The rate is the payment's own recorded rate, the one the server applied to
// turn the payee's figure into the payer's. Builders set `shareFxRate` only
// when the payment's two currencies are exactly the share's two, reversed;
// otherwise there is no rate line. Its direction is the payment's, which on
// the share reads 1 unit of what was given = N units of what was received.
function receiptShareConversion(receipt) {
  const r = receipt || {};
  if (r.kind === "coin") return null;
  const rate = receiptShareFxRate(r);
  return receiptConversionFacts(
    r.shareSenderAmount, r.shareSenderCurrency, r.shareReceiverAmount, r.shareReceiverCurrency,
    rate != null && r.shareSenderCurrency && r.shareReceiverCurrency
      ? `1 ${r.shareSenderCurrency} = ${rate.toFixed(6)} ${r.shareReceiverCurrency}`
      : null
  );
}

// The rate a receipt's Creator Share was converted at.
//
// `shareFxRate` when a builder set it (buildHistoryReceipt does, reading the
// source payment on a share receipt). Otherwise, on a PAYMENT receipt, the
// payment's own recorded rate on the same currency-alignment test — which is
// how the receipt shown straight after paying gets one: buildTransaction-
// Snapshot carries the share's two sides and the payment's rate, and this is
// the one place that decides whether that rate belongs to the share.
function receiptShareFxRate(receipt) {
  const r = receipt || {};
  const own = receiptRecordedFigure(r.shareFxRate);
  if (own != null) return own;
  if (r.kind === "share" || r.kind === "coin") return null;
  return receiptShareRateFromPayment(
    r.shareSenderCurrency, r.shareReceiverCurrency,
    r.senderSideCurrency, r.receiverSideCurrency, r.fxRate
  );
}

// The payment's recorded rate, when it is the rate this share was converted
// at: the share's giver holds the payment's receiving currency and the
// share's receiver the payment's sending one. Anything else returns null.
function receiptShareRateFromPayment(shareSenderCurrency, shareReceiverCurrency, paymentSenderCurrency, paymentReceiverCurrency, paymentFxRate) {
  const rate = receiptRecordedFigure(paymentFxRate);
  if (rate == null || !shareSenderCurrency || !shareReceiverCurrency) return null;
  if (shareSenderCurrency === shareReceiverCurrency) return null;
  if (shareSenderCurrency !== paymentReceiverCurrency || shareReceiverCurrency !== paymentSenderCurrency) return null;
  return rate;
}


// src/features/receipts/auditReport.js
//
// The audit report: one transaction, as a PDF you can send to somebody.
//
// A receipt is for the person who made the payment. This is for whoever they
// have to show it to — an accountant, a support queue, the other side of a
// dispute. Same facts, stated formally, in a file that leaves the app.
//
// ── Why this writes the PDF by hand ──────────────────────────────────────
//
// The obvious answer is a library. jsPDF is ~350KB and this bundle has five
// runtime dependencies in total, for a PWA whose people are on mid-range
// Android. A one-page, text-and-lines document does not need a general PDF
// engine: the format is a plain byte stream with an offset table, and what is
// below is the whole of it.
//
// The other answer — `window.print()` and "Save as PDF" — costs nothing and
// was the first plan. It is not a file. It cannot be handed to
// navigator.share, cannot be attached to an email from the app, and puts a
// print dialog in front of somebody who asked for a document.
//
// ── Why the report writes ISO codes and never currency symbols ───────────
//
// Partly practical: PDF's built-in fonts cover WinAnsi, and the rupee sign
// is not in it. A PDF that renders "500.00" where the screen says "500.00₹"
// would be a document that quietly drops the unit — the worst possible
// failure for a financial record.
//
// Mostly deliberate, though. "$" is the currency of a dozen countries. On a
// document that exists to settle questions, "500.00 INR" answers one that
// "₹500.00" only appears to. Every figure below is written amount-then-code.
//
// The Gloobal reference symbols ARE drawn — as vector paths, not glyphs (see
// SYMBOL_PAINTERS). A reference is the one thing on this page somebody might
// have to match character for character against another system, so it is
// reproduced exactly rather than transliterated.

// ── Page geometry, in PDF points (1/72") ────────────────────────────────
//
// A4 rather than Letter: this app is built in India and the report will be
// printed and filed there far more often than not.
var AUDIT_PAGE_W = 595.28;
var AUDIT_PAGE_H = 841.89;
var AUDIT_MARGIN = 48;
var AUDIT_COL_VALUE_RIGHT = AUDIT_PAGE_W - AUDIT_MARGIN;

// ── Helvetica metrics ────────────────────────────────────────────────────
//
// Adobe's own widths, per 1000 em, for printable ASCII. Needed only so
// amounts can be RIGHT-aligned, which on a financial document is not
// decoration: a column of figures whose decimal points do not line up is one
// a person has to read digit by digit to compare.
var AUDIT_W_REG = [
  278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278,
  556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
  1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778,
  667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
  333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556,
  556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584
];
var AUDIT_W_BOLD = [
  278, 333, 474, 556, 556, 889, 722, 238, 333, 333, 389, 584, 278, 333, 278, 278,
  556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 333, 333, 584, 584, 584, 611,
  975, 722, 722, 722, 722, 667, 611, 778, 722, 278, 556, 722, 611, 833, 722, 778,
  667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 333, 278, 333, 584, 556,
  333, 556, 611, 556, 611, 556, 333, 611, 611, 278, 278, 556, 278, 889, 611, 611,
  611, 611, 389, 556, 333, 611, 556, 778, 556, 556, 500, 389, 280, 389, 584
];

function auditTextWidth(text, size, bold) {
  const table = bold ? AUDIT_W_BOLD : AUDIT_W_REG;
  let units = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    units += c >= 32 && c <= 126 ? table[c - 32] : 556;
  }
  return (units / 1000) * size;
}

// Anything outside printable ASCII is replaced rather than dropped.
//
// Dropping is the failure this guards: a name with an accent would silently
// lose a letter, and nobody reading the PDF would know a character had ever
// been there. A visible marker is a worse-looking document and a more honest
// one. The Gloobal symbols never reach here — they are painted.
function auditAscii(text) {
  let out = "";
  const s = String(text == null ? "" : text);
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    out += c >= 32 && c <= 126 ? s[i] : "?";
  }
  return out;
}

// PDF string literals are parenthesised, so three characters must escape.
function auditEscape(text) {
  return auditAscii(text).replace(/([\\()])/g, "\\$1");
}

// ── The Gloobal alphabet, as paths ───────────────────────────────────────
//
// The same eight shapes the dial pad, the ID chips and the codes draw, at
// whatever size the page needs. A reference on this document has to match,
// character for character, a reference on a screen or in a database — so it
// is reproduced, not described.
//
// Local copy of the alphabet for the reason every other module here states:
// build_app.mjs concatenates these files into one scope and `var` hoists the
// declaration but not the initialiser, so reading DIAL_SYMBOLS at load time
// reads undefined. tests/audit-report.test.mjs holds the copy honest.
var AUDIT_SYMBOLS = ["−", "+", "\xD7", "=", "○", "□", "●", "■"];

// Circle from four cubic Béziers. 0.5523 is the standard magic constant.
function auditCircle(cx, cy, r) {
  const k = r * 0.5523;
  return (
    `${cx - r} ${cy} m ` +
    `${cx - r} ${cy + k} ${cx - k} ${cy + r} ${cx} ${cy + r} c ` +
    `${cx + k} ${cy + r} ${cx + r} ${cy + k} ${cx + r} ${cy} c ` +
    `${cx + r} ${cy - k} ${cx + k} ${cy - r} ${cx} ${cy - r} c ` +
    `${cx - k} ${cy - r} ${cx - r} ${cy - k} ${cx - r} ${cy} c `
  );
}

// A bar of thickness t, length L, centred on (cx, cy) and rotated by deg.
// Emitted as an explicit quadrilateral rather than with `cm`, because `cm`
// would alter the coordinate system for everything drawn after it and this
// has to compose with ordinary text placement.
function auditBar(cx, cy, len, thick, deg) {
  const a = (deg * Math.PI) / 180;
  const ux = Math.cos(a) * (len / 2);
  const uy = Math.sin(a) * (len / 2);
  const vx = -Math.sin(a) * (thick / 2);
  const vy = Math.cos(a) * (thick / 2);
  const p = (sx, sy) => `${(cx + sx).toFixed(2)} ${(cy + sy).toFixed(2)}`;
  return (
    `${p(-ux + vx, -uy + vy)} m ` +
    `${p(ux + vx, uy + vy)} l ` +
    `${p(ux - vx, uy - vy)} l ` +
    `${p(-ux - vx, -uy - vy)} l h `
  );
}

// One painter per symbol, drawing into a box of side `s` whose centre is
// (cx, cy). Returns a content-stream fragment.
var SYMBOL_PAINTERS = [
  // − minus
  (cx, cy, s) => auditBar(cx, cy, s * 0.74, s * 0.16, 0) + "f\n",
  // + plus
  (cx, cy, s) =>
    auditBar(cx, cy, s * 0.74, s * 0.16, 0) + "f\n" +
    auditBar(cx, cy, s * 0.74, s * 0.16, 90) + "f\n",
  // × times
  (cx, cy, s) =>
    auditBar(cx, cy, s * 0.72, s * 0.16, 45) + "f\n" +
    auditBar(cx, cy, s * 0.72, s * 0.16, -45) + "f\n",
  // = equals
  (cx, cy, s) =>
    auditBar(cx, cy + s * 0.14, s * 0.74, s * 0.13, 0) + "f\n" +
    auditBar(cx, cy - s * 0.14, s * 0.74, s * 0.13, 0) + "f\n",
  // ○ hollow circle
  (cx, cy, s) => `${(s * 0.11).toFixed(2)} w ` + auditCircle(cx, cy, s * 0.3) + "S\n",
  // □ hollow square
  (cx, cy, s) =>
    `${(s * 0.11).toFixed(2)} w ${(cx - s * 0.3).toFixed(2)} ${(cy - s * 0.3).toFixed(2)} ` +
    `${(s * 0.6).toFixed(2)} ${(s * 0.6).toFixed(2)} re S\n`,
  // ● filled circle
  (cx, cy, s) => auditCircle(cx, cy, s * 0.32) + "f\n",
  // ■ filled square
  (cx, cy, s) =>
    `${(cx - s * 0.32).toFixed(2)} ${(cy - s * 0.32).toFixed(2)} ` +
    `${(s * 0.64).toFixed(2)} ${(s * 0.64).toFixed(2)} re f\n`
];

// A Gloobal reference, painted left-to-right from x. Returns { ops, width }.
// Unknown characters are SKIPPED rather than guessed at — a reference that
// contains something outside the alphabet is not a Gloobal reference, and
// inventing a shape for it would make a wrong document look right.
function auditPaintReference(reference, x, y, size) {
  const step = size * 0.86;
  let ops = "";
  let drawn = 0;
  const chars = Array.from(String(reference || ""));
  for (const ch of chars) {
    const index = AUDIT_SYMBOLS.indexOf(ch);
    if (index === -1) continue;
    ops += SYMBOL_PAINTERS[index](x + drawn * step + step / 2, y + size * 0.32, size);
    drawn += 1;
  }
  return { ops, width: drawn * step, count: drawn };
}

// ── The document ─────────────────────────────────────────────────────────

function auditMoney(amount, code) {
  const n = Number(amount);
  if (!Number.isFinite(n)) return "—";
  // Two decimals here regardless of the currency's own precision, which is a
  // departure from fmtMoney and is deliberate: this is a ledger document, and
  // a column where some rows carry decimals and others do not is one a reader
  // has to check twice. The CODE says what the unit is.
  return `${n.toFixed(2)} ${String(code || "").toUpperCase() || "—"}`;
}

// Builds the page's content stream. Kept apart from the file assembly below
// so the layout can be read as layout.
function auditContentStream(report) {
  const L = AUDIT_MARGIN;
  const R = AUDIT_COL_VALUE_RIGHT;
  let y = AUDIT_PAGE_H - AUDIT_MARGIN;
  let ops = "";

  const text = (str, x, size, bold, gray) => {
    const g = gray == null ? 0 : gray;
    ops += `BT ${g} ${g} ${g} rg /${bold ? "F2" : "F1"} ${size} Tf ` +
      `${x.toFixed(2)} ${y.toFixed(2)} Td (${auditEscape(str)}) Tj ET\n0 0 0 rg\n`;
  };
  const right = (str, size, bold, gray) =>
    text(str, R - auditTextWidth(auditAscii(str), size, bold), size, bold, gray);
  const rule = (gray) => {
    const g = gray == null ? 0.82 : gray;
    ops += `${g} ${g} ${g} RG 0.7 w ${L} ${y.toFixed(2)} m ${R} ${y.toFixed(2)} l S\n0 0 0 RG\n`;
  };
  const gap = (n) => { y -= n; };
  const row = (label, value) => {
    text(label, L, 9.5, false, 0.35);
    right(value, 9.5, true);
    gap(15);
  };
  const heading = (str) => {
    gap(6);
    text(str.toUpperCase(), L, 8.5, true, 0.45);
    gap(6);
    rule();
    gap(14);
  };

  // Title block
  text("GLOOBAL", L, 17, true);
  right(report.generatedAt || "", 8.5, false, 0.45);
  gap(17);
  text("Transaction audit report", L, 10.5, false, 0.35);
  gap(20);
  rule(0.55);
  gap(22);

  // ── The payment ────────────────────────────────────────────────────────
  heading("Payment");
  row(report.payment.directionLabel, auditMoney(report.payment.amount, report.payment.currency));
  row(report.payment.counterpartyLabel, report.payment.counterpartyName || "—");
  if (report.payment.date) row("Date", report.payment.date);
  if (report.payment.time) row("Time", report.payment.time);
  if (report.payment.method) row("Method", report.payment.method);
  if (report.payment.status) row("Status", report.payment.status);

  // ── Currency conversion ───────────────────────────────────────────────
  //
  // Only when the two sides really are different currencies. A "conversion"
  // section on a domestic payment showing 1.000000 states that an exchange
  // took place, and none did.
  if (report.conversion) {
    heading("Currency conversion");
    row("Sender pays", auditMoney(report.conversion.sourceAmount, report.conversion.sourceCurrency));
    row("Receiver gets", auditMoney(report.conversion.destinationAmount, report.conversion.destinationCurrency));
    row("Rate applied", report.conversion.rateLabel);
    // The sentence that makes the figure above meaningful. A rate with no
    // date on it is a rate somebody will assume is today's.
    text(
      "Rate as settled at the time of this transaction, not a current market rate.",
      L, 8, false, 0.45
    );
    gap(16);
  }

  // ── The Creator Share ─────────────────────────────────────────────────
  if (report.share) {
    heading("Creator Share");
    row(report.share.directionLabel, auditMoney(report.share.amount, report.share.currency));
    row("Rate", report.share.rateLabel);
    if (report.share.counterpartyName) row(report.share.counterpartyLabel, report.share.counterpartyName);
    // The share's two recorded sides, when it crossed a currency: what the
    // payee gave in theirs, what the payer got in theirs.
    if (report.share.conversion) {
      row("Share given", auditMoney(report.share.conversion.sourceAmount, report.share.conversion.sourceCurrency));
      row("Share received", auditMoney(report.share.conversion.destinationAmount, report.share.conversion.destinationCurrency));
      row("Rate applied", report.share.conversion.rateLabel);
    }
  }

  // ── References ────────────────────────────────────────────────────────
  heading("References");
  for (const ref of report.references || []) {
    text(ref.label, L, 9.5, false, 0.35);
    if (ref.value) {
      const painted = auditPaintReference(ref.value, L, y, 8.5);
      if (painted.count) {
        // Right-align the painted block the same way a text value would be.
        const shifted = auditPaintReference(ref.value, R - painted.width, y, 8.5);
        ops += shifted.ops;
      } else {
        right(ref.value, 9.5, true);
      }
    } else {
      right("—", 9.5, true);
    }
    gap(16);
  }

  // ── Footer ────────────────────────────────────────────────────────────
  y = AUDIT_MARGIN + 34;
  rule();
  gap(14);
  text(
    "Generated by GLOOBAL from the records on this device. Figures are as settled;",
    L, 7.5, false, 0.5
  );
  gap(10);
  text("nothing on this page is recalculated at the time of printing.", L, 7.5, false, 0.5);

  return ops;
}

// ── File assembly ────────────────────────────────────────────────────────
//
// A PDF is a list of numbered objects, a cross-reference table of their byte
// offsets, and a trailer pointing at the table. The offsets must be exact and
// are counted in BYTES — so the buffer is built as bytes from the start
// rather than as a string that is encoded at the end, where a single
// multi-byte character would shift every offset after it and produce a file
// that opens in some readers and not others.
function auditPdfBytes(report) {
  const content = auditContentStream(report);
  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 " + AUDIT_PAGE_W + " " + AUDIT_PAGE_H +
      "] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> /Contents 4 0 R >>",
    "<< /Length " + content.length + " >>\nstream\n" + content + "endstream",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"
  ];

  const chunks = [];
  let length = 0;
  const push = (str) => {
    const bytes = new TextEncoder().encode(str);
    chunks.push(bytes);
    length += bytes.length;
  };

  push("%PDF-1.4\n");
  const offsets = [];
  objects.forEach((body, i) => {
    offsets.push(length);
    push(`${i + 1} 0 obj\n${body}\nendobj\n`);
  });

  const xrefAt = length;
  let xref = `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  for (const offset of offsets) xref += `${String(offset).padStart(10, "0")} 00000 n \n`;
  push(xref);
  push(`trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefAt}\n%%EOF\n`);

  const out = new Uint8Array(length);
  let at = 0;
  for (const chunk of chunks) { out.set(chunk, at); at += chunk.length; }
  return out;
}

// ── What the receipt hands in ────────────────────────────────────────────
//
// Every figure is taken off the receipt as it stands. Nothing here computes a
// rate, converts an amount or derives a missing side — a field the receipt
// does not have becomes a dash on the page, which is the true statement.
function buildAuditReport(receipt, options) {
  const opts = options || {};
  const isShare = receipt.kind === "share";
  const paymentIsSent = isShare ? receipt.sourceDirection === "sent" : receipt.direction === "sent";
  const paymentAmount = isShare ? receipt.sourceAmount : receipt.amount;
  const paymentCurrency = isShare
    ? receipt.sourceCurrencyCode || receipt.currencyCode
    : receipt.currencyCode;
  const shareIsCredit = isShare ? receipt.direction !== "sent" : receipt.direction === "sent";
  const shareRate = isShare ? receipt.sourceShareRate : receipt.shareRate;
  // THE RECORDED FIGURE FIRST, and the arithmetic only when there is none.
  //
  // This multiplied the payment by the rate every time, which is a
  // reconstruction of a number the server already recorded — and it rounds
  // differently from the server's minor-unit figure, so the two can differ
  // in the last unit. The screen and the shared picture both read the
  // recorded value first (ReceiptModal's shownShareAmount, receiptImage's
  // recordedShare) and only fall back to the multiplication for a payment
  // this device settled locally, which genuinely has no server figure.
  //
  // This renderer had no such branch, and it is the one that matters most:
  // of the three it is the formal artefact, the document literally headed
  // as an audit report. It printed a reconstructed share that could disagree
  // with the ledger — and with the figure on screen for the same payment.
  //
  // A recorded 0 counts as "not recorded", the same reading the other two
  // take: every builder defaults an absent share to 0, and a 0% payment has
  // no share to print anyway.
  const recordedShareAmount = Number(receipt.shareAmount);
  const hasRecordedShare = Number.isFinite(recordedShareAmount) && recordedShareAmount > 0;
  const shareAmount = isShare
    ? Number(receipt.shareAmount) || Number(receipt.amount) || 0
    : hasRecordedShare
      ? recordedShareAmount
      : (Number(receipt.amount) || 0) * ((Number(receipt.shareRate) || 0) / 100);

  // Read through receiptCurrency.js, the same way the screen and the picture
  // read it. This used to test sourceCurrency / destinationCurrency /
  // sourceSideAmount / destinationSideAmount / fxRateLabel — names no receipt
  // builder has ever set — so the section never appeared on a real report,
  // however cross-border the payment was.
  const toSection = (facts) => facts
    ? {
        sourceAmount: facts.paidAmount,
        sourceCurrency: facts.paidCurrency,
        destinationAmount: facts.gotAmount,
        destinationCurrency: facts.gotCurrency,
        rateLabel: facts.rateLabel || "—"
      }
    : null;
  const conversion = paymentAmount == null ? null : toSection(receiptPaymentConversion(receipt));
  const shareConversion = toSection(receiptShareConversion(receipt));

  return {
    generatedAt: opts.generatedAt || "",
    payment: {
      directionLabel: paymentAmount == null ? "Amount (not on this device)" : (paymentIsSent ? "Money sent" : "Money received"),
      amount: paymentAmount,
      currency: paymentCurrency,
      counterpartyLabel: paymentIsSent ? "To" : "From",
      counterpartyName: receipt.name,
      date: receipt.date,
      time: receipt.time,
      method: receipt.method,
      status: receipt.status
    },
    conversion,
    share: (shareRate != null || isShare)
      ? {
          directionLabel: shareIsCredit ? "Shared back to you" : "You shared back",
          amount: shareAmount,
          currency: receipt.currencyCode,
          rateLabel: shareRate == null ? "—" : `${Number(shareRate).toFixed(2)}%`,
          counterpartyLabel: shareIsCredit ? "Shared back by" : "Shared back to",
          counterpartyName: receipt.name,
          conversion: shareConversion
        }
      : null,
    references: [
      { label: "Payment reference", value: isShare ? receipt.sourceTxnId : receipt.txnId },
      { label: "Creator Share reference", value: isShare ? receipt.txnId : receipt.shareTxnId },
      { label: "GLOOBAL ID", value: receipt.id }
    ].filter((r) => r.value)
  };
}

// The two entry points. `bytes` is what the tests drive; `blob` is what the
// screen hands to a download or to navigator.share.
function auditReportBytes(receipt, options) {
  return auditPdfBytes(buildAuditReport(receipt, options));
}

function auditReportBlob(receipt, options) {
  return new Blob([auditReportBytes(receipt, options)], { type: "application/pdf" });
}

// A filename somebody can find again. Dated, and named for what it is.
function auditReportFilename(receipt) {
  const date = String(receipt && receipt.date ? receipt.date : "").replace(/[^\w-]+/g, "-");
  return `gloobal-audit-${date || "transaction"}.pdf`;
}

// ── Getting the file off the phone ───────────────────────────────────────
//
// Share first, download second, and the order matters.
//
// A report is going somewhere — an accountant, a support thread, a dispute.
// navigator.share with a file puts the PDF straight into WhatsApp or email,
// which is the whole errand. A download leaves it in a folder the person then
// has to find, and on Android that folder is not always obvious.
//
// canShare is asked BEFORE the call rather than the call being tried and
// caught, because a platform that cannot share files and a person who
// dismissed the sheet both surface as a rejected promise. Falling back on a
// rejection would mean that cancelling the share sheet silently downloaded a
// copy instead — a second thing happening that nobody asked for.
async function shareAuditReport(receipt, options) {
  const blob = auditReportBlob(receipt, options);
  const filename = auditReportFilename(receipt);

  if (typeof File !== "undefined" && navigator.canShare) {
    const file = new File([blob], filename, { type: "application/pdf" });
    if (navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({ files: [file], title: "GLOOBAL audit report" });
        return { ok: true, via: "share" };
      } catch (error) {
        // Dismissed, or refused mid-flight. The person has seen the sheet.
        return { ok: false, via: "share" };
      }
    }
  }

  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  // Revoking immediately cancels the download on some browsers, which is a
  // bug that only shows on slower devices — exactly the ones this app is for.
  setTimeout(() => URL.revokeObjectURL(url), 10000);
  return { ok: true, via: "download" };
}

// When the report was produced, in the reader's own locale.
//
// This is the ONE figure on the page that is not a record of the transaction,
// so it is generated here rather than taken off the receipt — and the page
// says "Generated" beside it so the two can never be confused. A document
// that showed only transaction dates would leave a reader unable to tell a
// fresh export from one filed months ago.
function formatAuditTimestamp(now) {
  const d = now || new Date();
  try {
    return d.toLocaleString(undefined, {
      day: "numeric", month: "short", year: "numeric",
      hour: "2-digit", minute: "2-digit"
    });
  } catch (error) {
    return d.toISOString().slice(0, 16).replace("T", " ");
  }
}


// src/features/receipts/coinReceipt.js
//
// A Gloobal Coin buy or sell, as a receipt.
//
// ── What this is for ─────────────────────────────────────────────────────
//
// Buying coin used to produce a toast — "Bought 12.50 GEU" — and nothing
// else. The server response carrying the reference id, the fiat paid, the
// currency it was paid in and the rate it converted at was read for one
// field and thrown away. So the one movement in this app that is literally a
// currency exchange was also the only one with no record a person could
// open, and the Coin Activity row beside it said "Minted from balance" and a
// coin figure, which answers neither "how much did that cost me" nor "at
// what rate".
//
// Everything below is a READ of a recorded fact. Nothing here multiplies one
// recorded figure by another to produce a third — see the rate note, which is
// where that temptation is strongest and most wrong.
//
// ── The rate, and why it is not normalised ───────────────────────────────
//
// The two server routes record opposite directions under the same field:
//
//   mint    coinAmount = fiatAmount * geuRate     -> GEU per 1 fiat
//   redeem  fiatAmount = coinAmount * redeemRate  -> fiat per 1 GEU
//
// Both are right for the arithmetic they were computed for. The history
// route now sends `geuRateBasis` saying which, and this module renders the
// rate in the direction it was recorded rather than flipping both into one
// house style. Flipping means dividing, and 1/(a rounded rate) is a number
// that does not reproduce the two amounts printed beside it — a receipt
// whose own figures disagree, which is worse than one that asks the reader
// to read the units.

// What a coin movement is called, from the holder's side.
var COIN_RECEIPT_TITLES = {
  coin_mint: "GLOOBAL Coin bought",
  coin_redeem: "GLOOBAL Coin sold",
  coin_send_out: "GLOOBAL Coin sent",
  coin_send_in: "GLOOBAL Coin received"
};

// The other side of a buy or sell.
//
// A mint is not a payment to a person: the fiat leaves the account and enters
// the reserve that backs the coin, and a redeem returns it. Naming that
// counterparty is what makes the receipt readable as an exchange rather than
// as money that went nowhere. It matches CoinReserve on the server and the
// "backed 1:1 by the reserve" line the Coin screen already shows.
var COIN_RESERVE_NAME = "Gloobal Reserve";

// One row from GET /api/coin/:symbolId/history, plus who is looking at it,
// shaped into the object ReceiptModal renders.
//
// `viewer` carries the three things the person asked to see on it and that
// the movement itself does not record, because they are properties of the
// account rather than of the transaction: { name, symbolId, countryName,
// countryFlag }.
function coinReceiptFrom(row, viewer) {
  if (!row) return null;
  const who = viewer || {};
  const isMint = row.type === "coin_mint";
  const isRedeem = row.type === "coin_redeem";
  const isSend = row.type === "coin_send";
  // "in" means coin arrived: a buy, or a send from somebody else.
  const coinArrived = row.direction === "in";

  const titleKey = isSend ? (coinArrived ? "coin_send_in" : "coin_send_out") : row.type;

  // The hero figure is the COIN, on every one of these, because that is what
  // the account's coin balance moved by and this screen is about the coin.
  // The fiat is the other side of the exchange and is shown as such.
  const coinAmount = Number(row.coinAmount) || 0;
  const fiatAmount = row.fiatAmount == null ? null : Number(row.fiatAmount);
  const fiatCurrency = row.fiatCurrency || null;

  // A send moves no fiat at all. Null rather than 0 throughout: 0 would read
  // as "this cost nothing", which is a claim about price rather than the
  // absence of one.
  const hasFiatLeg = !isSend && fiatAmount != null && fiatCurrency;

  return {
    kind: "coin",
    coinType: row.type,
    title: COIN_RECEIPT_TITLES[titleKey] || "GLOOBAL Coin",
    // Reusing the payment receipt's own vocabulary so the modal needs no
    // third notion of direction: "received" tints green, "sent" red.
    direction: coinArrived ? "received" : "sent",

    // ── The movement ────────────────────────────────────────────────────
    amount: coinAmount,
    currencyCode: row.coinCurrency || "GEU",

    // ── The other side of the exchange ──────────────────────────────────
    //
    // On a buy the fiat left and the coin arrived; on a sell the reverse.
    // Both figures are recorded ones, read straight off the row.
    fiatAmount: hasFiatLeg ? fiatAmount : null,
    fiatCurrencyCode: hasFiatLeg ? fiatCurrency : null,
    // Which way the fiat went, stated rather than derived at the point of
    // display: on a buy it left the bank balance, on a sell it arrived.
    fiatDirection: isMint ? "out" : isRedeem ? "in" : null,

    // ── The rate, in the direction it was recorded ──────────────────────
    rate: row.geuRate == null ? null : Number(row.geuRate),
    rateBasis: row.geuRateBasis || null,
    rateSource: row.geuRateSource || null,

    // ── Who ─────────────────────────────────────────────────────────────
    //
    // The holder, on both sides of the receipt, because a buy and a sell are
    // between a person and the reserve. The name, the Gloobal ID and the
    // country are the account's, not the movement's — the movement records
    // none of them, and putting them on the receipt is the point of this
    // change.
    holderName: who.name || null,
    holderSymbolId: who.symbolId || row.counterpartySymbolId || null,
    holderCountryName: who.countryName || null,
    holderCountryFlag: who.countryFlag || null,

    // On a buy or sell the counterparty is the reserve. On a send it is a
    // real account, and the server already resolved its name and ID.
    counterpartyName: isSend ? (row.counterpartyName || row.counterpartySymbolId || "Another account") : COIN_RESERVE_NAME,
    counterpartySymbolId: isSend ? row.counterpartySymbolId || null : null,

    // `name` and `id` are what ReceiptModal's counterparty box already
    // reads, so a coin receipt fills them rather than making that box learn
    // a third shape. They resolve the right way round on their own: a buy
    // has direction "received", which the modal labels "From" — and the coin
    // did come from the reserve. A sell reads "To Gloobal Reserve".
    name: isSend ? (row.counterpartyName || row.counterpartySymbolId || "Another account") : COIN_RESERVE_NAME,
    id: isSend ? row.counterpartySymbolId || null : null,
    // The reserve is not in a country, so a buy carries no counterparty flag
    // rather than borrowing the holder's — which would draw the person's own
    // flag on the far side and read as a payment to themselves.
    counterpartyCountryIso: isSend ? row.counterpartyCountryIso || null : null,

    // ── Provenance ──────────────────────────────────────────────────────
    txnId: row.referenceId || null,
    referenceId: row.referenceId || null,
    reserveCurrencyCode: row.reserveCurrency || null,
    note: row.note || "",
    ...coinReceiptStamp(row.createdAt),

    // A coin movement carries no Creator Share and never did. Stated as
    // zero/absent rather than left undefined so ReceiptModal's hasShareEvent
    // cannot read a stale value and offer a tab for a movement that has no
    // second leg — the shape of a defect this file has already produced once.
    shareRate: 0,
    shareAmount: 0,
    shareTxnId: null,
    // No "Payment method" row. On a buy the method was the bank balance and
    // on a sell it was the coin — both of which the block above already
    // states, in full, with the amounts. A row repeating one of them under a
    // label that calls this a payment adds nothing and miscalls it.
    // ReceiptRow renders nothing for a falsy value, so this removes the row.
    method: null,
    status: "success"
  };
}

// The same "Sep 3" / "14:07:32" pair every other receipt and row in the app
// carries, derived from the server's timestamp.
//
// Empty strings rather than invented values when the stamp cannot be parsed:
// historyRowStamp renders a dateless row as nothing at all, which is honest,
// where a fabricated "now" would date somebody's purchase to whenever they
// happened to open it.
function coinReceiptStamp(createdAt) {
  if (!createdAt) return { date: "", time: "" };
  const posted = new Date(createdAt);
  if (isNaN(posted.getTime())) return { date: "", time: "" };
  return {
    date: posted.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
    time: formatClockTime(posted)
  };
}

// The rate as a sentence, in the direction it was recorded.
//
// Returns null when there is no rate rather than a placeholder: a send has
// none, and neither does a row written before the field existed. The caller
// draws nothing, which is the same rule the payment receipt's conversion
// block follows — a "1.000000" on a movement that converted nothing states
// that an exchange took place.
function coinRateSentence(receipt) {
  if (!receipt || receipt.rate == null || !receipt.rateBasis) return null;
  const coin = receipt.currencyCode || "GEU";
  const fiat = receipt.fiatCurrencyCode;
  if (!fiat) return null;
  // Six places, because a GEU rate against a currency like IDR or VND is a
  // small number and two places would round several of them to 0.00 — a rate
  // of zero on a receipt whose amounts are plainly non-zero.
  const shown = formatCoinRate(receipt.rate);
  return receipt.rateBasis === "coin-per-fiat"
    ? `1 ${fiat} = ${shown} ${coin}`
    : `1 ${coin} = ${shown} ${fiat}`;
}

// Trailing zeros trimmed, so a 1:1 peg reads "1" rather than "1.000000",
// while a small rate keeps the places it needs.
function formatCoinRate(rate) {
  const n = Number(rate);
  if (!Number.isFinite(n)) return "";
  return String(Number(n.toFixed(6)));
}

// Every row from the coin history, newest first, as receipts — so the Coin
// Activity list and the receipt behind each row are built from one mapping
// rather than two that can disagree.
function coinReceiptsFrom(rows, viewer) {
  if (!Array.isArray(rows)) return [];
  return rows.map((row) => coinReceiptFrom(row, viewer)).filter(Boolean);
}


// src/features/receipts/receiptImage.js

// ── The receipt, as a picture ────────────────────────────────────────────
//
// A compact "payment successful" card that can be handed straight to the
// phone's share sheet as a PNG — the thing people actually forward on
// WhatsApp after paying someone. Gloobal's own identity throughout: the G
// logo, the GL●●BAL wordmark redrawn by hand, the theme's gradients, and the
// Hooman to Hooman mark and tagline INSIDE the image, as part of the card
// rather than an advert stapled to its foot.
//
// Two halves, deliberately split:
//
//   buildReceiptImageModel  PURE. Decides every word and figure that ends up
//                           on the image. This is where the rules live, and
//                           it is what the tests read.
//   renderReceiptImage      Draws the model and nothing else. It makes no
//                           decision about what is true.
//
// ── Rules the model keeps ────────────────────────────────────────────────
//
//   - Every figure is a RECORDED one. The conversion block prints the
//     server's own sender debit, receiver credit and rate; nothing is
//     multiplied, divided or inverted here (see ReceiptModal's fxRateLabel
//     for why the rate stays in its stored direction).
//   - Nothing on it reads as a request for money. No QR, no link, no "pay"
//     wording — a forwarded receipt must never be mistaken for something to
//     act on. The reference and receipt code identify it; that is all.
//   - Nobody's face is on it. The counterparty's photo was drawn here and
//     is not any more — see "Who it was" below for why the fallback disc was
//     the worse half of that. Nothing in this file loads a photo, so a
//     forwarded receipt cannot carry one and the canvas cannot be tainted by
//     one either.

var RECEIPT_IMAGE_BRAND = {
  wordmark: "GLOOBAL",
  hooman: "Hooman to Hooman",
  tagline: "Cashless · Textless · Borderless · Limitless"
};

var RECEIPT_IMAGE_DOT_COLORS = ["#2563EB", "#DC2626", "#EA580C", "#059669", "#9333EA", "#DB2777"];

function receiptImageCountry(receipt) {
  const list = typeof ALL_COUNTRIES !== "undefined" && Array.isArray(ALL_COUNTRIES) ? ALL_COUNTRIES : [];
  const iso = receipt.counterpartyIso ? String(receipt.counterpartyIso).toUpperCase() : "";
  const match = (receipt.flag && list.find((c) => c.flag === receipt.flag)) ||
    (iso && list.find((c) => c.iso === iso)) || null;
  if (!match && !receipt.flag) return null;
  return {
    name: match ? match.name : "",
    flag: receipt.flag || (match ? match.flag : ""),
    iso: match ? String(match.iso).toLowerCase() : (iso ? iso.toLowerCase() : "")
  };
}

// ── EVERY FIGURE ON THE PICTURE CARRIES BOTH NAMES ──────────────────────
//
// This file draws the one thing Gloobal makes that LEAVES Gloobal: the
// receipt picture a person sends into a chat, where it is seen by people who
// may never have opened the app. It was the last surface still printing a
// figure under one name, which made it the worst one — a picture of
// "500.00₹" with no GEU anywhere says Gloobal is a rupee app, and a picture
// of "500.00 GEU" with no rupee says nothing a stranger can price.
//
// WHICH LENS THE PICTURE IS IN is the sender's, by the founder's decision:
// the picture looks like the screen they were looking at when they shared
// it. The pair is on it either way, so the reader is never left completing a
// unit from their own country — only the order of the two names changes.
//
// `lens` is optional and absent means no relabelling, because the model is
// pure and is built with no lens at all by the preview path and the tests.
// Falling back to fmtMoney there is right: a figure with one true name is
// better than a figure wearing a lens nobody chose.
function receiptImageMoney(amount, currency, lens, ownCurrency) {
  const n = Number(amount);
  if (!Number.isFinite(n)) return "";
  if (!currency) return fmt(n);
  if (!lens) return fmtMoney(n, currency);
  return geuLensBarMoney(n, currency, lens, ownCurrency || currency);
}

function buildReceiptImageModel(receipt, { viewerName, viewerSymbolId, lens, viewerCurrency } = {}) {
  const r = receipt || {};
  const isShare = r.kind === "share";
  const isCoin = r.kind === "coin";
  const isSent = r.direction === "sent";
  const status = r.status === "pending" ? "pending" : r.status === "simulated" ? "simulated" : "completed";

  let headline;
  if (status === "pending") headline = "Payment Pending";
  else if (status === "simulated") headline = "Not Sent · Simulated";
  else if (isCoin) headline = r.title || "GLOOBAL Coin";
  else headline = isSent ? "Payment Successful" : "Money Received";

  // The hero figure is the row's own. On a Creator Share receipt the row IS
  // the share, so its figure is read, never worked out from a rate.
  const currency = r.currencyCode || null;
  const heroAmount = isShare
    ? (r.shareAmount != null ? r.shareAmount : r.amount)
    : r.amount;
  const amountText = receiptImageMoney(heroAmount, currency, lens, viewerCurrency);

  const counterpartyName = r.name ? String(r.name) : "";
  const counterpartyId = r.id ? String(r.id).replace(/\s/g, "") : "";
  const viewer = viewerName ? String(viewerName) : "";

  // The same facts, by the same rule, as the receipt screen draws for this
  // document (receiptCurrency.js): a payment's conversion on a payment, the
  // share's own two sides on a share. The two used to disagree — this file
  // refused a conversion with no recorded rate that the screen showed, and a
  // share picture carried one currency of a movement with two. A missing
  // rate now means no rate row, never a rate worked out from the amounts.
  const facts = isShare ? receiptShareConversion(r) : receiptPaymentConversion(r);
  const conversion = facts
    ? {
      sentText: receiptImageMoney(facts.paidAmount, facts.paidCurrency, lens, viewerCurrency),
      receivedText: receiptImageMoney(facts.gotAmount, facts.gotCurrency, lens, viewerCurrency),
      rateText: facts.rateLabel
    }
    : null;

  // ── The Creator Share, always ────────────────────────────────────────
  //
  // Always, including when it is zero. A row that disappears at 0% and a row
  // that reads 0% say different things to somebody reading a forwarded
  // receipt: the first leaves them to assume a share was taken and not shown.
  // Only the second is true.
  //
  // The AMOUNT is read, not worked out, by the same rule ReceiptModal states
  // at `shownShareAmount`: the figure the server recorded wins, and the
  // multiplication below is only the fallback for a payment this device
  // settled locally and for which no share leg exists. The two round
  // differently in the last minor unit, and a receipt whose share does not
  // reconcile with the ledger is worse than one that shows the plainer
  // figure. A recorded 0 counts as "not recorded" — every builder defaults an
  // absent share to 0 — so it falls through to the multiplication, which is
  // also 0 when the rate is 0.
  const shareRatePercent = Number(r.shareRate) || 0;
  const recordedShare = Number(r.shareAmount);
  const shareAmountValue = isShare
    ? (Number(r.shareAmount) || Number(r.amount) || 0)
    : (Number.isFinite(recordedShare) && recordedShare > 0
      ? recordedShare
      : (Number(r.amount) || 0) * (shareRatePercent / 100));
  // Trimmed rather than fixed to two places: "20%" not "20.00%", but "2.5%"
  // keeps its half.
  const shareRateText = `${Number(shareRatePercent.toFixed(2))}%`;

  return {
    headline,
    status,
    // What the purple zone says above the figure. On a completed payment it
    // names the DIRECTION, because the status is carried by the mark at the
    // foot; on anything else it is the headline, so a pending or simulated
    // payment says so at the top of the card as well as the bottom.
    //
    // A Creator Share says so instead of "Money received". The direction is
    // true but it is not what this row IS, and with the share chip now on
    // every receipt, a share receipt labelled "Money received" reads as an
    // ordinary payment that happens to carry a share of exactly its own size.
    heroLabel: status === "completed"
      ? (isShare ? "Creator Share" : isCoin ? (r.title || "GLOOBAL Coin") : isSent ? "Money sent" : "Money received")
      : headline,
    // The figure as the card prints it: a MINUS on money that left, nothing
    // on money that arrived.
    //
    // A sign, not a colour — this figure is white on the brand gradient, and
    // a red-for-out/green-for-in scheme would either fight that ground or be
    // invisible on it. The minus survives a greyscale print, a screenshot and
    // a colour-blind reader, which is what a record has to do.
    //
    // No "+" on the received side. A leading plus on a receipt reads as an
    // adjustment or a credit note rather than as money arriving, and the
    // label above it already says which way it went.
    //
    // amountText stays unsigned: it is the formatted figure, and the sign is
    // a presentation decision about direction, made here in the model so the
    // renderer keeps making none.
    heroAmountText: isSent && amountText ? `−${amountText}` : amountText,
    shareRate: shareRatePercent,
    shareRateText,
    shareAmountText: receiptImageMoney(shareAmountValue, currency, lens, viewerCurrency),
    shareText: `${shareRateText} \u00b7 ${receiptImageMoney(shareAmountValue, currency, lens, viewerCurrency)}`,
    // What the chip on the purple says. On a share receipt the figure above
    // IS the share amount, so repeating it under a "Creator Share" eyebrow
    // says the same thing three times; the rate is the part not already
    // shown. Everywhere else the chip carries both, at zero included.
    shareChipLabel: isShare ? "Share rate" : "Creator share",
    shareChipValue: isShare ? shareRateText : `${shareRateText} \u00b7 ${receiptImageMoney(shareAmountValue, currency, lens, viewerCurrency)}`,
    kind: isShare ? "share" : isCoin ? "coin" : "payment",
    kindLabel: isShare ? "Creator Share" : "",
    direction: isSent ? "sent" : "received",
    amountText,
    currency,
    counterpartyLabel: isSent ? "To" : "From",
    counterpartyName,
    counterpartyId,
    counterpartyCountry: receiptImageCountry(r),
    senderName: isSent ? viewer : counterpartyName,
    receiverName: isSent ? counterpartyName : viewer,
    viewerLabel: isSent ? "Sent by" : "Received by",
    viewerName: viewer,
    viewerSymbolId: viewerSymbolId ? String(viewerSymbolId).replace(/\s/g, "") : "",
    date: r.date ? String(r.date) : "",
    time: r.time ? String(r.time) : "",
    referenceLabel: "Transaction ID",
    reference: r.txnId ? String(r.txnId).replace(/\s/g, "") : "",
    receiptCode: r.receiptCode ? String(r.receiptCode) : "",
    conversion,
    brand: { ...RECEIPT_IMAGE_BRAND }
  };
}

// ── Drawing ──────────────────────────────────────────────────────────────

var RECEIPT_IMAGE_FONT_BODY = "Inter, 'Segoe UI', -apple-system, system-ui, sans-serif";
var RECEIPT_IMAGE_FONT_DISPLAY = "'Space Grotesk', Inter, 'Segoe UI', system-ui, sans-serif";
var RECEIPT_IMAGE_FONT_MONO = "'Segoe UI Symbol', 'Noto Sans Symbols 2', 'DejaVu Sans Mono', ui-monospace, monospace";

function receiptImageLoad(src, { crossOrigin, timeoutMs = 4000 } = {}) {
  return new Promise((resolve) => {
    if (!src || typeof Image === "undefined") return resolve(null);
    let settled = false;
    const done = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    try {
      const img = new Image();
      if (crossOrigin) img.crossOrigin = crossOrigin;
      img.onload = () => done(img.naturalWidth || img.width ? img : null);
      img.onerror = () => done(null);
      setTimeout(() => done(null), timeoutMs);
      img.src = src;
    } catch {
      done(null);
    }
  });
}

// The G logo in a single flat colour, for use on gradients.
function receiptImageTint(img, color) {
  try {
    const c = document.createElement("canvas");
    c.width = img.naturalWidth || img.width;
    c.height = img.naturalHeight || img.height;
    const x = c.getContext("2d");
    x.drawImage(img, 0, 0);
    x.globalCompositeOperation = "source-in";
    x.fillStyle = color;
    x.fillRect(0, 0, c.width, c.height);
    return c;
  } catch {
    return null;
  }
}

function receiptImageEllipsis(ctx, text, maxWidth) {
  const s = String(text || "");
  if (ctx.measureText(s).width <= maxWidth) return s;
  const chars = Array.from(s);
  let lo = 0;
  let hi = chars.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (ctx.measureText(chars.slice(0, mid).join("").trimEnd() + "…").width <= maxWidth) lo = mid;
    else hi = mid - 1;
  }
  return chars.slice(0, lo).join("").trimEnd() + "…";
}

// Largest size (down to `min`) at which `text` fits; the caller ellipsises
// whatever still does not.
function receiptImageFit(ctx, text, fontFor, max, min, maxWidth) {
  let size = max;
  ctx.font = fontFor(size);
  while (size > min && ctx.measureText(text).width > maxWidth) {
    size -= 1;
    ctx.font = fontFor(size);
  }
  return size;
}

function receiptImageRoundRect(ctx, x, y, w, h, r) {
  const rr = Array.isArray(r) ? r : [r, r, r, r];
  ctx.beginPath();
  ctx.moveTo(x + rr[0], y);
  ctx.lineTo(x + w - rr[1], y);
  ctx.arcTo(x + w, y, x + w, y + rr[1], rr[1]);
  ctx.lineTo(x + w, y + h - rr[2]);
  ctx.arcTo(x + w, y + h, x + w - rr[2], y + h, rr[2]);
  ctx.lineTo(x + rr[3], y + h);
  ctx.arcTo(x, y + h, x, y + h - rr[3], rr[3]);
  ctx.lineTo(x, y + rr[0]);
  ctx.arcTo(x, y, x + rr[0], y, rr[0]);
  ctx.closePath();
}

function receiptImageHash(text) {
  let h = 7;
  for (const ch of String(text || "")) h = (h * 31 + ch.codePointAt(0)) >>> 0;
  return h;
}

// "GL●●BAL", left-aligned at (x, baseline). Returns the width drawn.
function receiptImageDrawWordmark(ctx, x, baseline, size, color, dotColors, { measureOnly = false } = {}) {
  ctx.font = `800 ${size}px ${RECEIPT_IMAGE_FONT_BODY}`;
  const d = size * 0.72;
  const gap = size * 0.035;
  const w1 = ctx.measureText("GL").width;
  const w2 = ctx.measureText("BAL").width;
  const total = w1 + gap + d + gap * 2 + d + gap + w2;
  if (measureOnly) return total;
  ctx.fillStyle = color;
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.fillText("GL", x, baseline);
  const cy = baseline - size * 0.36;
  let cx = x + w1 + gap + d / 2;
  for (let i = 0; i < 2; i++) {
    ctx.beginPath();
    ctx.arc(cx, cy, d / 2, 0, Math.PI * 2);
    ctx.fillStyle = dotColors[i];
    ctx.fill();
    cx += d + gap * 2;
  }
  ctx.fillStyle = color;
  ctx.fillText("BAL", x + w1 + gap + d + gap * 2 + d + gap, baseline);
  return total;
}

// "H●●MAN T● H●●MAN", centred on cx. The circles stand in for the O's, the
// same as HoomanMark in brand.jsx.
function receiptImageDrawHooman(ctx, cx, baseline, size, color, dotColors, hoomanText) {
  ctx.font = `800 ${size}px ${RECEIPT_IMAGE_FONT_BODY}`;
  const d = size * 0.78;
  const gap = size * 0.05;
  const space = size * 0.55;
  // Parse the brand string rather than hardcoding the letters, so the mark
  // on the image is always the brand text, upper-cased, with its O's as dots.
  const parts = [];
  const upper = String(hoomanText).toUpperCase();
  for (const ch of upper) {
    if (ch === "O") parts.push({ dot: true });
    else if (ch === " ") parts.push({ space: true });
    else if (parts.length && parts[parts.length - 1].text != null) parts[parts.length - 1].text += ch;
    else parts.push({ text: ch });
  }
  const widthOf = (p) => (p.dot ? d + gap * 2 : p.space ? space : ctx.measureText(p.text).width);
  const total = parts.reduce((sum, p) => sum + widthOf(p), 0);
  let x = cx - total / 2;
  let dotIndex = 0;
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  for (const p of parts) {
    if (p.dot) {
      ctx.beginPath();
      ctx.arc(x + gap + d / 2, baseline - size * 0.36, d / 2, 0, Math.PI * 2);
      ctx.fillStyle = dotColors[dotIndex++ % dotColors.length];
      ctx.fill();
    } else if (p.text) {
      ctx.fillStyle = color;
      ctx.fillText(p.text, x, baseline);
    }
    x += widthOf(p);
  }
  // The accessible string, drawn invisibly so the exact brand text is part
  // of what was painted (and of what a text-extracting reader finds).
  ctx.save();
  ctx.globalAlpha = 0;
  ctx.textAlign = "center";
  ctx.font = `600 2px ${RECEIPT_IMAGE_FONT_BODY}`;
  ctx.fillText(hoomanText, cx, baseline);
  ctx.restore();
}

// An uppercase eyebrow with real tracking. ctx.letterSpacing exists in
// Chromium only, and a label set solid reads as a mistake at this size, so
// the gaps are placed by hand. Returns the width drawn.
function receiptImageDrawTracked(ctx, text, cx, baseline, { size = 11, weight = 800, color = "#FFFFFF", tracking = 1.6, align = "center" } = {}) {
  ctx.font = `${weight} ${size}px ${RECEIPT_IMAGE_FONT_BODY}`;
  const chars = Array.from(String(text || ""));
  const widths = chars.map((ch) => ctx.measureText(ch).width + tracking);
  const total = widths.reduce((a, b) => a + b, 0) - (chars.length ? tracking : 0);
  let x = align === "center" ? cx - total / 2 : align === "right" ? cx - total : cx;
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = color;
  chars.forEach((ch, i) => {
    ctx.fillText(ch, x, baseline);
    x += widths[i];
  });
  return total;
}

// Symbols one colour each, the way ColoredGloobalId draws them. Shrinks to
// fit, then ellipsises.
function receiptImageDrawSymbols(ctx, text, x, baseline, maxWidth, { size = 17, align = "left", colored = true, color } = {}) {
  const fontFor = (s) => `700 ${s}px ${RECEIPT_IMAGE_FONT_MONO}`;
  const s = receiptImageFit(ctx, text, fontFor, size, 11, maxWidth);
  ctx.font = fontFor(s);
  const shown = receiptImageEllipsis(ctx, text, maxWidth);
  const chars = Array.from(shown);
  const widths = chars.map((ch) => ctx.measureText(ch).width);
  const total = widths.reduce((a, b) => a + b, 0);
  let cx = align === "right" ? x - total : align === "center" ? x - total / 2 : x;
  const palette = typeof POSITION_COLORS !== "undefined" ? POSITION_COLORS : RECEIPT_IMAGE_DOT_COLORS;
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  chars.forEach((ch, i) => {
    ctx.fillStyle = colored && ch !== "…" ? palette[i % palette.length] : (color || "#15132A");
    ctx.fillText(ch, cx, baseline);
    cx += widths[i];
  });
}

async function receiptImageWaitForFonts() {
  if (typeof document === "undefined" || !document.fonts) return;
  const timeout = new Promise((resolve) => setTimeout(resolve, 2500));
  try {
    const loads = [
      `800 30px Inter`, `700 16px Inter`, `600 14px Inter`, `700 48px 'Space Grotesk'`
    ].map((f) => (document.fonts.load ? document.fonts.load(f).catch(() => null) : null));
    await Promise.race([Promise.all(loads), timeout]);
    if (document.fonts.ready) await Promise.race([document.fonts.ready, timeout]);
  } catch {
  }
}

async function renderReceiptImage(model, { scale = 2 } = {}) {
  const m = model || buildReceiptImageModel({});
  const theme = typeof T !== "undefined" ? T : {};
  const INK = theme.ink || "#15132A";
  const INK_SOFT = theme.inkSoft || "#6B6580";
  const INK_FAINT = theme.inkFaint || "#9C96AF";
  const LINE = theme.line || "#EAE6F7";
  const SURFACE_ALT = theme.surfaceAlt || "#F3F1FA";
  const ACCENT = theme.accent || "#7C3AED";
  const POSITIVE = theme.positive || "#0FA372";
  const POSITIVE_SOFT = theme.positiveSoft || "#E3F8EE";

  await receiptImageWaitForFonts();

  const logoSrc = typeof G_LOGO_DATA_URI !== "undefined" ? G_LOGO_DATA_URI : null;
  const country = m.counterpartyCountry;
  const [logo, flag] = await Promise.all([
    receiptImageLoad(logoSrc),
    // flagcdn serves `Access-Control-Allow-Origin: *`, so an anonymous load
    // keeps the canvas exportable. If it ever stops, the load fails rather
    // than tainting, and the country is written out without its flag.
    country && country.iso
      ? receiptImageLoad(`https://flagcdn.com/w160/${country.iso}.png`, { crossOrigin: "anonymous", timeoutMs: 3000 })
      : Promise.resolve(null)
  ]);
  const whiteLogo = logo ? receiptImageTint(logo, "#FFFFFF") : null;

  const s = Math.max(1, Number(scale) || 2);
  const W = 540;
  const MARGIN = 22;
  const CX = MARGIN;
  const CW = W - MARGIN * 2;
  const PAD = 26;
  const INNER = CW - PAD * 2;

  const seed = receiptImageHash(m.reference || m.receiptCode || m.counterpartyName);
  const dotA = RECEIPT_IMAGE_DOT_COLORS[seed % RECEIPT_IMAGE_DOT_COLORS.length];
  // Two different colours, as the live wordmark always has.
  const dotB = RECEIPT_IMAGE_DOT_COLORS[(seed + 1 + ((seed >>> 3) % (RECEIPT_IMAGE_DOT_COLORS.length - 1))) % RECEIPT_IMAGE_DOT_COLORS.length];
  const hoomanDots = [0, 1, 4, 2, 3].map((i) => RECEIPT_IMAGE_DOT_COLORS[(seed + i * 2) % RECEIPT_IMAGE_DOT_COLORS.length]);

  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  const ops = [];
  // Assigned once the card's height is known, and read by the ops, which all
  // run after that. The perforation notches are filled with this same
  // gradient object rather than a stand-in purple, so they match the card
  // exactly at whatever height it ends up.
  let cardGradient = null;

  // ── N3: the figure on the brand, the facts on white ─────────────────────
  //
  // The card used to be white with a purple strip across the top, and the
  // headline, the tick and the amount all competed for the same middle. This
  // inverts it. The whole card is the brand gradient and carries exactly one
  // thing — what happened and how much — and every fact that has to be read
  // back later sits on a white panel floating inside it.
  //
  // The split is the point: the purple is glanceable at thumbnail size in a
  // chat, and the white panel is the part somebody forwards to an accountant.
  // Nothing appears in both.
  const CARD_TOP = MARGIN;
  const PANEL_INSET = 14;
  const PANEL_X = CX + PANEL_INSET;
  const PANEL_W = CW - PANEL_INSET * 2;
  const PANEL_PAD = 24;
  const PW = PANEL_W - PANEL_PAD * 2;
  const PLX = PANEL_X + PANEL_PAD;
  const PRX = PANEL_X + PANEL_W - PANEL_PAD;
  const PCX = CX + CW / 2;

  // ── The brand zone ──
  let y = CARD_TOP + 44;

  const wordBase = y;
  ops.push(() => {
    const markSize = 23;
    const logoH = 30;
    const logoW = whiteLogo ? logoH * (whiteLogo.width / whiteLogo.height) : 0;
    const wordW = receiptImageDrawWordmark(ctx, 0, 0, markSize, "#FFFFFF", [dotA, dotB], { measureOnly: true });
    const groupW = logoW + (logoW ? 9 : 0) + wordW;
    const gx = PCX - groupW / 2;
    if (whiteLogo) ctx.drawImage(whiteLogo, gx, wordBase - logoH * 0.78, logoW, logoH);
    receiptImageDrawWordmark(ctx, gx + logoW + (logoW ? 9 : 0), wordBase, markSize, "#FFFFFF", [dotA, dotB]);
  });
  y = wordBase + 40;

  const eyebrowBase = y;
  ops.push(() => {
    receiptImageDrawTracked(ctx, String(m.heroLabel || "").toUpperCase(), PCX, eyebrowBase, {
      size: 11.5, weight: 800, color: "rgba(255,255,255,0.72)", tracking: 2.4
    });
  });
  y = eyebrowBase + 54;

  const figureBase = y;
  ops.push(() => {
    const text = m.heroAmountText || m.amountText || "—";
    ctx.textAlign = "center";
    ctx.textBaseline = "alphabetic";
    const size = receiptImageFit(ctx, text, (z) => `700 ${z}px ${RECEIPT_IMAGE_FONT_DISPLAY}`, 52, 26, PW);
    ctx.font = `700 ${size}px ${RECEIPT_IMAGE_FONT_DISPLAY}`;
    ctx.fillStyle = "#FFFFFF";
    ctx.fillText(receiptImageEllipsis(ctx, text, PW), PCX, figureBase);
  });
  y = figureBase;

  // The ISO code under the figure, because a bare $ or ¥ is ambiguous. Not
  // repeated when the figure already ends in it ("1,450.25 CHF").
  const showCode = !!(m.currency && !String(m.amountText || "").endsWith(m.currency));
  if (showCode) {
    const codeBase = y + 26;
    ops.push(() => {
      receiptImageDrawTracked(ctx, m.currency, PCX, codeBase, {
        size: 12.5, weight: 700, color: "rgba(255,255,255,0.78)", tracking: 1.8
      });
    });
    y = codeBase;
  }

  // ── The Creator Share chip, on every receipt ──
  //
  // Including at zero, and that is the whole reason it is here rather than in
  // the detail rows. A chip that vanishes when the rate is 0% leaves a reader
  // to assume a share was taken and not shown; "0% · 0.00₹" is the only
  // version of that which is true. At zero it is drawn quieter, not hidden.
  const shareTop = y + 26;
  const SHARE_H = 30;
  ops.push(() => {
    const zero = !(Number(m.shareRate) > 0);
    const label = String(m.shareChipLabel || "Creator share");
    const value = String(m.shareChipValue || m.shareText || "");
    ctx.font = `700 12.5px ${RECEIPT_IMAGE_FONT_BODY}`;
    const labelW = ctx.measureText(label).width;
    ctx.font = `700 13px ${RECEIPT_IMAGE_FONT_BODY}`;
    const valueW = ctx.measureText(value).width;
    const chipW = labelW + 10 + valueW + 32;
    const chipX = PCX - chipW / 2;
    receiptImageRoundRect(ctx, chipX, shareTop, chipW, SHARE_H, SHARE_H / 2);
    ctx.fillStyle = zero ? "rgba(255,255,255,0.10)" : "rgba(255,255,255,0.18)";
    ctx.fill();
    ctx.strokeStyle = zero ? "rgba(255,255,255,0.16)" : "rgba(255,255,255,0.30)";
    ctx.lineWidth = 1;
    ctx.stroke();
    const base = shareTop + SHARE_H / 2 + 4.5;
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.font = `700 12.5px ${RECEIPT_IMAGE_FONT_BODY}`;
    ctx.fillStyle = zero ? "rgba(255,255,255,0.55)" : "rgba(255,255,255,0.78)";
    ctx.fillText(label, chipX + 16, base);
    ctx.textAlign = "left";
    ctx.font = `700 13px ${RECEIPT_IMAGE_FONT_BODY}`;
    ctx.fillStyle = zero ? "rgba(255,255,255,0.72)" : "#FFFFFF";
    ctx.fillText(value, chipX + 16 + labelW + 10, base);
  });
  y = shareTop + SHARE_H;

  // ── The white panel ──
  const panelTop = y + 26;
  const panelBox = { h: 0 };
  ops.push(() => {
    receiptImageRoundRect(ctx, PANEL_X, panelTop, PANEL_W, panelBox.h, 22);
    ctx.fillStyle = "#FFFFFF";
    ctx.fill();
  });

  let py = panelTop + 10;

  // ── The rows ─────────────────────────────────────────────────────────────
  //
  // Every fact as a label/value row, the conversion included. An earlier pass
  // led with a large centred name and gave the conversion a filled box of its
  // own; both pulled the eye away from the figure on the purple, which is the
  // one thing this card exists to show. Flat rows read faster, and they let
  // the conversion sit WITH the other facts instead of announcing itself as a
  // separate event.
  //
  // The rate keeps its stored direction — see ReceiptModal's fxRateLabel.
  // Printing "1 EUR = 91.80 INR" when the server recorded the other way round
  // means inverting a number and calling it a record, which is the one thing
  // this file must never do.
  const panelRows = [];
  panelRows.push({ label: m.counterpartyLabel, value: m.counterpartyName || "—", flag: true });
  if (m.counterpartyId) panelRows.push({ label: "GLOOBAL ID", value: m.counterpartyId, symbols: true });
  if (m.conversion) {
    panelRows.push({ label: "Sent", value: m.conversion.sentText });
    panelRows.push({ label: "Received", value: m.conversion.receivedText });
    if (m.conversion.rateText) panelRows.push({ label: "Rate applied", value: m.conversion.rateText, accent: true });
  }
  if (m.viewerName) panelRows.push({ label: m.viewerLabel, value: m.viewerName });
  const whenText = [m.date, m.time].filter(Boolean).join(" · ");
  if (whenText) {
    panelRows.push({ label: m.date && m.time ? "Date · Time" : (m.date ? "Date" : "Time"), value: whenText });
  }
  if (m.receiptCode) panelRows.push({ label: "Receipt code", value: m.receiptCode, mono: true });

  const ROW_H = 40;
  const rowsTop = py;
  ops.push(() => {
    panelRows.forEach((row, i) => {
      const top = rowsTop + i * ROW_H;
      const base = top + ROW_H / 2 + 5;
      if (i > 0) {
        ctx.beginPath();
        ctx.moveTo(PLX, top);
        ctx.lineTo(PRX, top);
        ctx.strokeStyle = LINE;
        ctx.lineWidth = 1;
        ctx.stroke();
      }
      ctx.textAlign = "left";
      ctx.textBaseline = "alphabetic";
      ctx.font = `600 13.5px ${RECEIPT_IMAGE_FONT_BODY}`;
      ctx.fillStyle = INK_SOFT;
      ctx.fillText(row.label, PLX, base);
      const labelW = ctx.measureText(row.label).width;

      // The flag rides at the right edge and the name is measured to stop
      // short of it, rather than the name being placed and the flag pushed
      // past the panel — which is how a long name loses its country.
      const fr = 8.5;
      const wantsFlag = !!(row.flag && flag);
      const rightEdge = wantsFlag ? PRX - fr * 2 - 8 : PRX;
      const maxW = rightEdge - PLX - labelW - 20;

      if (row.symbols) {
        receiptImageDrawSymbols(ctx, row.value, rightEdge, base, maxW, { size: 15, align: "right" });
      } else {
        ctx.textAlign = "right";
        ctx.font = row.mono
          ? `700 14.5px ui-monospace, 'Cascadia Mono', Consolas, monospace`
          : `700 14.5px ${RECEIPT_IMAGE_FONT_BODY}`;
        ctx.fillStyle = row.accent ? ACCENT : INK;
        ctx.fillText(receiptImageEllipsis(ctx, row.value, maxW), rightEdge, base);
      }

      if (wantsFlag) {
        const fx = PRX - fr;
        const fy = base - 5;
        ctx.save();
        ctx.beginPath();
        ctx.arc(fx, fy, fr, 0, Math.PI * 2);
        ctx.clip();
        const iw = flag.naturalWidth || flag.width;
        const ih = flag.naturalHeight || flag.height;
        const side = Math.min(iw, ih);
        ctx.drawImage(flag, (iw - side) / 2, (ih - side) / 2, side, side, fx - fr, fy - fr, fr * 2, fr * 2);
        ctx.restore();
        ctx.beginPath();
        ctx.arc(fx, fy, fr, 0, Math.PI * 2);
        ctx.strokeStyle = LINE;
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    });
  });
  py = rowsTop + panelRows.length * ROW_H;

  // The one line the rows cannot carry. A rate with no date attached invites
  // being read as today's, and a forwarded receipt is read long after the day
  // it was made.
  if (m.conversion) {
    const noteBase = py + 18;
    ops.push(() => {
      ctx.textAlign = "left";
      ctx.textBaseline = "alphabetic";
      ctx.font = `600 11px ${RECEIPT_IMAGE_FONT_BODY}`;
      ctx.fillStyle = INK_FAINT;
      ctx.fillText("As settled at the time of this transaction, not a current rate.", PLX, noteBase);
    });
    py = noteBase + 4;
  }

  // ── Transaction ID, in its own block ──
  //
  // Not one of the rows above. It is the thing somebody quotes back when this
  // payment has to be found again, it is twelve coloured symbols rather than
  // a word, and right-aligned in a row it shrank until it could not be read
  // off a screenshot. Outlined rather than filled: on a white panel a filled
  // block reads as a second card.
  if (m.reference) {
    const refTop = py + 20;
    const REF_H = 66;
    ops.push(() => {
      receiptImageRoundRect(ctx, PLX, refTop, PW, REF_H, 14);
      ctx.strokeStyle = LINE;
      ctx.lineWidth = 1.5;
      ctx.stroke();
      receiptImageDrawTracked(ctx, String(m.referenceLabel).toUpperCase(), PCX, refTop + 25, {
        size: 10, weight: 800, color: INK_FAINT, tracking: 2
      });
      receiptImageDrawSymbols(ctx, m.reference, PCX, refTop + 50, PW - 32, { size: 18, align: "center" });
    });
    py = refTop + REF_H;
  }

  // ── Status ──
  const pillTop = py + 22;
  const PILL_H = 34;
  ops.push(() => {
    const done = m.status === "completed";
    const tone = m.status === "pending" ? "#B45309" : m.status === "simulated" ? INK_SOFT : POSITIVE;
    const wash = m.status === "pending" ? "#FEF3C7" : m.status === "simulated" ? SURFACE_ALT : POSITIVE_SOFT;
    const text = m.status === "pending" ? "Pending" : m.status === "simulated" ? "Not sent · Simulated" : "Completed";
    ctx.font = `800 13.5px ${RECEIPT_IMAGE_FONT_BODY}`;
    const w = ctx.measureText(text).width + 52;
    const x = PCX - w / 2;
    receiptImageRoundRect(ctx, x, pillTop, w, PILL_H, PILL_H / 2);
    ctx.fillStyle = wash;
    ctx.fill();
    const cy = pillTop + PILL_H / 2;
    const mx = x + 20;
    ctx.strokeStyle = tone;
    ctx.lineWidth = 2.4;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    if (done) {
      ctx.moveTo(mx - 6, cy);
      ctx.lineTo(mx - 1.5, cy + 4.5);
      ctx.lineTo(mx + 7, cy - 5);
    } else if (m.status === "pending") {
      ctx.arc(mx, cy, 6.5, 0, Math.PI * 2);
      ctx.moveTo(mx, cy - 3.5);
      ctx.lineTo(mx, cy);
      ctx.lineTo(mx + 3.5, cy + 2);
    } else {
      ctx.moveTo(mx, cy - 6);
      ctx.lineTo(mx, cy + 1);
      ctx.moveTo(mx, cy + 5);
      ctx.lineTo(mx, cy + 5.5);
    }
    ctx.stroke();
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.fillStyle = tone;
    ctx.fillText(text, mx + 15, cy + 5);
  });
  py = pillTop + PILL_H;

  // ── Footer, inside the white panel ──
  const footerTop = py + 24;
  const hoomanBase = footerTop + 40;
  const taglineBase = hoomanBase + 26;
  ops.push(() => {
    // Perforation-style divider: the receipt tears off here. The notches are
    // filled with the PURPLE the panel floats on, not the page colour — this
    // divider is inside the card now, and a page-coloured notch would read as
    // two holes punched in the brand.
    ctx.save();
    ctx.setLineDash([6, 6]);
    ctx.strokeStyle = LINE;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(PANEL_X + 16, footerTop);
    ctx.lineTo(PANEL_X + PANEL_W - 16, footerTop);
    ctx.stroke();
    ctx.restore();
    ctx.fillStyle = cardGradient || (theme.bg || "#F6F5FC");
    [PANEL_X, PANEL_X + PANEL_W].forEach((nx) => {
      ctx.beginPath();
      ctx.arc(nx, footerTop, 9, 0, Math.PI * 2);
      ctx.fill();
    });

    receiptImageDrawHooman(ctx, PCX, hoomanBase, 18, ACCENT === "#7C3AED" ? "#4C1D95" : ACCENT, hoomanDots, m.brand.hooman);

    ctx.textAlign = "center";
    ctx.textBaseline = "alphabetic";
    ctx.font = `600 12.5px ${RECEIPT_IMAGE_FONT_BODY}`;
    ctx.fillStyle = INK_SOFT;
    ctx.fillText(m.brand.tagline, PCX, taglineBase);
  });

  const panelBottom = taglineBase + 26;
  panelBox.h = panelBottom - panelTop;
  const cardBottom = panelBottom + PANEL_INSET;
  const H = cardBottom + MARGIN;

  canvas.width = Math.round(W * s);
  canvas.height = Math.round(H * s);
  ctx.setTransform(s, 0, 0, s, 0, 0);

  // Page.
  ctx.fillStyle = theme.bg || "#F6F5FC";
  ctx.fillRect(0, 0, W, H);

  // The card, gradient all the way down.
  ctx.save();
  ctx.shadowColor = "rgba(76,29,149,0.22)";
  ctx.shadowBlur = 26;
  ctx.shadowOffsetY = 10;
  receiptImageRoundRect(ctx, CX, CARD_TOP, CW, cardBottom - CARD_TOP, 28);
  cardGradient = ctx.createLinearGradient(CX, CARD_TOP, CX + CW, cardBottom);
  cardGradient.addColorStop(0, "#1E1B4B");
  cardGradient.addColorStop(0.38, "#3E2E8E");
  cardGradient.addColorStop(0.74, "#7C3AED");
  cardGradient.addColorStop(1, "#C026D3");
  ctx.fillStyle = cardGradient;
  ctx.fill();
  ctx.restore();
  ctx.save();
  receiptImageRoundRect(ctx, CX, CARD_TOP, CW, cardBottom - CARD_TOP, 28);
  ctx.clip();
  ctx.globalAlpha = 0.12;
  ctx.fillStyle = "#FFFFFF";
  ctx.beginPath();
  ctx.arc(CX + CW - 30, CARD_TOP - 20, 95, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 0.07;
  ctx.beginPath();
  ctx.arc(CX + 20, CARD_TOP + 150, 80, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  for (const op of ops) {
    ctx.save();
    try {
      op();
    } catch {
    }
    ctx.restore();
  }

  canvas.dataset.receiptModel = JSON.stringify(m);
  return canvas;
}

function receiptImageToBlob(canvas) {
  return new Promise((resolve, reject) => {
    try {
      canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error("Could not encode the receipt image"))), "image/png");
    } catch (error) {
      reject(error);
    }
  });
}

function receiptImageFilename(receipt) {
  const r = receipt || {};
  const code = String(r.receiptCode || "").replace(/[^A-Za-z0-9-]/g, "");
  return `gloobal-receipt-${code || "payment"}.png`;
}

// Share first, download second — the same order and the same canShare
// check as the receive-QR card and the audit report.
// ── One share: the picture and the link ──────────────────────────────────
//
// The receipt had two share buttons: this one sent the picture, and a second
// one on the Transaction ID box sent a written summary and the /t/ link. Two
// share sheets for one receipt, and whichever you picked, you did not send
// the other half — the picture cannot be clicked through to the transaction,
// and the link is not something you can look at in a chat.
//
// They are one action now, and this builds the payload for it.
//
// The written summary is NOT in it. The picture already states the amount,
// the counterparty, the date and the Transaction ID, in Gloobal's own type —
// so a `text` field repeating all of it put the same receipt in the message
// twice, once as a document and once as a wall of plain text under it. The
// picture is the receipt; the link is where it leads. Nothing else goes.
//
// The ladder is the awkward part, and it exists because navigator.share is
// not uniform. A target that accepts files does not necessarily accept `url`
// alongside them, and the whole payload is rejected when any part of it is
// unsupported — so asking for both at once and giving up on a `false` from
// canShare would lose the picture on exactly the platforms that can show it.
// Each rung drops the least valuable thing that could be causing the
// refusal, and canShare decides, not a browser sniff:
//
//   1. picture + link, the thing that was asked for
//   2. the same, with the link folded into `text` — the field that survives
//      when `url` does not, and a pasted link is still a link
//   3. the picture alone, reported back as its own outcome so the caller can
//      say the link did not go rather than silently dropping it
//
// Nothing here opens a second share sheet. A person who wanted one share and
// got two is the thing this replaced.
function receiptShareAttempts(file, link) {
  const title = "GLOOBAL receipt";
  const out = [];
  if (link) {
    out.push([{ files: [file], title, url: link }, "shared"]);
    out.push([{ files: [file], title, text: link }, "shared"]);
  }
  out.push([{ files: [file], title }, link ? "shared-without-link" : "shared"]);
  return out;
}

async function shareReceiptImage(receipt, opts = {}) {
  try {
    if (!receipt || typeof document === "undefined") return "failed";
    // No photo is fetched. This used to call loadCounterpartyPhoto — a
    // request to the server for the other party's picture — purely so the
    // panel above could draw it. With the avatar gone that request buys
    // nothing, and not making it is the better half of the change: sharing a
    // receipt no longer reaches for anyone's face.
    const model = buildReceiptImageModel(receipt, opts);
    const canvas = await renderReceiptImage(model, { scale: opts.scale || 2 });
    const blob = await receiptImageToBlob(canvas);
    const filename = receiptImageFilename(receipt);

    const link = typeof opts.link === "string" ? opts.link.trim() : "";

    if (typeof File !== "undefined" && typeof navigator !== "undefined" && navigator.canShare && navigator.share) {
      const file = new File([blob], filename, { type: "image/png" });
      for (const [payload, outcome] of receiptShareAttempts(file, link)) {
        let allowed = false;
        try {
          allowed = navigator.canShare(payload);
        } catch {
          allowed = false;
        }
        if (!allowed) continue;
        try {
          await navigator.share(payload);
          return outcome;
        } catch (error) {
          // A refusal here is the SHEET's answer, not the payload's, so the
          // ladder stops: retrying a shorter payload would re-open a sheet
          // the person just dismissed.
          return error && error.name === "AbortError" ? "cancelled" : "failed";
        }
      }
    }

    // No file sharing at all. The picture is downloaded, and the link goes to
    // the clipboard in the same gesture rather than needing a second button —
    // one action still carries both halves, just by two different routes.
    const objectUrl = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = objectUrl;
    anchor.download = filename;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(objectUrl), 10000);
    if (link && typeof copyToClipboard === "function") {
      try {
        // The link alone. The downloaded PNG is the receipt; pasting its
        // contents again as text beside it is the duplication this removed.
        copyToClipboard(link);
        return "downloaded-link-copied";
      } catch {
      }
    }
    return "downloaded";
  } catch {
    return "failed";
  }
}


// src/components/dialogs/ReceiptModal.jsx


// src/components/dialogs/ReceiptModal.jsx

// The ticket's head, in the direction the money went.
//
// Money OUT is the app's own violet; money IN — a payment received, a
// Creator Share credited — is green. The figure sits on the gradient in
// white rather than in T.negative/T.positive, so the direction is carried by
// the whole head of the document instead of by the colour of six characters.
var RECEIPT_HERO_OUT = "linear-gradient(135deg,#312E81 0%,#4F46E5 55%,#7C3AED 100%)";
var RECEIPT_HERO_IN = "linear-gradient(135deg,#064E3B 0%,#047857 55%,#0FA372 100%)";

// The perforation between the head and the rows.
//
// Two half-discs bitten out of the ticket's sides and a dashed rule between
// them. The discs are painted in the colour BEHIND the ticket, which is the
// only thing making them read as holes rather than as dots.
function ReceiptTicketTear() {
  const notch = {
    position: "absolute",
    top: -8,
    width: 16,
    height: 16,
    borderRadius: "50%",
    background: T.bg
  };
  return <div style={{ position: "relative", height: 16, background: T.surface }} aria-hidden="true"><span style={{ position: "absolute", left: 10, right: 10, top: 7, borderTop: `2px dashed ${T.line}` }} /><span style={{ ...notch, left: -8 }} /><span style={{ ...notch, right: -8 }} /></div>;
}

// A section heading inside the ticket — WHO, MONEY, PROOF — with room at the
// right for the one stamp the section carries.
//
// The stamp used to be absolutely positioned over the rows, where it landed
// on top of the first value it met (the counterparty's name, the payment
// figure). It sits on this line instead, which is the one line in the block
// with nothing on its right.
function ReceiptSectionLabel({ children, stamp, stampColor }) {
  return <div
    className="rcpt-sec"
    style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, padding: "9px 0 2px", fontSize: 9, fontWeight: 800, letterSpacing: 1.4, color: T.inkFaint, textTransform: "uppercase" }}
  ><span>{children}</span>{stamp && <span
    style={{
      transform: "rotate(-7deg)",
      border: `2px solid ${stampColor}`,
      color: stampColor,
      borderRadius: 9,
      padding: "3px 8px",
      fontSize: 9.5,
      fontWeight: 800,
      letterSpacing: 1.3,
      opacity: 0.9
    }}
  >{stamp}</span>}</div>;
}

// One of the three things you can do with a finished receipt. Icon over a
// one-word label, because the row has to hold three of them across a phone
// and "Audit report (PDF)" spelled out took a full-width button of its own.
function ReceiptIconAction({ icon, label, onClick, solid, disabled, testId, busy, ariaLabel }) {
  return <button
    onClick={onClick}
    disabled={disabled}
    data-testid={testId}
    aria-label={ariaLabel}
    aria-busy={busy ? true : void 0}
    className="v2-tap"
    style={{
      flex: 1,
      minWidth: 0,
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      gap: 4,
      padding: "10px 4px",
      borderRadius: 18,
      border: solid ? "none" : `1px solid ${T.line}`,
      background: solid ? T.gradButton : T.surface,
      color: solid ? "#fff" : T.inkSoft,
      fontSize: 10.5,
      fontWeight: 800,
      cursor: disabled ? "default" : "pointer",
      opacity: disabled ? 0.55 : 1,
      boxShadow: solid ? "0 8px 20px -14px rgba(76,29,149,0.9)" : T.shadowCard
    }}
  >{icon}<span>{label}</span></button>;
}

// One segment of the Payment / Creator Share toggle.
//
// Pulled out of the row because the row is no longer two identical things
// in a loop — the counterparty's flag sits between them — and interleaving
// a separator into a .map() costs more clarity than the loop was saving.
function ReceiptTabButton({ label, active, onSelect }) {
  return <button
    onClick={onSelect}
    className="v2-tap"
    aria-pressed={active}
    style={{
      flex: 1,
      border: "none",
      borderRadius: 999,
      padding: "9px 0",
      fontSize: 12.5,
      fontWeight: 800,
      cursor: "pointer",
      whiteSpace: "nowrap",
      color: active ? "#fff" : T.inkSoft,
      background: active ? T.gradButton : "transparent",
      transition: "background 0.18s ease, color 0.18s ease"
    }}
  >{label}</button>;
}

function ReceiptModal({ receipt, onClose, onDone, onRevealShare, shareTabRequest }) {
  // ── THE LENS ON A DOCUMENT SOMEBODY KEEPS ────────────────────────────
  //
  // A receipt is the thing a person screenshots as proof, so the rule is
  // applied here more strictly than anywhere else: ONLY figures in the
  // viewer's own tender are renamed, and everything else keeps its real
  // currency.
  //
  // On a cross-border receipt that means one document legitimately showing
  // two units — "8,000.00 GEU" for what left the payer and "98.00 EUR" for
  // what reached the payee. That looks odd the first time and it is the
  // honest reading: they are not the same unit, and 1 GEU is one unit of
  // the READER'S money, not of the counterparty's.
  //
  // The viewer's currency comes from the shared reader rather than a prop,
  // because this modal is opened from history, from the dashboard and from
  // the send flow, and a prop added to two of the three would print GEU
  // over somebody else's money on the third.
  const lens = useGeuLens();
  const viewerCurrency = geuLensOwnCurrency();
  const [copied, setCopied] = useState11(false);
  // A Creator Share receipt opens on its share.
  //
  // Initialised from the prop AND reset by the effect below. Two places on
  // purpose: the effect runs after paint, so on its own it would show one
  // frame of the Payment tab before switching — a flicker on the document
  // that is least about a payment.
  const [receiptTab, setReceiptTab] = useState11(
    () => (receipt && receipt.kind === "share" ? "share" : "payment")
  );
  const { getLocationForViewer, getComplaintWindow, openComplaint } = useProvenanceAndDisputes();
  const [reportSubmitted, setReportSubmitted] = useState11(false);
  const [complaintOpen, setComplaintOpen] = useState11(false);
  const [complaintBusy, setComplaintBusy] = useState11(false);
  const [complaintError, setComplaintError] = useState11("");
  const [complaintRaised, setComplaintRaised] = useState11(null);
  // Which of the two quiet things under the ticket is open: "where", "report",
  // or neither. One at a time, so the foot of the receipt never grows by two
  // blocks at once.
  const [detail, setDetail] = useState11(null);
  // "Working", not "done": the share sheet can be dismissed, and a button
  // that flipped to a success state on tap would claim the report had gone
  // somewhere when the person had just cancelled it.
  const [auditBusy, setAuditBusy] = useState11(false);
  // The receipt-image share. Busy while the picture is drawn and handed to
  // the share sheet (the button is disabled meanwhile, so a double tap cannot
  // draw two); `shareFeedback` is the one line saying what happened.
  const [imageShareBusy, setImageShareBusy] = useState11(false);
  const [shareFeedback, setShareFeedback] = useState11("");
  // What the Gloobal ID check found, when Pay again ran it: null, or one of
  // checking / changed / gone / unreachable. Declared up here with the other
  // hooks rather than beside the handler that owns it, because `if (!receipt)
  // return null` sits between the two and a hook after a conditional return
  // is a hook React does not always see — the crash is "Rendered more hooks
  // than during the previous render", and it takes the whole receipt down.
  const [payAgainState, setPayAgainState] = useState11(null);
  // The link share's own tick, apart from the Transaction ID copy's.
  // Who is looking at this receipt: their Gloobal ID for the image's
  // "Sent by / Received by" line. Read from the stored session, the same
  // place every other screen asks.
  const viewerSymbolId = useCurrentSymbolId();
  // No counterparty photo is read here any more.
  //
  // It used to call the server by the other party's Gloobal ID to fetch their
  // picture, and draw it beside their name. Two reasons it is gone, and the
  // second is the one that settled it:
  //
  //   A receipt is a record, and this one is shared — as a link and as a PNG.
  //   A face is the single thing on it that is not a fact about the payment,
  //   and it travels further than the sender means it to.
  //   The fallback was worse than the photo. Where there was no picture the
  //   component drew a brand-gradient disc, so the largest mark on the block
  //   carried nothing at all and was there only because the layout had a
  //   hole shaped like a face.
  //
  // profileAvatar.jsx stays — the scan card and the dashboard still use it.
  // What is removed is this screen's request for it.
  useEffect10(() => {
    if (receipt) {
      setReceiptTab(receipt.kind === "share" ? "share" : "payment");
      setReportSubmitted(false);
      setShareFeedback("");
      setDetail(null);
    }
  }, [receipt]);
  // "View Creator Share receipt", from the card that has just been scratched.
  //
  // A counter rather than a boolean, because the request can be made more than
  // once in a receipt's life and a boolean that is already true fires nothing.
  // Zero — the initial value — is not a request, so a receipt that opens with
  // no reveal behind it is unaffected.
  useEffect10(() => {
    if (shareTabRequest) setReceiptTab("share");
  }, [shareTabRequest]);
  const [txnColorOffset, setTxnColorOffset] = useState11(0);
  useEffect10(() => {
    const interval = setInterval(() => {
      setTxnColorOffset((o) => (o + 1) % POSITION_COLORS.length);
    }, 2e3);
    return () => clearInterval(interval);
  }, []);
  if (!receipt) return null;
  const isSent = receipt.direction === "sent";
  const viewerRole = isSent ? "sender" : "receiver";
  const myLocation = receipt.txnId ? getLocationForViewer(receipt.txnId, viewerRole) : null;
  const complaintWindow = receipt.txnId ? getComplaintWindow(receipt.txnId) : null;
  const withinComplaintWindow = complaintWindow ? Date.now() <= new Date(complaintWindow.expiresAt).getTime() : false;
  // The Report icon is drawn whenever this transaction HAS a complaint window,
  // open or closed: a window that has closed is a fact worth being able to
  // read, and hiding the control would leave somebody looking for it.
  const canReport = !!complaintWindow;
  // A payment this person SENT, that the server knows about, can carry a
  // complaint to the person who received it. Everything else keeps the
  // old on-device report.
  const canComplain = isSent && receipt.kind !== "share" && Boolean(receipt.txnId);
  const raiseComplaint = async ({ reason, note }) => {
    if (complaintBusy) return;
    setComplaintBusy(true);
    setComplaintError("");
    try {
      const created = typeof GloobalApi !== "undefined" && GloobalApi.raiseComplaint
        ? await GloobalApi.raiseComplaint({ txnId: receipt.txnId, reason, note })
        : null;
      if (!created || created.error) {
        setComplaintError((created && created.error) || "Couldn't raise the complaint just now. Try again.");
        return;
      }
      setComplaintOpen(false);
      setComplaintRaised(created);
    } finally {
      setComplaintBusy(false);
    }
  };
  const handleReportIssue = () => {
    if (!receipt.txnId) return;
    const result = openComplaint({ txnId: receipt.txnId, raisedBy: viewerRole, reason: "Reported from receipt" });
    if (result?.ok) setReportSubmitted(true);
  };
  // The share leg's own reference, stripped of the grouping spaces rows
  // saved before genTxnId dropped them still carry. See the block below the
  // tints for what it is and why nothing falls back to the payment's id.
  const shareTxnRaw = receipt.shareTxnId ? String(receipt.shareTxnId).replace(/\s/g, "") : "";
  // Is there a Creator Share on this receipt AT ALL?
  //
  // Two ways to be sure there is: the share leg's own reference (a server
  // payment whose payee shares something), or a non-zero rate (a payment
  // settled locally, where the share is real in this device's ledger but no
  // server leg exists to reference). A payment at 0% has neither, and it
  // gets no Creator Share tab — an empty tab on a payment that shares
  // nothing implies a movement that never happened.
  const shareRatePercent = Number(receipt.shareRate) || 0;
  const isShareReceipt = receipt.kind === "share";
  // A Gloobal Coin buy, sell or send.
  //
  // It reaches this component through the same door as a payment and reuses
  // everything that already fits: the hero figure, the counterparty box
  // (`name`/`id`, filled by coinReceipt.js so that box needs no third
  // shape), the date/time/status box, and the audit report. What it adds is
  // one block — the holder, and the other side of the exchange — because a
  // coin buy is the one movement here whose two legs are in different units
  // and whose counterparty is not a person.
  //
  // It gets no Creator Share tab, and not by a special case: hasShareEvent
  // below reads a rate and a share reference, and coinReceipt.js states both
  // as absent rather than leaving them undefined, precisely so a coin
  // receipt opened after a payment cannot inherit the previous one's.
  const isCoinReceipt = receipt.kind === "coin";
  const coinRateLine = isCoinReceipt ? coinRateSentence(receipt) : null;

  // The payment the Payment tab describes.
  //
  // On a payment receipt that is this row. On a share receipt it is the
  // payment the share came from — 500 to Jio, not the 10 share — resolved by
  // reference in historyUtils, and null when it could not be found.
  const paymentKnown = !isShareReceipt || receipt.sourceAmount != null;
  const paymentAmount = isShareReceipt
    ? Number(receipt.sourceAmount) || 0
    : receipt.amount;
  const paymentCurrency = isShareReceipt
    ? receipt.sourceCurrencyCode || receipt.currencyCode
    : receipt.currencyCode;
  const paymentIsSent = isShareReceipt ? receipt.sourceDirection === "sent" : isSent;

  // Which tab leads.
  //
  // Payment receipt: Payment, the flag, then Creator Share — the order the
  // money moved in. Share receipt: the document is about the share, so
  // Creator Share leads and Payment follows, carrying the payment it came
  // from. The ORDER is what says which kind of receipt you opened before you
  // have read a figure; lighting a tab does not, because a lit tab in second
  // place still reads as the second thing.
  const leadingTab = isShareReceipt ? "share" : "payment";
  const trailingTab = isShareReceipt ? "payment" : "share";
  // A coin movement is not a payment and must not be labelled as one. It has
  // no second tab either — the chip is the document's own name, which is the
  // only thing left for it to say.
  const tabLabel = (tab) => (tab === "share"
    ? "Creator Share"
    : receipt.kind === "coin" ? (receipt.title || "GLOOBAL Coin") : "Payment");

  // A Creator Share receipt gets a Creator Share tab, and it is the one it
  // opens on — but the tab shows the share, it never COMPUTES one.
  //
  // That distinction is the whole of it, and it is worth being exact about,
  // because the tab was removed from share receipts outright to stop a real
  // fabrication: the row arrived carrying the payment's rate, this check read
  // it as "there is a share here", and the tab computed the rate AGAIN
  // against the share amount and announced the result as money shared back.
  // On the reported payment that was a second release of 49.00 out of a 700
  // share — a movement that exists in no transaction, no ledger entry and no
  // balance. In the Jio example it is 2% of 10, printed as 0.20.
  //
  // Two things now make the tab safe rather than absent:
  //
  //   - mapServerTransaction zeroes `shareRate` on a share leg, so no share
  //     row can claim a rate of its own; and
  //   - `shareAmount` below READS the row's own figure on a share receipt
  //     instead of multiplying anything, so there is no second computation
  //     left to be wrong.
  //
  // What the tab shows is the share that actually happened, and the Payment
  // tab beside it shows the payment it came from. Removing the tab stopped
  // the fabrication but left the other half of the defect standing: the
  // share still opened as a document headed "Money received", as though Jio
  // had paid you 10 for something.
  //
  // A PAYMENT receipt still gets the tab only when a share really happened —
  // a share leg minted server-side, or a non-zero rate applied by this
  // device's own ledger. A payment at 0% shares nothing, and a tab offering
  // the receipt for a movement that never happened is a claim, not a control.
  const hasShareEvent = isShareReceipt || !!shareTxnRaw || shareRatePercent > 0;
  // Two documents, or one.
  //
  // One tab is not a toggle — it is a button that does nothing, restating the
  // line already beside it. A coin movement carries no Creator Share by
  // construction, and neither does a payment at 0%, so both get their
  // document's name in the header instead of a pill with a single segment.
  // Is there a share to reveal, and is anyone offering to reveal it?
  //
  // Both halves matter. `hasShareEvent` is the payment's own answer — a payee
  // who shares nothing back has nothing behind a coupon, and a button
  // promising otherwise is a lie the scratch card would have to tell. And
  // `onRevealShare` is only passed by the screen that has just paid: from
  // History the share is simply on its tab, which is what "it reveals itself
  // quietly" means for somebody who walked away.
  const canReveal = typeof onRevealShare === "function" && hasShareEvent;
  // While the coupon is still unopened the receipt keeps the share to itself:
  // no Creator Share tab, and no "Creator share 2.78₹ back" on the head. A
  // coupon over a figure printed two inches above it is not a coupon.
  const showReceiptTabs = !isCoinReceipt && hasShareEvent && !canReveal;

  // `direction` means two different things, and conflating them puts the
  // wrong sign on the hero figure.
  //
  // On a PAYMENT receipt it describes the payment, and the share always runs
  // the other way: I paid Jio, so Jio's share comes back to ME. On a SHARE
  // receipt it describes the share itself and needs no inverting — direction
  // "received" IS the share arriving.
  const shareIsCredit = isShareReceipt ? !isSent : isSent;
  // ── WHERE THE SHARE WENT, AND WHY IT IS READ OFF THE RECORD ──────────
  //
  // This row said "Gloobal balance" unconditionally, and it was telling
  // the truth: the share was credited into the payer's spendable balance
  // the moment the payment settled. That behaviour has changed — the share
  // is now placed in My Assets and claimed from there — but the receipts
  // for every payment made before the change still describe payments where
  // it really did go to the balance.
  //
  // So the destination comes off the row the server recorded, never from
  // what the app does today. `shareDestination` is "assets" on a payment
  // whose share was held and empty on one that predates it. A receipt is a
  // record; it has to keep saying what happened.
  //
  // Only the CREDIT side moves. On the payee's side the share was taken
  // out of what they would otherwise have been paid, which came from their
  // balance either way.
  const shareDestinationName = shareIsCredit && receipt.shareDestination === "assets"
    ? "My Assets"
    : "GLOOBAL balance";
  // Guarded rather than read straight off `receiptTab`, so a receipt opened
  // while the previous one was left on its share tab cannot land on a tab
  // this receipt does not have.
  const onShareTab = hasShareEvent && receiptTab === "share";
  // Which currency the hero figure is in, and whether saying so adds
  // anything. See the note beside the line that draws it.
  //
  // Whether fmtMoney already ends in the code is a property of the CURRENCY,
  // not of the amount — it appends the code exactly for those with no symbol
  // of their own — so it is probed with a fixed 1 rather than with the hero
  // figure. That keeps this independent of where the hero amounts are worked
  // out further down the component.
  const heroCurrencyRaw = onShareTab ? receipt.currencyCode : (paymentKnown ? paymentCurrency : null);
  // ── THE CODE MOVED ONTO THE FIGURE'S OWN LINE ─────────────────────────
  //
  // This used to be a separate 10.5px line under the hero carrying the bare
  // code, because a symbol is not an identifier — ₹ is the rupee of five
  // countries and $ belongs to more than twenty, and on a cross-border
  // receipt "1,106.61₹" does not say which rupee left the account.
  //
  // That job is now done by the bar on the figure itself (see moneyCoded and
  // geuLensBarMoney), which does it on the same line and in the pattern every
  // other amount in the app uses. Keeping both would make the hero the one
  // place on this screen naming its unit twice — and the bar is the copy that
  // also answers the question the old line could not, which is what the
  // reader's own figure is called in the OTHER unit.
  //
  // So this is now empty whenever the bar names the unit, which is whenever
  // there is a unit to name. It is kept rather than deleted because the one
  // case left is real: a hero with no currency at all. The Coin receipt is
  // counted in GC, which is not a currency, gets no bar, and still has a
  // ticker worth printing.
  const heroBarUnit = heroCurrencyRaw ? geuLensBarUnit(heroCurrencyRaw, lens, viewerCurrency) : "";

  // ── THE HERO, IN TWO SIZES ────────────────────────────────────────────
  //
  // The unit being read in is the larger half — see GEU_LENS_TRAIL_RATIO.
  // Both halves and the size are derived ONCE here rather than inline in the
  // markup, because the size depends on the joined string's length and the
  // two spans must be sized from the same answer. Computed for both tabs
  // whether or not this receipt has a share; they are three string
  // operations, and a conditional here is a second thing to keep in step.
  const heroFigure = (amount, code, sign) => {
    const parts = geuLensBarParts(amount, code, lens, viewerCurrency);
    const whole = `${sign}${geuLensBarMoney(amount, code, lens, viewerCurrency)}`;
    return { lead: parts.lead, trail: parts.trail, size: receiptAmountFontSize(whole, 31) };
  };
  const heroPayment = heroFigure(paymentAmount, paymentCurrency, paymentIsSent ? "\u2212" : "+");
  const heroCurrencyCode = heroCurrencyRaw && !heroBarUnit &&
    !String(fmtMoney(1, heroCurrencyRaw)).endsWith(String(heroCurrencyRaw))
    ? String(heroCurrencyRaw)
    : "";
  const tint = onShareTab
    ? (shareIsCredit ? T.positive : T.negative)
    : (paymentIsSent ? T.negative : T.positive);
  const tintSoft = onShareTab
    ? (shareIsCredit ? T.positiveSoft : "rgba(226,63,69,0.12)")
    : (paymentIsSent ? "rgba(226,63,69,0.12)" : T.positiveSoft);
  const shareCurrency = receipt.currencyCode;
  const shareAmountBase = receipt.amount;
  // READ on a share receipt, computed on a payment receipt.
  //
  // On a share receipt the row IS the share, so its own figure is the
  // figure. This is the line that makes the Creator Share tab safe to show
  // on a share receipt at all — see hasShareEvent above.
  const shareAmount = isShareReceipt
    ? (Number(receipt.shareAmount) || Number(receipt.amount) || 0)
    : shareAmountBase * ((receipt.shareRate ?? 0) / 100);
  // What the share tab DISPLAYS.
  //
  // On a PAYMENT receipt the row carries the share the server actually
  // recorded (the share leg's amount straight after paying, cashbackCredit /
  // cashback on a restored row), and that figure wins. The multiplication
  // above is only the fallback for a receipt with no recorded share — a
  // payment this device settled locally — because it rounds differently from
  // the server's minor-unit figure. A recorded 0 counts as "not recorded":
  // every builder defaults an absent share to 0, and a 0% payment has no
  // share tab to show it on anyway.
  const recordedShareAmount = Number(receipt.shareAmount);
  const shownShareAmount = !isShareReceipt && Number.isFinite(recordedShareAmount) && recordedShareAmount > 0
    ? recordedShareAmount
    : shareAmount;

  // Declared HERE, not beside heroPayment, because it reads shownShareAmount
  // — which is a const twenty lines further down and therefore in its own
  // temporal dead zone up there. Same class of mistake as hoomanRaisedText on
  // the Coverage screen: a derivation written next to its SIBLING rather than
  // after its DEPENDENCY, and a ReferenceError the moment the component
  // renders.
  const heroShare = heroFigure(shownShareAmount, shareCurrency, shareIsCredit ? "+" : "\u2212");
  // The rate to DISPLAY. On a share receipt it comes off the payment, for
  // the reason historyUtils spells out: the share row's own rate is zeroed
  // at the boundary by design, so reading it here would print 0.00%.
  // ── What this transaction was exchanged at ─────────────────────────────
  //
  // Drawn only when the two sides really are different currencies. A
  // "conversion" block on a domestic payment showing 1.000000 states that an
  // exchange took place, and none did.
  //
  // Every figure is a recorded one: the server stores the receiver's face
  // value, the sender's own debit, and the rate, as three separate facts.
  // Multiplying one by another to fill in the third would give a number that
  // disagrees with the ledger by a rounding unit, and a receipt whose halves
  // do not reconcile is worse than one that shows a single side.
  //
  // The rate is stated in the direction it was RECORDED: 1 unit of the
  // receiver's currency into the sender's. Inverting it would read more
  // naturally to a sender ("1 USD = 83.61 INR" rather than "1 INR = 0.011960
  // USD") and that is exactly why it is not done. An inverted rate is a
  // computed rate: it rounds, so it would not match the figure on the record,
  // and somebody reconciling this receipt against a statement would find two
  // rates for one payment.
  //
  // Read through receiptCurrency.js, the same functions the shared picture
  // and the audit PDF use, so the three cannot disagree about whether this
  // transaction crossed a currency. On a Creator Share receipt the payment is
  // the SOURCE payment, not this row — the share row carries no conversion of
  // its own, and reading it here is why the Payment tab of every share
  // receipt used to look domestic.
  const paymentConversion = paymentKnown ? receiptPaymentConversion(receipt) : null;
  // And the share's own two sides: what the payee gave, in their currency,
  // and what the payer got, in theirs. The Creator Share tab showed only the
  // viewer's side of a movement that had two.
  const shareConversion = receiptShareConversion(receipt);

  const displayShareRate = isShareReceipt
    ? (receipt.sourceShareRate ?? null)
    : shareRatePercent;
  // Each tab shows ITS OWN transaction's reference.
  //
  // The Creator Share is a separate movement between a different pair of
  // parties — I pay Jio (one transaction), then Jio's share comes back to
  // me (another) — and the server already mints it as its own Transaction
  // with its own referenceId (mintShareLegAndReceipts). Both tabs used to
  // print receipt.txnId, so the payment and the share were indistinguishable
  // by reference and neither could be looked up unambiguously.
  //
  // It used to FALL BACK to the payment's id when the share reference was
  // absent, on the reasoning that a blank looked broken. That fallback is
  // removed, because what it actually printed was a false statement: the
  // Creator Share tab claimed a transaction id that belongs to a different
  // transaction, and the two legs of one payment could not be told apart by
  // anyone reading the receipt. Four ordinary situations reached it —
  // reopening any receipt from history, retrying a send, paying a scanned
  // code, paying a business — so the same-id receipt was the normal case,
  // not an edge one.
  //
  // No reference now means no reference is shown. The id box is drawn only
  // `&&` there is one (see below), so the tab renders its money and its rate
  // and simply omits a field it does not have.
  // Which reference each tab names, and it swaps with the document.
  //
  // PAYMENT receipt: the payment's id is the row's own, the share's is
  // shareTxnId. SHARE receipt: the other way round — the row IS the share,
  // so its own id is the share's, and the payment's comes off the row the
  // lookup found.
  const ownTxnId = receipt.txnId ? String(receipt.txnId).replace(/\s/g, "") : "";
  const shareSideTxnId = isShareReceipt ? ownTxnId : shareTxnRaw;
  const paymentSideTxnId = isShareReceipt ? receipt.sourceTxnId || "" : ownTxnId;
  const showingShare = onShareTab && !!shareSideTxnId;
  const rawTxnId = onShareTab ? shareSideTxnId : paymentSideTxnId;
  // No cross-reference line under the id.
  //
  // There was one — "From payment <id>" in small grey type beneath the
  // share's own reference. The two tabs are a single swipe apart and each
  // already shows the id of the thing it is about, in its own box under its
  // own label, so the line said the same thing twice and in the worse of the
  // two places. It was also laid out as a flex ROW sibling of the reference,
  // so the two drew on top of each other.
  const handleCopyTxnId = () => {
    if (!rawTxnId) return;
    copyToClipboard(rawTxnId);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };
  // Share the RECEIPT, not the reference on its own.
  //
  // This used to hand the share sheet a bare 20-symbol reference. Pasted into
  // WhatsApp it arrived as a wall of symbols that said nothing about what it
  // was, from whom or for how much - and could not be acted on, because there
  // was nowhere for it to lead.
  //
  // Now it opens the phone's own share sheet with a summary and a link. The
  // summary is the sender deliberately disclosing their own payment, which is
  // what sharing a receipt IS. The link carries only the reference (see
  // GET /t/:referenceId) and the app it opens shows the receipt from the
  // VIEWER'S OWN history, so a forwarded link tells a stranger nothing.
  const receiptCountryName = (() => {
    if (!receipt || !receipt.flag) return "";
    const match = (typeof ALL_COUNTRIES !== "undefined" ? ALL_COUNTRIES : []).find((c) => c.flag === receipt.flag);
    return match ? match.name : "";
  })();
  // The path this receipt's link is addressed by.
  //
  // It used to be the transaction's own reference. Every one of the twenty
  // dial-pad symbols is multi-byte UTF-8, so encodeURIComponent turned a
  // 20-character reference into about 180 characters of %E2%96%A0 — a link
  // that filled a WhatsApp message and read as a decoding error:
  //
  //   /t/%E2%96%A1%E2%96%A0%3D%E2%97%8B%E2%96%A0%E2%96%A1…
  //
  // The server now mints a ten-character ASCII handle for each transaction
  // (Transaction.receiptCode) and GET /t/ resolves it back to that row, so
  // the same link reads /t/A7K9M2QX8P.
  //
  // Read per TAB, not per receipt: the payment and its Creator Share are two
  // different movements with two different references, so they have two
  // different handles, and sharing the share tab must not hand somebody a
  // link to the payment it came from.
  //
  // The reference is still the fallback, and is still what a receipt with no
  // code shares — a payment that stayed local, or a row restored from before
  // codes existed. Those links are long, and they still resolve: GET /t/
  // accepts both shapes. Nothing here changes the Transaction ID itself; it
  // is minted, stored, displayed and copied exactly as before.
  const receiptShareCode = onShareTab
    ? (isShareReceipt ? receipt.receiptCode || "" : receipt.shareReceiptCode || "")
    : (isShareReceipt ? receipt.sourceReceiptCode || "" : receipt.receiptCode || "");
  const receiptSharePath = receiptShareCode || (rawTxnId ? encodeURIComponent(rawTxnId) : "");
  const receiptShareUrl = receiptSharePath ? `${GLOOBAL_API_BASE}/t/${receiptSharePath}` : "";
  // The words that travel with the picture.
  //
  // Built from the TAB's receipt, not the raw row, so the summary and the
  // image describe the same movement. They did not before: the picture was
  // built per tab and this text was not, so sharing a payment's Creator Share
  // tab sent a picture of the share captioned with the payment's figure.
  //
  // `for` is the per-tab receipt; rawTxnId is already per-tab.
  const receiptShareSummary = (For) => {
    const r = For || receipt;
    const sent = r.direction === "sent";
    const money = geuLensBarMoney(Number(r.amount || 0), r.currencyCode, lens, viewerCurrency);
    const who = r.name ? `${sent ? "To" : "From"}: ${r.name}${receiptCountryName ? ` (${receiptCountryName})` : ""}` : "";
    return [
      `GLOOBAL receipt - ${sent ? "money sent" : "money received"}`,
      money,
      who,
      `${r.date || ""}${r.time ? ` \u00b7 ${r.time}` : ""}`,
      `Transaction ID: ${rawTxnId}`
    ].filter(Boolean).join("\n");
  };
  // Text and link only. This is no longer a button — it is what runs when the
  // picture could not be drawn, so that a failure still sends the receipt
  // rather than nothing.
  const handleShareTxnId = () => {
    if (!rawTxnId) return;
    const text = receiptShareSummary(imageReceiptForTab());
    // The clipboard fallback copies the WHOLE receipt including the link,
    // rather than the bare id it used to leave behind.
    shareOrCopy(
      { title: "GLOOBAL receipt", text, url: receiptShareUrl },
      `${text}\n${receiptShareUrl}`,
      () => setShareFeedback("Receipt and link copied.")
    );
  };
  // ── Share the receipt as a PICTURE ─────────────────────────────────────
  //
  // The Share button on the amount card hands the phone's share sheet a PNG
  // of the receipt (features/receipts/receiptImage.js) — the thing people
  // actually forward after paying someone — or downloads it where a browser
  // cannot share files. The text-and-link share above is still one tap away
  // on the Transaction ID box, and is what runs if drawing the image fails.
  //
  // The image describes the TAB being looked at, the same rule the link
  // follows: a payment receipt's Creator Share tab shares the share, not the
  // payment it came from, and vice versa on a share receipt. Every figure on
  // the derived documents below is one this component already shows on that
  // tab; nothing new is computed for the picture.
  const imageReceiptForTab = () => {
    if (isCoinReceipt || onShareTab === isShareReceipt) return receipt;
    // The payment's conversion is dropped from a derived share document (a
    // share is not a conversion of its payment). The share's own two sides —
    // shareSender* / shareReceiver* / shareFxRate — ride along untouched on
    // the spread, and the picture reads those for a share.
    const noConversion ={ senderAmount: null, senderSideCurrency: null, receiverAmount: null, receiverSideCurrency: null, fxRate: null };
    if (onShareTab) {
      return {
        ...receipt,
        ...noConversion,
        // Resolved BEFORE the payment's fields are stripped: on a receipt
        // shown straight after paying, the share's rate is the payment's own
        // recorded one, and it is read off those fields (receiptShareFxRate).
        shareFxRate: receiptShareFxRate(receipt),
        kind: "share",
        direction: shareIsCredit ? "received" : "sent",
        amount: shownShareAmount,
        shareAmount: shownShareAmount,
        currencyCode: shareCurrency,
        txnId: shareSideTxnId,
        receiptCode: receipt.shareReceiptCode || ""
      };
    }
    if (!paymentKnown) return receipt;
    // The payment tab of a share receipt: the conversion is the SOURCE
    // payment's recorded one, the same figures this tab draws on screen.
    return {
      ...receipt,
      ...noConversion,
      senderAmount: receipt.sourceSenderAmount ?? null,
      senderSideCurrency: receipt.sourceSenderSideCurrency || null,
      receiverAmount: receipt.sourceReceiverAmount ?? null,
      receiverSideCurrency: receipt.sourceReceiverSideCurrency || null,
      fxRate: receipt.sourceFxRate ?? null,
      kind: "payment",
      direction: paymentIsSent ? "sent" : "received",
      amount: paymentAmount,
      currencyCode: paymentCurrency,
      txnId: paymentSideTxnId,
      receiptCode: receipt.sourceReceiptCode || ""
    };
  };
  const handleShareReceiptImage = async () => {
    if (imageShareBusy) return;
    setImageShareBusy(true);
    setShareFeedback("");
    let outcome = "failed";
    try {
      const session = typeof gloobalSessionLoad === "function" ? gloobalSessionLoad() : null;
      const storedName = session && session.user && typeof session.user.fullName === "string" ? session.user.fullName.trim() : "";
      // Accounts made before the name step carry their mobile number as
      // fullName; a phone number is not a name to print on a shared picture.
      const viewerName = storedName && !/^\+?\d[\d\s-]*$/.test(storedName) ? storedName : "";
      // No photo is passed, and receiptImage.js no longer fetches one of its
      // own. The shared picture carries the payment and nobody's face.
      // ONE share, carrying both halves. The picture and the /t/ link go out
      // in a single sheet; there is no second share button any more.
      //
      // No `summary`. It used to ride along, and it repeated — line for line
      // — what the picture already prints: the amount, the counterparty, the
      // date, the Transaction ID. One receipt arrived twice in the same
      // message, once as a document and once as plain text under it. The
      // picture carries the payment and the branding; the link carries where
      // it leads. receiptShareSummary still exists for handleShareTxnId,
      // which runs only when there is no picture to send.
      const tabReceipt = imageReceiptForTab();
      outcome = await shareReceiptImage(tabReceipt, {
        viewerName,
        viewerSymbolId: viewerSymbolId || "",
        // The picture goes out in the lens the sender is reading in, so it
        // matches the screen they shared it from. Both names are on every
        // figure either way — see receiptImageMoney — so the only thing this
        // decides is which of the two leads.
        lens,
        viewerCurrency,
        link: receiptShareUrl
      });
    } catch (e) {
      outcome = "failed";
    } finally {
      setImageShareBusy(false);
    }
    if (outcome === "shared") setShareFeedback(receiptShareUrl ? "Receipt and link shared." : "Receipt shared.");
    // Said out loud rather than swallowed: some share targets refuse a link
    // alongside a file, and a person who expected both should be told which
    // one went, not left to discover it in the chat they sent it to.
    else if (outcome === "shared-without-link") setShareFeedback("Receipt shared. This app wouldn't take the link with it — use Copy to send it.");
    else if (outcome === "downloaded-link-copied") setShareFeedback("Receipt saved to your downloads, and the link copied.");
    else if (outcome === "downloaded") setShareFeedback("Receipt image saved to your downloads.");
    else if (outcome === "cancelled") setShareFeedback("");
    else {
      // Only a real failure falls back to the text and link — a person who
      // dismissed the share sheet did not ask for a second one.
      setShareFeedback("Couldn't make the receipt image, so the receipt link was shared instead.");
      handleShareTxnId();
    }
  };
  // ── Pay again ──────────────────────────────────────────────────────────
  //
  // The same counterparty, a blank amount. Blank rather than prefilled with
  // the figure just paid: the second payment to somebody is not usually the
  // same size as the first, and a form that opens holding a number is a form
  // that gets sent holding it. Everything else about them — name, Gloobal ID,
  // country, their Creator Share rate — is carried over, which is the part
  // that is tedious to type and the part this button exists to save.
  //
  // Announced rather than called: this component is mounted from Send Money,
  // from History and from the Coin screen, and only App.jsx knows how to open
  // Send Money on a payee. It listens for this event (openSendToPayee).
  //
  // The receipt is closed FIRST and the event fires after that turn, because
  // App.jsx clears a pending payee whenever the send screen is not the open
  // one — dispatching before the close would hand it a payee and then wipe it.
  // ── The ID on a receipt is not a current fact ───────────────────────────
  //
  // This used to open Send Money on receipt.id directly, and said so: "the
  // payee is the counterparty already named on the receipt, so nothing is
  // resolved over the network". That is the right instinct for a name or a
  // country and the wrong one for the ID, because a receipt records what
  // was true when the money moved and PATCH /api/profile/change-symbol-id
  // exists. The older the receipt, the likelier its ID names nobody.
  //
  // It cannot name the WRONG body — a released ID is retired for good, so it
  // never returns to the pool and a stranger cannot be holding it — so what
  // this fixes is a dead end, not a misdelivery. GET /api/payees/current
  // turns the dead end back into the person: the rename trail first, which
  // is an exact recorded link between the old ID and the new, and their
  // mobile number only where there is no trail. Never a name; names are not
  // unique, and the name here is for the payer to recognise.
  //
  // THREE OUTCOMES, and the middle one is why this is not just a lookup:
  //
  //   unchanged  — open Send Money, exactly as before.
  //   changed    — do NOT open it. Money is about to go to an ID the payer
  //                has never seen, so the old and the new are put side by
  //                side and they tap to agree. A resolve that quietly
  //                substituted one ID for another would be the app deciding
  //                who gets paid.
  //   gone       — say so, and leave the receipt open. There is nothing
  //                useful to prefill and a payment screen aimed at nobody
  //                is worse than a sentence explaining why.
  //
  // An unreachable server is none of the three. A cold start is not an
  // answer about anybody's ID, so it says "couldn't check" and stops rather
  // than falling back to the stored ID — falling back would make the check
  // decorative exactly when it is load-bearing.
  const canPayAgain = !isCoinReceipt && !!receipt.id && receipt.status !== "simulated";
  // ── WHAT PAY AGAIN HANDS TO SEND MONEY ────────────────────────────────
  //
  // `resolved` is the payee as the server just described them — the same
  // answer the ID check below already fetched, which was being thrown away.
  //
  // It is thrown away no longer because `receipt.phone` DOES NOT EXIST.
  // Neither mapServerTransaction nor buildTransactionSnapshot produces a
  // phone field, so this was `mobileNumber: ""` on every payment ever
  // reopened, and Send Money drew the receiver card with an empty number
  // row. Not intermittent: always.
  //
  // The number it uses instead is the MASKED one — "+9190••••••04" — which
  // is the only form that leaves the server (audit finding GLB-17, see
  // cleanResolvedTransactionUserPayload). That is enough to confirm the
  // right person and is exactly what the screen shows when somebody is
  // found by searching, so Pay again now matches the path beside it.
  const payAgainDetail = (gloobalId, resolved) => ({
    gloobalId,
    // The live name wins over the stored one: the whole point of the check
    // this follows is that the account may have changed since the payment.
    name: (resolved && resolved.fullName) || receipt.name || "",
    mobileNumber: (resolved && resolved.mobileNumber) || receipt.phone || "",
    countryIso: (resolved && resolved.countryIso) || receipt.counterpartyIso || null,
    shareRate: Number(receipt.shareRate) || 0
  });
  const openSendMoney = (gloobalId, resolved) => {
    (onDone || onClose)();
    if (typeof window !== "undefined") {
      setTimeout(() => window.dispatchEvent(new CustomEvent("gloobal:payAgain", { detail: payAgainDetail(gloobalId, resolved) })), 0);
    }
  };
  const handlePayAgain = async () => {
    if (!canPayAgain || (payAgainState && payAgainState.status === "checking")) return;
    setPayAgainState({ status: "checking" });
    try {
      const answer = await GloobalApi.resolveCurrentPayee({
        gloobalId: receipt.id,
        mobileNumber: receipt.phone || ""
      });
      const now = answer && answer.user && answer.user.symbolId;
      if (!now) {
        setPayAgainState({ status: "gone" });
        return;
      }
      if (!answer.changed && now === receipt.id) {
        setPayAgainState(null);
        openSendMoney(receipt.id, answer.user);
        return;
      }
      // The resolved payee is carried on the state so the confirm button
      // below hands Send Money the same answer this check just got, rather
      // than looking them up a second time or falling back to the receipt.
      setPayAgainState({
        status: "changed",
        was: receipt.id,
        now,
        name: (answer.user && answer.user.fullName) || receipt.name || "",
        user: answer.user || null
      });
    } catch (err) {
      const message = (err && err.message) || "";
      // The route answers 404 with its own sentence; anything that is not a
      // 404 is a failure to ask, not an answer.
      const notFound = (err && (err.status === 404 || err.code === "payee_not_found"))
        || /could not find where it went/i.test(message);
      setPayAgainState(notFound ? { status: "gone" } : { status: "unreachable", message });
    }
  };
  // Which way the money went on the tab being read, and therefore which head
  // the ticket wears. `tint` still exists above and still colours the rate
  // and the share figures in the rows; it is the hero that stopped using it.
  const heroIsCredit = onShareTab ? shareIsCredit : !paymentIsSent;
  const heroGradient = heroIsCredit ? RECEIPT_HERO_IN : RECEIPT_HERO_OUT;
  const stampColor = receipt.status === "pending" || receipt.status === "simulated" ? "#B45309" : T.positive;
  const paymentStamp = receipt.status === "pending"
    ? "PENDING"
    : receipt.status === "simulated" ? "NOT SENT" : "COMPLETED";
  const shareStamp = shareIsCredit ? "CREDITED" : "SHARED";
  const ticketStamp = onShareTab ? shareStamp : paymentStamp;
  // The line under the figure. On the payment tab it names the share the
  // payment carried; on the share tab, the rate it came from. Drawn only when
  // there is really one — see hasShareEvent.
  const heroChip = onShareTab
    ? (displayShareRate == null ? "" : `${receipt.name || "They"} share${/s$/i.test(String(receipt.name || "")) ? "" : "s"} ${displayShareRate.toFixed(2)}% of every payment`)
    : (hasShareEvent && !canReveal && shownShareAmount > 0
      // This chip is a SENTENCE ("Creator share 18.33€ │ EUR back"), and it
      // used to be the argument for leaving the bar off — the words around
      // the figure already say what it is, so a bar read as breaking the
      // sentence in half.
      //
      // THAT RULE IS REVERSED, by the founder, in the words that prompted
      // this pass: "i still saw many places that geu is not together with
      // local unit and some place local unit is not connected with geu".
      //
      // The old rule was wrong in a way worth writing down, because it
      // sounds reasonable. "The sentence says what it is" is true of the
      // WORDS and false of the UNIT: "Creator share 18.33 back" with the
      // toggle on names no currency at all, and a reader supplies their own.
      // A sentence is not a context that makes a figure safe to half-label;
      // it is just a context where the second name is less convenient to
      // set. Convenience was doing the arguing.
      //
      // So the bar goes on here too, and the sentence carries it. Where the
      // figure sits inside running type the TRAIL IS SET SMALLER rather than
      // dropped — see GeuFigure — which is the founder's own answer to how
      // the pair should sit in a sentence. This particular string is handed
      // to a share sheet rather than drawn by us, so it gets the one-size
      // form; everything the app draws itself gets the two-size one.
      ? `Creator share ${geuLensBarMoney(shownShareAmount, shareCurrency, lens, viewerCurrency)} ${shareIsCredit ? "back" : "shared"}`
      : "");
  const dateTimeValue = [receipt.date, receipt.time].filter(Boolean).join(" \xB7 ");
  // A figure in a row, with its currency spelled out beside it.
  //
  // fmtMoney draws the SYMBOL, and a symbol is not a currency: ₹ is shared by
  // India, Pakistan, Nepal, Sri Lanka and Mauritius, $ by more than twenty,
  // kr by four. The hero has carried its code under the figure since it was
  // written; the rows had nothing, so on a cross-border receipt — the only
  // kind this app makes — "18.33€ / 2,000.00₹" left the reader to guess which
  // rupee and which euro. Suppressed where fmtMoney already ends in the code,
  // which is what it does for currencies with no symbol of their own
  // ("1,450.25 CHF"); printing it twice reads as a mistake.
  // This is now geuLensBarMoney and nothing else, and that is a tidy-up
  // rather than a change of mind. The rule this function worked out by hand
  // — rename only the reader's own money, otherwise name the currency, and
  // suppress the name where the figure already ends in it — is the rule
  // geuLensBarMoney applies app-wide. Two copies of one rule is one chance
  // for them to drift, and a receipt is the document somebody keeps.
  //
  // What a reader sees change: "18.33€ EUR" becomes "18.33€ │ EUR" (same
  // facts, the punctuation every other figure in the app now uses), and the
  // reader's OWN figure gains the unit it is not being read in —
  // "2,000.00₹ │ GEU", flipping to "2,000.00 GEU │ ₹". A renamed figure used
  // to carry nothing after it, which was defensible on its own and is not
  // once every other screen names both units.
  const moneyCoded = (amount, code) => geuLensBarMoney(amount, code, lens, viewerCurrency);
  return <div
    role="dialog"
    aria-modal="true"
    aria-label="Transaction receipt"
    style={{
      position: "fixed",
      inset: 0,
      zIndex: 500,
      background: T.bg,
      display: "flex",
      alignItems: "stretch",
      justifyContent: "center",
      animation: "receipt-overlay-in 0.2s ease"
    }}
  >{
    /* A SCREEN, not a bottom sheet.
       It was a sheet at 88vh with a grab handle and a dimmed backdrop you
       could tap to dismiss. A receipt is a document people read top to
       bottom, switch tabs on and send to somebody — and at 88vh the last
       thing on it was always half under the fold.
       The backdrop tap went with it. There is no "outside" on a full screen,
       and a dismiss gesture with nothing visible to aim at is a way to lose
       a receipt by accident. Back is the way out, and it is drawn. */
  }<style>{`
        @keyframes receipt-overlay-in { from { opacity: 0; } to { opacity: 1; } }
        @keyframes receipt-sheet-up { from { transform: translateY(14px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .rcpt-rows > div:not(.rcpt-sec):not(.rcpt-sub) { padding: 7px 0; border-bottom: 1px solid ${T.line}; }
        .rcpt-sub > div { padding: 7px 0; border-bottom: 1px solid ${T.line}; }
        .rcpt-rows > div:not(.rcpt-sec):last-child, .rcpt-sub > div:last-child { border-bottom: none; }
        .rcpt-rows .rcpt-note { border-bottom: none; }
      `}</style><div
    style={{
      width: "100%",
      maxWidth: 430,
      height: "100%",
      background: T.bg,
      position: "relative",
      display: "flex",
      flexDirection: "column",
      animation: "receipt-sheet-up 0.24s cubic-bezier(.32,.72,0,1)"
    }}
  >{
    /* Header: back, and the two tabs. No "Receipt" word — the tab that is
       lit says which document you are on, and it says it in the one place
       you can also change it from. A title above a toggle repeated the
       toggle's job and took a line to do it. */
  }<div style={{
      display: "flex",
      alignItems: "center",
      gap: 10,
      padding: "calc(10px + env(safe-area-inset-top, 0px)) 12px 8px",
      flexShrink: 0
    }}
  >{
    /* The app's one back button, not a second one drawn here. Same circle,
       same glyph, same size as the twenty other screens that have one —
       navButtons.jsx exists because there used to be several. */
  }<NavBackButton onClick={onClose} />{
    /* A COIN receipt has one document, so it gets a name rather than a
       toggle: a lone tab is not a toggle, it is a button that does nothing.
       Everything else gets Payment and — when the payment really carried a
       share — Creator Share. */
  }{showReceiptTabs ? <div style={{ display: "flex", flex: 1, gap: 4, padding: 3, borderRadius: 999, background: T.surfaceAlt, boxShadow: "inset 0 1px 2px rgba(76,29,149,0.06)" }}><ReceiptTabButton
    label={tabLabel(leadingTab)}
    active={leadingTab === "share" ? onShareTab : !onShareTab}
    onSelect={() => setReceiptTab(leadingTab)}
  /><ReceiptTabButton
    label={tabLabel(trailingTab)}
    active={trailingTab === "share" ? onShareTab : !onShareTab}
    onSelect={() => setReceiptTab(trailingTab)}
  /></div> : <span style={{ fontSize: 15, fontWeight: 800, color: T.ink }}>{tabLabel(leadingTab)}</span>}</div>{
    /* The document. It scrolls if it has to, but the whole point of the
       tighter rows is that on an ordinary payment it does not have to: one
       screen, one screenshot. */
  }<div style={{
      flex: 1,
      minHeight: 0,
      overflowY: "auto",
      WebkitOverflowScrolling: "touch",
      padding: "4px 12px calc(10px + env(safe-area-inset-bottom, 0px))",
      display: "flex",
      flexDirection: "column",
      gap: 10
    }}
  ><div
    data-testid="receipt-ticket"
    style={{
      background: T.surface,
      borderRadius: T.radiusXl,
      overflow: "hidden",
      position: "relative",
      boxShadow: T.shadowCard,
      // Never squeezed.
      //
      // This is a flex child of a scrolling column, so by default it SHRINKS
      // to make room for whatever is under it — and because it also clips its
      // own overflow, shrinking cut the ticket off mid-row: a receipt ending
      // halfway through "Date · Time" with the buttons sitting under the cut.
      // The column scrolls; the document does not shorten itself.
      flexShrink: 0
    }}
  >{
    /* ── The head of the ticket ──────────────────────────────────────────
       Our mark in one corner, the counterparty's flag in the other, the
       wordmark between them, and under it the one figure this document is
       about. */
  }<div style={{ padding: "12px 14px 14px", color: "#fff", textAlign: "center", background: heroGradient }}><div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center", minHeight: 30, padding: "0 42px" }}><span style={{ position: "absolute", left: 0, top: 0 }}><GH2HFlipCircle size={28} /></span><span style={{ fontSize: 14, letterSpacing: 2.2, fontFamily: T.fontWordmark }}><GloobalWordmark /></span>{
    /* The same FlagEmoji every other flag in this app is, cut to a disc.
       Never the emoji character: on any platform without flag glyphs
       (Windows above all) that is not a flag, it is the two
       regional-indicator letters sitting where a flag should be.
       One flag for the whole document: the person named on the Payment tab
       is the person shared with on the Creator Share tab. */
  }{receipt.flag && <span
    data-testid="receipt-flag"
    style={{ position: "absolute", right: 0, top: 0, display: "flex", borderRadius: "50%", boxShadow: "0 0 0 2px rgba(255,255,255,0.85), 0 2px 8px rgba(20,10,50,0.25)" }}
  ><FlagEmoji
    flag={receipt.flag}
    shape="circle"
    size={28}
    fit="cover"
  /></span>}</div><div style={{ fontSize: 9.5, fontWeight: 800, letterSpacing: 2.2, opacity: 0.85, marginTop: 9, textTransform: "uppercase" }}>{!onShareTab ? (isCoinReceipt
    ? /* Never "Money received" on a coin buy. Money did not arrive — it
         LEFT, and coin arrived in its place. The hero figure below is the
         coin, so the line above it has to name the exchange rather than
         describe a direction that is true of the coin and false of the
         money. The receipt's own title is that name. */
      receipt.title || "GLOOBAL Coin"
    : paymentKnown ? (paymentIsSent ? "Money sent" : "Money received") : "Payment not available") : shareIsCredit ? "Creator share earned" : "You share back"}</div><div style={{ marginTop: 1 }}>{!onShareTab ? (paymentKnown ? <div
    style={{
      fontSize: heroPayment.size,
      fontWeight: 800,
      color: "#fff",
      fontFamily: T.fontDisplay,
      lineHeight: 1.15,
      letterSpacing: -0.5,
      overflowWrap: "anywhere"
    }}
    data-testid="receipt-hero-payment"
  >{paymentIsSent ? "\u2212" : "+"}{heroPayment.lead}{heroPayment.trail && <span
    style={{ fontSize: geuLensTrailSize(heroPayment.size), fontWeight: 800 }}
  > {heroPayment.trail}</span>}</div> : <div
    style={{ fontSize: 12.5, fontWeight: 700, color: "rgba(255,255,255,0.88)", lineHeight: 1.4, padding: "6px 0" }}
    data-testid="receipt-payment-unavailable"
  >{
    /* The payment row is not on this device. Saying so is the only honest
       option: the share and its rate are both known, so the payment COULD
       be reconstructed by division — and that is exactly the figure that
       would be quietly wrong for every share that rounded. */
  }This payment isn't on this device. The Creator Share above is complete.</div>) : <div
    style={{
      fontSize: heroShare.size,
      fontWeight: 800,
      color: "#fff",
      fontFamily: T.fontDisplay,
      lineHeight: 1.15,
      letterSpacing: -0.5,
      overflowWrap: "anywhere"
    }}
    data-testid="receipt-hero-share"
  >{shareIsCredit ? "+" : "\u2212"}{heroShare.lead}{heroShare.trail && <span
    style={{ fontSize: geuLensTrailSize(heroShare.size), fontWeight: 800 }}
  > {heroShare.trail}</span>}</div>}{
    /* The currency CODE under the figure.
       fmtMoney draws the symbol, and a symbol is not the currency: ₹ is
       shared by India, Pakistan, Nepal, Sri Lanka and Mauritius, $ by more
       than twenty, and kr by four. On a cross-border receipt — the only kind
       this app makes — "1,106.61₹" alone does not say which rupee left the
       account, and this is the document somebody keeps.
       Suppressed when the formatted figure already ends in the code, which
       is what fmtMoney does for currencies with no symbol of their own. */
  }{heroCurrencyCode && <div
    data-testid="receipt-hero-currency"
    style={{ fontSize: 10.5, fontWeight: 700, color: "rgba(255,255,255,0.8)", letterSpacing: 0.6, marginTop: 1 }}
  >{heroCurrencyCode}</div>}</div>{heroChip && <span
    data-testid="receipt-hero-chip"
    style={{ display: "inline-flex", alignItems: "center", gap: 5, marginTop: 8, padding: "5px 11px", borderRadius: 999, background: "rgba(255,255,255,0.18)", fontSize: 10.5, fontWeight: 800 }}
  >{heroChip}</span>}</div><ReceiptTicketTear />{
    /* ── The rows ────────────────────────────────────────────────────────
       Hairlines between them rather than a box around each group, which is
       what lets the whole receipt fit one screen. The section headings do
       the grouping the boxes used to. */
  }<div className="rcpt-rows" style={{ padding: "0 16px 6px" }}>{!onShareTab ? <>{
    /* Who it's to/from, and their Gloobal ID if there is one. */
  }<ReceiptSectionLabel stamp={ticketStamp} stampColor={stampColor}>Who</ReceiptSectionLabel><ReceiptRow
    testId="receipt-counterparty"
    // paymentIsSent, not isSent. This tab describes the PAYMENT, and on a
    // Creator Share receipt `direction` describes the share — so a share Jio
    // sent me read "From Jio" on a tab about money I sent TO Jio.
    label={paymentIsSent ? "To" : "From"}
    value={receipt.name}
  />{receipt.id && <ReceiptRow
    testId="receipt-counterparty-id"
    label={<GloobalWordmark suffix=" ID" />}
    value={<ColoredGloobalId id={receipt.id} />}
    mono
  />}{
    /* The holder, and the other leg of a coin exchange.

       Only on a coin receipt, and it carries the three facts a coin buy
       could not previously answer: who bought it, under which Gloobal ID,
       from which country — none of which the movement itself records, since
       they are properties of the account — and then what the coin cost, in
       real money, at the rate it actually converted at.

       The rate is printed in the direction it was RECORDED. The mint route
       stores GEU-per-fiat and the redeem route stores fiat-per-GEU under the
       same field name; coinRateSentence reads the basis the server now sends
       and writes the matching sentence rather than inverting one into the
       other. Inverting means dividing, and one over a rounded rate is a
       number that does not reproduce the two amounts printed above it. */
  }{isCoinReceipt && <ReceiptSectionLabel>Coin</ReceiptSectionLabel>}{isCoinReceipt && <div
    data-testid="receipt-coin"
    className="rcpt-sub"
  >{receipt.holderName && <ReceiptRow label="Held by" value={receipt.holderName} />}{receipt.holderSymbolId && <ReceiptRow
    label={<GloobalWordmark suffix=" ID" />}
    value={<ColoredGloobalId id={receipt.holderSymbolId} />}
    mono
  />}{receipt.holderCountryName && <ReceiptRow
    label="Country"
    value={receipt.holderCountryName}
    flag={receipt.holderCountryFlag}
  />}{
    /* The fiat leg. Absent on a send, which moves no money at all — and
       absent rather than shown as zero, because a zero here would read as
       "this cost nothing" rather than "no money was involved". */
  }{receipt.fiatAmount != null && receipt.fiatCurrencyCode && <ReceiptRow
    label={receipt.fiatDirection === "out" ? "Paid" : "Received"}
    value={moneyCoded(receipt.fiatAmount, receipt.fiatCurrencyCode)}
  />}<ReceiptRow
    label={receipt.fiatDirection === "out" ? "Coin bought" : receipt.fiatDirection === "in" ? "Coin sold" : "Coin moved"}
    value={`${fmt(receipt.amount)} ${receipt.currencyCode}`}
  />{coinRateLine && <ReceiptRow label="Rate applied" value={coinRateLine} accent />}{coinRateLine && <div className="rcpt-note" style={{ fontSize: 10, fontWeight: 600, color: T.inkFaint, lineHeight: 1.4, paddingTop: 6 }}>{
    /* The same sentence the payment receipt's conversion block carries, for
       the same reason: a rate with no date attached is one the reader takes
       to be today's. */
  }As converted at the time of this transaction, not a current rate.</div>}</div>}{
    /* What this transaction was exchanged at.

       Drawn only when the two sides really are different currencies. A
       "conversion" block on a domestic payment showing 1.000000 states that
       an exchange took place, and none did. Every figure is a recorded one,
       read through receiptCurrency.js so the screen, the shared picture and
       the audit PDF cannot disagree about it. */
  }{paymentConversion && <ReceiptSectionLabel>Money</ReceiptSectionLabel>}{paymentConversion && <div
    data-testid="receipt-conversion"
    className="rcpt-sub"
  ><ReceiptRow
    label="Sender paid"
    value={moneyCoded(paymentConversion.paidAmount, paymentConversion.paidCurrency)}
  /><ReceiptRow
    label="Receiver got"
    value={moneyCoded(paymentConversion.gotAmount, paymentConversion.gotCurrency)}
  />{paymentConversion.rateLabel && <ReceiptRow label="Rate applied" value={paymentConversion.rateLabel} accent />}<div className="rcpt-note" style={{ fontSize: 10, fontWeight: 600, color: T.inkFaint, lineHeight: 1.4, paddingTop: 6 }}>{
    /* A rate with no date attached is a rate the reader assumes is today's.
       This one is the rate the payment settled at, and saying so is the
       difference between a record and an estimate. */
  }As settled at the time of this transaction, not a current rate.</div></div>}<ReceiptSectionLabel>Proof</ReceiptSectionLabel>{receipt.method && <ReceiptRow label="Method" value={receipt.method} />}<ReceiptRow label={"Date \xB7 Time"} value={dateTimeValue} /></> : <>{
    /* The Creator Share's own document: the arithmetic, where it went, and
       who it came from. Rate and amount are shown even at 0 rather than the
       tab disappearing — a 0% share is still a real, reportable outcome. */
  }<ReceiptSectionLabel stamp={ticketStamp} stampColor={stampColor}>How it was worked out</ReceiptSectionLabel><ReceiptRow
    label="From payment"
    value={paymentKnown ? moneyCoded(paymentAmount, paymentCurrency) : "Not on this device"}
    testId="receipt-share-from-payment"
  /><ReceiptRow
    label="Creator Share rate"
    value={displayShareRate == null ? "\u2014" : `${displayShareRate.toFixed(2)}%`}
    accent
  />{
    /* Credit when I sent (the receiver shares back to me), debit when I
       received (I share back to them) — same direction as the figure above,
       always my own currency, since it is always my account the share
       settles into or out of. */
  }<ReceiptRow
    label={shareIsCredit ? "Your share" : "You shared"}
    value={`${shareIsCredit ? "+" : "\u2212"}${moneyCoded(shownShareAmount, shareCurrency)}`}
    accent
  />{
    /* The share's own currency conversion, when it crossed one.

       The payee gives the share in their currency and the payer gets it in
       theirs; both figures are recorded, and the rate is the payment's own.
       Absent on a same-currency share, and absent — rather than worked out —
       when either side was never recorded (a legacy row, or the receipt shown
       straight after paying, whose response carries only the payer's side). */
  }{shareConversion && <ReceiptSectionLabel>Conversion</ReceiptSectionLabel>}{shareConversion && <div
    data-testid="receipt-share-conversion"
    className="rcpt-sub"
  ><ReceiptRow
    label="Share given"
    value={moneyCoded(shareConversion.paidAmount, shareConversion.paidCurrency)}
  /><ReceiptRow
    label="Share received"
    value={moneyCoded(shareConversion.gotAmount, shareConversion.gotCurrency)}
  />{shareConversion.rateLabel && <ReceiptRow label="Rate applied" value={shareConversion.rateLabel} accent />}<div className="rcpt-note" style={{ fontSize: 10, fontWeight: 600, color: T.inkFaint, lineHeight: 1.4, paddingTop: 6 }}>
      As settled at the time of this transaction, not a current rate.
    </div></div>}<ReceiptSectionLabel>Where it went</ReceiptSectionLabel><ReceiptRow label={shareIsCredit ? "Credited to" : "Taken from"} value={shareDestinationName} /><ReceiptRow label={"Date \xB7 Time"} value={dateTimeValue} /><ReceiptSectionLabel>Who</ReceiptSectionLabel><ReceiptRow label={shareIsCredit ? "Shared back to" : "You shared back to"} value={shareIsCredit ? "You" : receipt.name} />{
    /* Who the other side of the share is, by name and by ID.

       When I RECEIVED the payment, the row above already names the person I
       shared back to. When I SENT it, the row above says "You" — the share
       came back to me — so the counterparty needs naming before their ID can
       be attached to anything. Hence the extra row in that direction only:
       receipt.id belongs to receipt.name in both cases, and it must sit under
       the row that names them, never under "You". */
  }{shareIsCredit && <ReceiptRow label="Shared back by" value={receipt.name} />}{receipt.id && <ReceiptRow
    testId="receipt-share-counterparty-id"
    label={<GloobalWordmark suffix=" ID" />}
    value={<ColoredGloobalId id={receipt.id} />}
    mono
  />}</>}{
    /* Transaction ID — twenty symbols in one row, inside a dashed box at the
       foot of the ticket. Each tab shows ITS OWN reference: the payment and
       its Creator Share are two movements between two different pairs of
       parties, and the server mints each with its own. There is no fallback
       to the other one's — a blank looks broken, but printing the payment's
       id on the share tab is a false statement about which transaction you
       are holding. */
  }{rawTxnId && <div
    className="rcpt-note"
    style={{
      position: "relative",
      margin: "8px 0 4px",
      padding: "8px 10px 9px",
      borderRadius: 14,
      border: `1px dashed ${T.line}`
    }}
  >{
    /* The label, the copy control and the symbols are three DIRECT children
       of this box, and that is load-bearing rather than incidental: the
       browser tests find the reference by looking for the label and then for
       the monospace row inside the label's own parent. Nesting the label with
       the button in a flex row of their own hid the symbols from that walk —
       and from anything else reading the receipt structurally. */
  }<span style={{ display: "block", textAlign: "center", fontSize: 9, fontWeight: 800, color: T.inkFaint, letterSpacing: 1.5, textTransform: "uppercase" }}>{showingShare ? "Share transaction ID" : "Transaction ID"}</span><button
    onClick={handleCopyTxnId}
    aria-label="Copy transaction ID"
    className="v2-tap"
    style={{
      position: "absolute",
      top: 4,
      right: 6,
      width: 20,
      height: 20,
      borderRadius: "50%",
      border: "none",
      background: "transparent",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      cursor: "pointer",
      padding: 0
    }}
  >{copied ? <Check size={12} color={T.positive} /> : <Copy size={12} color={T.inkFaint} />}</button><div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 1, marginTop: 5, fontFamily: "monospace", fontSize: 12.5, fontWeight: 800 }}>{rawTxnId.split("").map((ch, i) => <span key={i} style={{ flexShrink: 0, color: POSITION_COLORS[(i + txnColorOffset) % POSITION_COLORS.length], transition: "color 0.4s ease" }}>{ch}</span>)}</div></div>}</div></div>{
    /* Simulated payments say so outside the ticket, not inside it: the
       ticket is the record, and this is a warning about the record. */
  }{receipt.status === "simulated" && <div
    role="alert"
    style={{
      display: "flex",
      alignItems: "center",
      gap: 8,
      padding: "10px 12px",
      borderRadius: 12,
      background: "#FEF3C7",
      border: "1px solid #F5D68A",
      color: "#8A5A00",
      fontSize: 11.5,
      fontWeight: 700,
      lineHeight: 1.35
    }}
  ><span aria-hidden="true">⚠️</span><span>This recipient wasn't a registered <GloobalWordmark /> account, so nothing was actually sent — this receipt reflects a local simulation only.</span></div>}{shareFeedback && <div
    role="status"
    data-testid="receipt-share-feedback"
    style={{ fontSize: 11.5, fontWeight: 700, color: T.inkSoft, textAlign: "center", lineHeight: 1.4 }}
  >{shareFeedback}</div>}{
    /* Provenance & complaint window — each viewer only ever sees their OWN
       resolved city/state (never the other party's), plus a short, explicit
       window to report an issue. Reporting opens a case; it never reverses
       money or flags fraud automatically. */
  }{

    /* Audit, Share, Pay again — three icons rather than three sentences.
       There is no Done: back is the only way out of a document, and a second
       control that does the same thing is a decision nobody asked to make. */
  }<div style={{ display: "flex", gap: 7, flexShrink: 0 }}><ReceiptIconAction
    testId="receipt-audit-report"
    icon={<FileText size={20} color={T.accent} />}
    label={auditBusy ? "Preparing…" : "Audit"}
    disabled={auditBusy}
    busy={auditBusy}
    onClick={async () => {
      if (auditBusy) return;
      setAuditBusy(true);
      try {
        await shareAuditReport(receipt, { generatedAt: formatAuditTimestamp() });
      } finally {
        setAuditBusy(false);
      }
    }}
  />{
    /* ── THE SHOP'S STORE ─────────────────────────────────────────────
       On a payment made to a shop (paid at its creator name), one tap into
       that shop's store — its items and prices. Not on personal payments,
       and not on the Creator Share tab. App closes whatever screen the
       receipt sits on and the dashboard opens the store (gloobal:openShop). */
  }{receipt && receipt.creatorHandle && !onShareTab ? <ReceiptIconAction
    testId="receipt-open-store"
    ariaLabel={`Open the store of ${receipt.creatorHandle}`}
    icon={<StoreReceipt size={20} color={T.accent} />}
    label="Store"
    onClick={() => {
      window.dispatchEvent(new CustomEvent("gloobal:openShop", { detail: { handle: receipt.creatorHandle } }));
      if (onClose) onClose();
    }}
  /> : null}<ReceiptIconAction
    testId="receipt-share-image"
    ariaLabel="Share receipt image"
    icon={<Share2 size={20} color={T.accent} />}
    label="Share"
    disabled={imageShareBusy}
    busy={imageShareBusy}
    onClick={handleShareReceiptImage}
  />{
    /* Where it happened, and how to complain about it — two icons rather than
       a card of their own under the ticket.
       They were a bordered box carrying one line of text and a full-width
       button, which on a cross-border receipt pushed the ticket into a scroll
       nobody was expecting. Both are one tap here, and both open in the line
       under this row rather than taking permanent space: the place is a fact
       most people never need, and the complaint is a door most people never
       open. */
  }{myLocation && <ReceiptIconAction
    testId="receipt-where"
    icon={<MapPin size={20} color={T.accent} />}
    label="Where"
    onClick={() => setDetail((d) => (d === "where" ? null : "where"))}
  />}{canComplain && <ReceiptIconAction
    testId="receipt-complain"
    icon={<CpComplaintIcon size={20} color={T.negative} />}
    label="Complain"
    onClick={() => { setComplaintError(""); setComplaintOpen(true); }}
  />}{!canComplain && canReport && <ReceiptIconAction
    testId="receipt-report"
    icon={reportSubmitted ? <Check size={20} color={T.positive} /> : <FlagIcon2 size={20} color={T.accent} />}
    label={reportSubmitted ? "Reported" : "Report"}
    onClick={() => setDetail((d) => (d === "report" ? null : "report"))}
  />}{canPayAgain && <ReceiptIconAction
    testId="receipt-pay-again"
    icon={<RefreshCw7 size={20} color="#fff" />}
    label={payAgainState && payAgainState.status === "checking"
      ? "Checking…"
      : paymentIsSent ? "Pay again" : "Pay back"}
    solid
    busy={!!(payAgainState && payAgainState.status === "checking")}
    onClick={handlePayAgain}
  />}</div>{
    /* What the check found, when it found something worth stopping for.
       Nothing is drawn while the ID is still theirs — the payment screen is
       already opening, and a panel that flashed "still correct" would make
       the common case feel like an interruption. */
  }{payAgainState && payAgainState.status === "changed" && <div
    data-testid="receipt-id-changed"
    style={{ display: "flex", flexDirection: "column", gap: 9, padding: "12px 13px", borderRadius: 12, background: T.surface, border: `1px solid ${T.line}`, flexShrink: 0 }}
  ><p style={{ fontSize: 11.5, color: T.inkSoft, fontWeight: 700, lineHeight: 1.45, margin: 0 }}
  >{`${payAgainState.name || "Their"}${/s$/i.test(String(payAgainState.name || "")) ? "'" : "'s"} GLOOBAL ID has changed since this payment.`}</p><div
    style={{ display: "flex", flexDirection: "column", gap: 6 }}
  >{[["was", payAgainState.was, T.inkFaint], ["now", payAgainState.now, T.ink]].map(([label, symbols, tint]) => <div
    key={label}
    style={{ display: "flex", alignItems: "center", gap: 8 }}
  ><span style={{ fontSize: 10.5, fontWeight: 800, color: T.inkFaint, width: 26, flexShrink: 0 }}>{label}</span><span
    data-testid={`receipt-id-${label}`}
    style={{ display: "flex", flexWrap: "wrap", gap: 3, opacity: label === "was" ? 0.55 : 1 }}
  >{String(symbols || "").split("").map((ch, i) => <span
    key={i}
    style={{ fontFamily: "monospace", fontSize: 13.5, fontWeight: 800, color: label === "was" ? tint : POSITION_COLORS[i % POSITION_COLORS.length] }}
  >{ch}</span>)}</span></div>)}</div><div
    style={{ display: "flex", gap: 8 }}
  ><button
    data-testid="receipt-id-changed-cancel"
    onClick={() => setPayAgainState(null)}
    className="v2-tap"
    style={{ flex: 1, minHeight: 40, borderRadius: 999, border: `1px solid ${T.line}`, background: T.surface, color: T.inkSoft, fontSize: 12.5, fontWeight: 800, cursor: "pointer" }}
  >Cancel</button><button
    data-testid="receipt-id-changed-go"
    onClick={() => { const next = payAgainState.now; const resolved = payAgainState.user; setPayAgainState(null); openSendMoney(next, resolved); }}
    className="v2-tap"
    style={{ flex: 1, minHeight: 40, borderRadius: 999, border: "none", background: T.gradButton, color: "#fff", fontSize: 12.5, fontWeight: 800, cursor: "pointer" }}
  >{`Pay ${payAgainState.name ? payAgainState.name.split(" ")[0] : "them"}`}</button></div></div>}{payAgainState && (payAgainState.status === "gone" || payAgainState.status === "unreachable") && <p
    data-testid="receipt-pay-again-problem"
    role="status"
    style={{ fontSize: 11.5, fontWeight: 700, color: T.inkSoft, textAlign: "center", lineHeight: 1.45, flexShrink: 0 }}
  >{payAgainState.status === "gone"
    ? "That GLOOBAL ID has changed and we couldn't find where it went. Ask them for their current one."
    : "Couldn't check their GLOOBAL ID just now. Try again in a moment."}</p>}{
    /* What the two of them have to say, in one line under the row. */
  }{detail === "where" && myLocation && <div
    data-testid="receipt-where-line"
    style={{ fontSize: 11.5, fontWeight: 700, color: T.inkSoft, textAlign: "center", lineHeight: 1.45, flexShrink: 0 }}
  >{`Completed near ${myLocation.city}${myLocation.state ? `, ${myLocation.state}` : ""}${myLocation.approximate ? " (approx.)" : ""}`}</div>}{detail === "report" && <div
    data-testid="receipt-report-line"
    style={{ display: "flex", flexDirection: "column", gap: 8, padding: "10px 12px", borderRadius: 12, background: T.surface, border: `1px solid ${T.line}`, flexShrink: 0 }}
  >{reportSubmitted ? <p style={{ fontSize: 11.5, color: T.positive, fontWeight: 700, lineHeight: 1.45, margin: 0 }}>
          Reported — a case has been opened. This doesn't change your balance or eligibility; the other side has up to 24 hours to respond.
        </p> : withinComplaintWindow ? <>
        <p style={{ fontSize: 11.5, color: T.inkSoft, fontWeight: 700, lineHeight: 1.45, margin: 0 }}>
          Something wrong with this payment? Opening a case does not move any money — the other side has 24 hours to respond.
        </p><button
    onClick={handleReportIssue}
    className="v2-tap"
    style={{ width: "100%", padding: "9px 0", borderRadius: 12, border: `1px solid ${T.line}`, background: T.surfaceAlt, color: T.ink, fontSize: 12.5, fontWeight: 800, cursor: "pointer" }}
  >Report an issue</button></> : <p style={{ fontSize: 11.5, color: T.inkFaint, fontWeight: 700, margin: 0 }}>
          The verification window for this transaction has closed.
        </p>}</div>}{
    /* Reveal my share.
       Offered only when this payment really carried a Creator Share, and only
       while it is still a surprise — `onRevealShare` is passed by the screen
       that has just paid, and never by History, so a receipt reopened a week
       later simply has its Creator Share tab and no coupon.
       It sits UNDER the receipt rather than on it: the receipt is a record and
       is complete without this. This is the part that is for fun. */
  }{canReveal && <button
    onClick={onRevealShare}
    data-testid="receipt-reveal-share"
    className="v2-tap"
    style={{
      marginTop: 10,
      width: "100%",
      minHeight: 52,
      borderRadius: 16,
      border: "none",
      background: T.gradButton,
      color: "#fff",
      fontSize: 14.5,
      fontWeight: 800,
      cursor: "pointer",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      gap: 8,
      boxShadow: "0 12px 26px -16px rgba(76,29,149,0.9)"
    }}
  ><Eye size={17} aria-hidden="true" />Reveal my share</button>}{
    /* What the document is signed with.
       One line, not two: the tagline that used to sit under it is on the
       screens that introduce the app, and a receipt is not the place to be
       introduced to anything. */
  }<div style={{ marginTop: "auto", textAlign: "center", padding: "12px 0 4px" }}><div style={{ fontSize: 11.5, letterSpacing: 1.2, color: T.ink }}><HoomanMark /></div></div></div></div>{
    /* The complaint flow. Only the person who PAID raises one from a
       receipt: the person who was paid sees it under Profile → Complaints &
       reports, with the reason, and answers it there. */
  }<ComplaintReasonSheet
    open={complaintOpen}
    payment={{ name: receipt.name || "", when: [receipt.date, receipt.time].filter(Boolean).join(" · "), amountText: geuLensBarMoney(Number(paymentAmount) || 0, paymentCurrency || "", lens, viewerCurrency) }}
    busy={complaintBusy}
    error={complaintError}
    onClose={() => setComplaintOpen(false)}
    onRaise={raiseComplaint}
  /><ComplaintRaisedSheet
    open={Boolean(complaintRaised)}
    caseRef={complaintRaised && complaintRaised.ref}
    payment={{ name: receipt.name || "", when: [receipt.date, receipt.time].filter(Boolean).join(" · "), amountText: geuLensBarMoney(Number(paymentAmount) || 0, paymentCurrency || "", lens, viewerCurrency) }}
    onDone={() => setComplaintRaised(null)}
    onOpenChat={() => {
      const opened = complaintRaised;
      setComplaintRaised(null);
      if (typeof window !== "undefined" && opened) window.dispatchEvent(new CustomEvent("gloobal:openComplaint", { detail: { id: opened.id } }));
    }}
  /></div>;
}


// src/components/dialogs/PaymentProcessing.jsx
//
// The screen between "verified" and the receipt.
//
// ── Why there was nothing here ───────────────────────────────────────────
//
// There already is a state machine. SendMoney sets `transactionStatus` to
// idle / processing / failed / completed at six places, and until now the
// only thing that read it was a re-entry guard stopping a double-tap on Pay.
// Nothing drew it. So a payment went: verify, blank, receipt — and the blank
// is `await onRemoteSend(...)`, a real network call that on a sleeping Render
// instance can run for thirty seconds.
//
// This component does not invent that state. It renders the one that was
// already being tracked.
//
// ── Everything on this screen is true ────────────────────────────────────
//
// There are three stages listed now, and the rule that kept them off the
// screen before is the reason they are safe to draw: NOTHING here advances on
// a timer, and no stage claims to have happened until it has.
//
//   1. Verified it's you — already true when this screen opens. The PIN, and
//      the fingerprint after it, were taken before the POST was made.
//   2. Sending — true for exactly as long as this screen is up, because this
//      screen IS the request being in flight.
//   3. Settling — drawn grey, and it never ticks here. It cannot: the moment
//      the server answers, this screen is gone and the receipt is on top.
//      The receipt is the tick.
//
// So the list says what is known and stops. A third row that filled in after
// a couple of seconds would be the defect this codebase already names, in the
// comment about a biometric prompt that "was a 700ms setTimeout that always
// succeeded".
//
// The slow-line below is the same rule applied to reassurance. It appears
// only once the call really has been running longer than a payment usually
// takes, and what it then says — that the server may be waking up — is the
// actual most likely cause on this deployment.
var PROCESSING_SLOW_AFTER_MS = 6000;

